INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7aec29c-9275-402e-ac74-7f9e29c3cad4', '贈楊煉師', '贈楊煉師', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["紫煙衣上繡春雲，清隱山書小篆文。","明月在天將鳳管，夜深吹向玉晨君。"]', '["紫煙衣上繡春云，清隐山书小篆文。","明月在天將鳳管，夜深吹向玉晨君。"]', '诗', 'shi', '', NULL, '贈楊煉師 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f5537d-a83f-486a-87b3-51a730016dee', '玉清壇', '玉清壇', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["上陽宮裏女，玉色楚人多。","西信無因得，東遊奈樂何。"]', '["上陽宮裏女，玉色楚人多。","西信無因得，东游奈乐何。"]', '诗', 'shi', '', NULL, '玉清壇 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb50ed6-2410-476b-b0f8-a9fea5df2db0', '荅客', '荅客', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["竹間深路馬驚嘶，獨入蓬門半似迷。","勞問圃人終歲事，桔槔聲裏雨春畦。"]', '["竹间深路马驚嘶，独入蓬门半似迷。","勞问圃人終歲事，桔槔声裏雨春畦。"]', '诗', 'shi', '', NULL, '荅客 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c9f3a0-edb7-4a12-9ff5-b20468b1d296', '隋宮', '隋宮', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["柳塘煙起日西斜，竹浦風迴鴈弄沙。","煬帝春遊古城在，壞宮芳草滿人家。"]', '["柳塘煙起日西斜，竹浦风迴鴈弄沙。","煬帝春游古城在，壞宮芳草满人家。"]', '诗', 'shi', '', NULL, '隋宮 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5baca491-5a2d-480c-8596-58ec72b1c132', '送僧文江', '送僧文江', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["吳王劒池上，禪子石房深。","久慕白雲性，忽勞青玉音。","孤高知勝鶴，清雅似聞琴。","此韻書珍重，煩師出定吟。"]', '["吳王劒池上，禪子石房深。","久慕白云性，忽勞青玉音。","孤高知勝鹤，清雅似闻琴。","此韻书珍重，煩師出定吟。"]', '诗', 'shi', '', NULL, '送僧文江 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048b9758-1195-4367-b6b0-eb285e0e5d0a', '古意', '古意', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["重錦化爲泥，翦刀誤人事。","夜裁遠道書，翦破相思字。","妾心不自信，遠道終難寄。","客心固多疑，肯信非人意。","萬里不言遠，歸書長相次。","可即由此書，空房□忌諱。"]', '["重錦化爲泥，翦刀誤人事。","夜裁远道书，翦破相思字。","妾心不自信，远道終难寄。","客心固多疑，肯信非人意。","万里不言远，归书长相次。","可即由此书，空房□忌諱。"]', '诗', 'shi', '', NULL, '古意 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f32718-012e-449d-b4f7-877b0e9b7d29', '山中冬思二首 一', '山中冬思二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["山深先冬寒，敗葉與林齊。","門巷非世路，何人念窮棲。","哀風破山起，夕雪誤鳴雞。","巢鳥侵旦出，飢猨無聲啼。","晨興動煙火，開雲伐冰溪。","老木寒更瘦，陰雲晴亦低。","我貧自求力，顏色常低迷。","時思靈臺下，遊子正悽悽。"]', '["山深先冬寒，敗葉與林齊。","门巷非世路，何人念窮棲。","哀风破山起，夕雪誤鳴雞。","巢鸟侵旦出，飢猨無声啼。","晨兴动煙火，开云伐冰溪。","老木寒更瘦，陰云晴亦低。","我貧自求力，顏色常低迷。","时思靈台下，游子正悽悽。"]', '诗', 'shi', '', NULL, '山中冬思二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3ccca7-b611-4b71-9ab8-6f8ce1ec6889', '山中冬思二首 二', '山中冬思二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["雪壯冰亦堅，凍澗如平地。","幽人毛褐煖，笑就糟牀醉。","喚人空谷應，開火寒猨至。","拾薪煮秋栗，看鼎書古字。","忽憶南澗游，衣巾多雲氣。","露腳尋逸僧，諮量意中事。"]', '["雪壯冰亦堅，凍澗如平地。","幽人毛褐煖，笑就糟牀醉。","喚人空谷應，开火寒猨至。","拾薪煮秋栗，看鼎书古字。","忽憶南澗游，衣巾多云氣。","露腳尋逸僧，諮量意中事。"]', '诗', 'shi', '', NULL, '山中冬思二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da128ae-3425-4b49-9dd3-1c1cd99e9030', '讀史', '读史', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["鬼書報秦亡，天地亦云閉。","赤龍吟大野，老[母]哭白帝。","蒼蒼無白日，項氏徒先濟。","六合已姓劉，鴻門事難制。","坑降嬴政在，衣錦人望替。","宿昔見漢兵，龍蛇滿旌棨。","始矜山可拔，終歎騅不逝。","區區亞父心，未究天人際。","蕭張馬無汗，盛業垂千世。"]', '["鬼书報秦亡，天地亦云閉。","赤龙吟大野，老[母]哭白帝。","蒼蒼無白日，項氏徒先濟。","六合已姓劉，鴻门事难制。","坑降嬴政在，衣錦人望替。","宿昔见漢兵，龙蛇满旌棨。","始矜山可拔，終歎騅不逝。","區區亞父心，未究天人際。","蕭張马無汗，盛業垂千世。"]', '诗', 'shi', '', NULL, '讀史 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99450f4-44d1-4741-b219-ad93d4c39a9f', '冬夜荅客', '冬夜荅客', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["冬日誠可愛，不如夜漏多。","幸君霜露裏，車馬犯寒過。","學耕不逢年，稂莠敗黍禾。","豈唯親賓散，鳥鼠移巢窠。","獨見青松心，凌霜庇柔蘿。","壯日賤若此，留恩意如何。","因憶古丈夫，一言重山河。","臨風彈楚劒，爲子奏燕歌。"]', '["冬日誠可愛，不如夜漏多。","幸君霜露裏，车马犯寒過。","学耕不逢年，稂莠敗黍禾。","豈唯親賓散，鸟鼠移巢窠。","独见青松心，凌霜庇柔蘿。","壯日賤若此，留恩意如何。","因憶古丈夫，一言重山河。","臨风彈楚劒，爲子奏燕歌。"]', '诗', 'shi', '', NULL, '冬夜荅客 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d15b1f-3020-42cd-88bb-ff93302ca1e3', '宿吳興道中苕村', '宿吳兴道中苕村', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["浮客倦長道，秋深夜如年。","久行惜日月，常起雞鳴前。","夕計今日程，息車在苕川。","霜中水南寺，金磬泠泠然。","疇昔此林下，歸心巢頂禪。","身依寤昏寐，智月生虛圓。","羈旅違我程，去留難雙全。","觀身話往事，如夢遊青天。","明發止賓從，寄聲琴上弦。","聊書越人意，此曲名思仙。"]', '["浮客倦长道，秋深夜如年。","久行惜日月，常起雞鳴前。","夕計今日程，息车在苕川。","霜中水南寺，金磬泠泠然。","疇昔此林下，归心巢頂禪。","身依寤昏寐，智月生虛圓。","羈旅違我程，去留难雙全。","观身話往事，如梦游青天。","明發止賓從，寄声琴上弦。","聊书越人意，此曲名思仙。"]', '诗', 'shi', '', NULL, '宿吳興道中苕村 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb0c135-98b7-4108-98d6-b2b8c7ead862', '代楚老酬主人', '代楚老酬主人', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["流水爲我鄉，扁舟爲我宅。","二毛去天遠，幾日人間客。","曈曈銜山景，渺渺翔雲迹。","從時無定心，病處不煖席。","煩君問岐路，爲我生悽慽。","百年衣食身，未死皆有役。","曾傷無遺嗣，縱有復何益。","終古北邙山，樵人賣松栢。"]', '["流水爲我乡，扁舟爲我宅。","二毛去天远，幾日人间客。","曈曈銜山景，渺渺翔云迹。","從时無定心，病处不煖席。","煩君问岐路，爲我生悽慽。","百年衣食身，未死皆有役。","曾傷無遺嗣，縱有复何益。","終古北邙山，樵人賣松栢。"]', '诗', 'shi', '', NULL, '代楚老酬主人 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94984e1f-fc1c-4929-a9d3-9076382a0f0e', '沛中懷古', '沛中懷古', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["煙蕪歌風臺，此是赤帝鄉。","赤帝今已矣，大風邈淒涼。","惟昔仗孤劒，十年朝八荒。","人言生處樂，萬乘巡東方。","高臺何巍巍，行殿起中央。","興言萬代事，四坐沾衣裳。","我爲異代臣，酌水祀先王。","撫事復懷昔，臨風獨彷徨。"]', '["煙蕪歌风台，此是赤帝乡。","赤帝今已矣，大风邈淒涼。","惟昔仗孤劒，十年朝八荒。","人言生处乐，万乘巡东方。","高台何巍巍，行殿起中央。","兴言万代事，四坐沾衣裳。","我爲異代臣，酌水祀先王。","撫事复懷昔，臨风独彷徨。"]', '诗', 'shi', '', NULL, '沛中懷古 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce421446-8c4c-4e75-9c0d-b89b565057c8', '夏日華山別韓博士愈', '夏日华山別韓博士愈', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["別地泰華陰，孤亭潼關口。","夏日可畏時，望山易遲久。","暫因車馬倦，一逐雲先後。","碧霞氣爭寒，黃鳥相語誘。","三峰多異態，逈舉仙人手。","天晴捧日輪，月夕弄星斗。","幽疑白帝近，明見黃河走。","遠心不期來，真境非吾有。","鳥鳴草木下，日息天地右。","躑躅因風松，青冥謝仙叟。","不知無聲淚，中感一顏厚。","青霄上何階，別劒空朗扣。","故鄉此關外，身與名相守。","跡比斷根蓬，憂如長飲酒。","生離抱多恨，方寸安可受。","咫尺岐路分，蒼煙蔽回首。"]', '["別地泰华陰，孤亭潼关口。","夏日可畏时，望山易遲久。","暫因车马倦，一逐云先後。","碧霞氣爭寒，黄鸟相語誘。","三峰多異態，逈舉仙人手。","天晴捧日輪，月夕弄星斗。","幽疑白帝近，明见黄河走。","远心不期来，真境非吾有。","鸟鳴草木下，日息天地右。","躑躅因风松，青冥謝仙叟。","不知無声泪，中感一顏厚。","青霄上何階，別劒空朗扣。","故乡此关外，身與名相守。","跡比斷根蓬，憂如长饮酒。","生離抱多恨，方寸安可受。","咫尺岐路分，蒼煙蔽回首。"]', '诗', 'shi', '', NULL, '夏日華山別韓博士愈 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96e17da6-0e57-41c3-835a-eda786ed4948', '春日言懷', '春日言懷', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["湛湛琴前酒，期自賞青春。","胡爲緘笑語，深念不思身。","寂寂花舞多，嚶嚶鳥言頻。","心悲兄弟遠，願見相似人。","江界田土卑，競來東作勤。","歲寒虛盡力，家外無強親。","杳窅青雲望，無途同苦辛。"]', '["湛湛琴前酒，期自賞青春。","胡爲緘笑語，深念不思身。","寂寂花舞多，嚶嚶鸟言頻。","心悲兄弟远，願见相似人。","江界田土卑，競来东作勤。","歲寒虛尽力，家外無強親。","杳窅青云望，無途同苦辛。"]', '诗', 'shi', '', NULL, '春日言懷 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd09b97-63cc-41db-9fc7-71187e05f3c5', '題吳徵君巖居', '題吳徵君巖居', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["堯澤潤天下，許由心不知。","真風存綿緜，常與達者期。","有道吾不仕，有生吾不欺。","澹然靈府中，獨見太古時。","地脈發醴泉，巖根生靈芝。","天文若通會，星影應離離。","亭亭傅氏巖，何獨萬古思。"]', '["堯澤潤天下，許由心不知。","真风存綿緜，常與達者期。","有道吾不仕，有生吾不欺。","澹然靈府中，独见太古时。","地脈發醴泉，巖根生靈芝。","天文若通會，星影應離離。","亭亭傅氏巖，何独万古思。"]', '诗', 'shi', '', NULL, '題吳徵君巖居 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1603aba-6ded-4262-b4de-cb78a2d34bc1', '雲溪竹園翁', '云溪竹园翁', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["硠硠雲溪裏，翠竹和雲生。","古泉積澗深，竦竦如刻成。","楚客臥雲老，世間無姓名。","因茲千畝業，以代雙牛耕。","亂林不可留，寸莖不可輕。","風煖鬬出地，仰齊故年莖。","幽室結白茅，密葉羅衆清。","照水寒澹蕩，對山綠崢嶸。","蒼松含古貌，秋桂儼白英。","相看受天風，深夜戛擊聲。"]', '["硠硠云溪裏，翠竹和云生。","古泉積澗深，竦竦如刻成。","楚客臥云老，世间無姓名。","因茲千畝業，以代雙牛耕。","亂林不可留，寸莖不可轻。","风煖鬬出地，仰齊故年莖。","幽室結白茅，密葉羅衆清。","照水寒澹蕩，对山綠崢嶸。","蒼松含古貌，秋桂儼白英。","相看受天风，深夜戛擊声。"]', '诗', 'shi', '', NULL, '雲溪竹園翁 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b166a3e0-2841-4222-b1dd-a539469ae9e8', '竊覽都官李郎中和李舍人益酬張舍人弘靜夏夜寓直思聞雅琴見寄', '竊覽都官李郎中和李舍人益酬張舍人弘静夏夜寓直思闻雅琴见寄', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["朝草天子奏，夜語思憂琴。","因聲含香氣，其韻流水音。","仙樂朱鳳意，靈芝紫鸞心。","翻然遠求友，豈獨雙歸林。","松吹暑中冷，星花池上深。","倘俾有聲樂，請以絲和金。"]', '["朝草天子奏，夜語思憂琴。","因声含香氣，其韻流水音。","仙乐朱鳳意，靈芝紫鸾心。","翻然远求友，豈独雙归林。","松吹暑中冷，星花池上深。","倘俾有声乐，請以絲和金。"]', '诗', 'shi', '', NULL, '竊覽都官李郎中和李舍人益酬張舍人弘靜夏夜寓直思聞雅琴見寄 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('217ae2f8-826f-4e98-b040-b32f8b4beb89', '長安言懷', '长安言懷', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["殷殷生念厚，戚戚勞者多。","二時晝夜等，百歲詎幾何。","日下文翰苑，側身識經過。","千慮恐一失，翔陽已蹉跎。","臨觴翦衆憂，靜寄絲桐歌。","思歸繞十指，五聲不相和。","暮天還巢翼，明日隕葉柯。","高謝巖谷人，鹿衣帶女蘿。","生不去親愛，浮名若風波。","誰令不及此，親愛隔山河。"]', '["殷殷生念厚，戚戚勞者多。","二时晝夜等，百歲詎幾何。","日下文翰苑，側身識經過。","千慮恐一失，翔陽已蹉跎。","臨觴翦衆憂，静寄絲桐歌。","思归繞十指，五声不相和。","暮天還巢翼，明日隕葉柯。","高謝巖谷人，鹿衣带女蘿。","生不去親愛，浮名若风波。","誰令不及此，親愛隔山河。"]', '诗', 'shi', '', NULL, '長安言懷 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8015b5a1-8d4b-4ec0-bbe2-87e908811dcb', '秋思三首 一', '秋思三首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["胡風吹鴈翼，遠別無人鄉。","君近鴈來處，幾迴斷君腸。","昔奉千日書，撫心怨星霜。","無書又千日，世路重茫茫。","燕國有佳麗，蛾眉富春光。","自然君歸晚，花落君空堂。","君其若不然，歲晚雙鴛鴦。"]', '["胡风吹鴈翼，远別無人乡。","君近鴈来处，幾迴斷君腸。","昔奉千日书，撫心怨星霜。","無书又千日，世路重茫茫。","燕国有佳丽，蛾眉富春光。","自然君归晚，花落君空堂。","君其若不然，歲晚雙鴛鴦。"]', '诗', 'shi', '', NULL, '秋思三首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06378852-e29a-4f92-8658-072008c95de4', '秋思三首 二', '秋思三首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["顧兔蝕殘月，幽光不如星。","女兒晚事夫，顏色同秋螢。","秋日邊馬思，武夫不遑寧。","燕歌易水怨，劒舞蛟龍腥。","風折連枝樹，水翻無蔕萍。","立身多門戶，何必燕山銘。","生世不如鳥，雙雙比翼翎。"]', '["顧兔蝕殘月，幽光不如星。","女兒晚事夫，顏色同秋螢。","秋日邊马思，武夫不遑寧。","燕歌易水怨，劒舞蛟龙腥。","风折連枝樹，水翻無蔕萍。","立身多门戶，何必燕山銘。","生世不如鸟，雙雙比翼翎。"]', '诗', 'shi', '', NULL, '秋思三首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700b3179-7f9f-4ebd-8d54-d110e2ed95c7', '秋思三首 三', '秋思三首 三', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["季秋天地閑，萬物生意足。","我憂長於生，安得及草木。","試從古人願，致酒歌秉燭。","燕趙皆世人，詎能長似玉。","俯憐老期近，仰視日車速。","蕭颯御風君，魂夢願相逐。","百年夜銷半，端爲垂纓束。"]', '["季秋天地闲，万物生意足。","我憂长於生，安得及草木。","試從古人願，致酒歌秉燭。","燕趙皆世人，詎能长似玉。","俯怜老期近，仰視日车速。","蕭颯御风君，魂梦願相逐。","百年夜銷半，端爲垂纓束。"]', '诗', 'shi', '', NULL, '秋思三首 三 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('070090be-0d2a-4832-83a7-5f1be7dad755', '歸鴈', '归鴈', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["南國春早煖，渚蒲正月生。","東風吹鴈心，上下和樂聲。","繞水半空去，拂雲偕相迎。","如防失羣怨，預有侵夜驚。","渺邈天外影，支離塞中鶯。","自顧摧頹羽，偏感南北情。","乍甘煙霧勞，不顧龍沙榮。","雖樂未歸意，終不能自鳴。","喜去春月滿，歸來秋風清。","啼餘碧窗夢，望斷陰山行。","不及瑤𥯅燕，寄身金宮楹。"]', '["南国春早煖，渚蒲正月生。","东风吹鴈心，上下和乐声。","繞水半空去，拂云偕相迎。","如防失羣怨，預有侵夜驚。","渺邈天外影，支離塞中鶯。","自顧摧頹羽，偏感南北情。","乍甘煙霧勞，不顧龙沙榮。","雖乐未归意，終不能自鳴。","喜去春月满，归来秋风清。","啼餘碧窗梦，望斷陰山行。","不及瑤𥯅燕，寄身金宮楹。"]', '诗', 'shi', '', NULL, '歸鴈 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc8b077-25e6-43f8-a503-894a8802a87c', '悲湘靈', '悲湘靈', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["山上涼雲收，日斜川風止。","娥皇五十弦，秋深漢江水。","初因無象外，牽感百憂裏。","霜露結瑤華，煙波勞玉指。","將隨落葉去，又繞疎蘋起。","哀響雲合來，清餘桐半死。","女顏萬歲後，豈復嬋娟子。","不道神無悲，那能久如此。","魂魄無不之，九山徒相似。","沒沒竟不從，唯傷遠人耳。","斑斑淚篁下，恐有學瑟鬼。"]', '["山上涼云收，日斜川风止。","娥皇五十弦，秋深漢江水。","初因無象外，牽感百憂裏。","霜露結瑤华，煙波勞玉指。","將隨落葉去，又繞疎蘋起。","哀响云合来，清餘桐半死。","女顏万歲後，豈复嬋娟子。","不道神無悲，那能久如此。","魂魄無不之，九山徒相似。","沒沒竟不從，唯傷远人耳。","斑斑泪篁下，恐有学瑟鬼。"]', '诗', 'shi', '', NULL, '悲湘靈 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60756730-3848-49de-a9fb-a55b7785e89f', '聞蟬', '闻蟬', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["高蟬旦夕唳，景物浮涼氣。","木葉漸驚年，錦字因絡緯。","稍斷當窗夢，更悽臨水意。","清香筍蒂風，曉露蓮花淚。","餘引未全歇，凝悲尋迥至。","星井欲望河，月扇看藏笥。","誰念因聲感，放歌寫人事。"]', '["高蟬旦夕唳，景物浮涼氣。","木葉漸驚年，錦字因絡緯。","稍斷當窗梦，更悽臨水意。","清香筍蒂风，晓露蓮花泪。","餘引未全歇，凝悲尋迥至。","星井欲望河，月扇看藏笥。","誰念因声感，放歌寫人事。"]', '诗', 'shi', '', NULL, '聞蟬 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e1e4f6-728f-44ac-a428-2b4c528a0709', '懷幽期', '懷幽期', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["清砧擊霜天外發，楚僧期到石上月。","寒峯深虛獨遶盡，夜水淺急不可越。","窅機冥智難思量，無盡性月如空王。","眼界行處不著我，天花下來惟有香。"]', '["清砧擊霜天外發，楚僧期到石上月。","寒峯深虛独遶尽，夜水淺急不可越。","窅機冥智难思量，無尽性月如空王。","眼界行处不著我，天花下来惟有香。"]', '诗', 'shi', '', NULL, '懷幽期 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de48135c-2fb4-4922-9961-24d5d74c73f5', '思琴高', '思琴高', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["琴仙人，得仙去。","萬古釣龍空有處，我持曲鉤思白魚。","仙溪綠盡含空虛，天鈞蹤跡無遺餘。","燒香寄影在巖樹，東禮海日雞鳴初。"]', '["琴仙人，得仙去。","万古釣龙空有处，我持曲鉤思白鱼。","仙溪綠尽含空虛，天鈞蹤跡無遺餘。","燒香寄影在巖樹，东禮海日雞鳴初。"]', '诗', 'shi', '', NULL, '思琴高 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a16583ef-9846-4dea-b231-8d6d5f0ce719', '得儲道士書', '得儲道士书', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["嬋娟春盡暮心秋，鄰里同年半白頭。","爲問蓬萊近消息，海波平靜好東遊。"]', '["嬋娟春尽暮心秋，鄰里同年半白头。","爲问蓬萊近消息，海波平静好东游。"]', '诗', 'shi', '', NULL, '得儲道士書 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a45b3fa-7b2e-49ca-9688-e6453d369971', '寒夜吟', '寒夜吟', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["九衢金吾夜行行，上宮玉漏遙分明。","霜飆乘陰掃地起，旅鴻迷雪遶枕聲。","遠人歸夢既不成，留家惜夜歡心發。","羅幕畫堂深皎潔，蘭煙對酒客幾人。","獸火揚光二三月，細腰楚姬絲竹間。","白紵長袖歌閑閑，豈識苦寒損朱顏。"]', '["九衢金吾夜行行，上宮玉漏遙分明。","霜飆乘陰掃地起，旅鴻迷雪遶枕声。","远人归梦既不成，留家惜夜歡心發。","羅幕畫堂深皎潔，蘭煙对酒客幾人。","獸火揚光二三月，細腰楚姬絲竹间。","白紵长袖歌闲闲，豈識苦寒損朱顏。"]', '诗', 'shi', '', NULL, '寒夜吟 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b468e53-fb77-4fb6-a080-af4e434c56c2', '採蓮曲二首 一', '採蓮曲二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["弄舟朅來南塘水，荷葉映身摘蓮子。","暑衣清淨鴛鴦喜，作浪舞花驚不起。","殷勤護惜纖纖指，水菱初熟多新刺。"]', '["弄舟朅来南塘水，荷葉映身摘蓮子。","暑衣清淨鴛鴦喜，作浪舞花驚不起。","殷勤護惜纖纖指，水菱初熟多新刺。"]', '诗', 'shi', '', NULL, '採蓮曲二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cfa1be4-5878-491a-9184-2e763b81e0dd', '採蓮曲二首 二', '採蓮曲二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["採蓮朅來水無風，蓮潭如鑑松如龍。","夏衫短袖交斜紅，豔歌笑鬬新芙蓉。"]', '["採蓮朅来水無风，蓮潭如鑑松如龙。","夏衫短袖交斜紅，豔歌笑鬬新芙蓉。"]', '诗', 'shi', '', NULL, '採蓮曲二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fb0c4cf-8ed3-4550-a1d1-3c97933cbecc', '玉山謠奉送王隱者', '玉山謠奉送王隐者', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["鳳皇城南玉山高，石腳聳立爭雄豪。","攢峯胎玉氣色潤，百泉透雲流不盡。","萬古分明對眼開，五煙窈窕呈祥近。","有客師事金身仙，用金買得山中田。","閑開玉水灌芝草，靜醉天酒松間眠。","心期南溟萬里外，出山幾遇光陰改。","水玉丁東不可聞，冰華皎潔應如待。","秋風引吾歌去來，玉山綵翠遙相催。","殷勤千樹玉山頂，碧洞寥寥寒錦苔。"]', '["鳳皇城南玉山高，石腳聳立爭雄豪。","攢峯胎玉氣色潤，百泉透云流不尽。","万古分明对眼开，五煙窈窕呈祥近。","有客師事金身仙，用金買得山中田。","闲开玉水灌芝草，静醉天酒松间眠。","心期南溟万里外，出山幾遇光陰改。","水玉丁东不可闻，冰华皎潔應如待。","秋风引吾歌去来，玉山綵翠遙相催。","殷勤千樹玉山頂，碧洞寥寥寒錦苔。"]', '诗', 'shi', '', NULL, '玉山謠奉送王隱者 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2a44cb0-517b-4df3-8b37-93918d564fa9', '岐路', '岐路', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["北風送微寒，徒侶勤遠征。","憂人席不煖，殘月馬上明。","飄飄岐路間，長見日初生。","重嶂曉色淺，疎猨寒啼清。","人間多岐路，常恐終身行。","回見四方人，車輪無留聲。","空谷亦堪隱，下田非嬾耕。","古人有遺訓，飽食非親榮。","我生禮義鄉，少小見太平。","聖賢猶羈旅，況復非其名。"]', '["北风送微寒，徒侶勤远征。","憂人席不煖，殘月马上明。","飄飄岐路间，长见日初生。","重嶂晓色淺，疎猨寒啼清。","人间多岐路，常恐終身行。","回见四方人，车輪無留声。","空谷亦堪隐，下田非嬾耕。","古人有遺訓，飽食非親榮。","我生禮義乡，少小见太平。","聖賢猶羈旅，況复非其名。"]', '诗', 'shi', '', NULL, '岐路 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52096ef9-671a-4ef5-833e-d8a1bee9d476', '隴頭水', '隴头水', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["隴頭水，千古不堪聞。","生歸蘇屬國，死別李將軍。","細響風凋草，清哀雁落雲。"]', '["隴头水，千古不堪闻。","生归蘇屬国，死別李將軍。","細响风凋草，清哀雁落云。"]', '诗', 'shi', '', NULL, '隴頭水 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2450017-58c1-4504-bc6b-6d471c06890e', '沙上月', '沙上月', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["黃昏潮落南沙明，月光涵沙秋雪清。","水文不上煙不蕩，平平玉田冷空曠。"]', '["黄昏潮落南沙明，月光涵沙秋雪清。","水文不上煙不蕩，平平玉田冷空曠。"]', '诗', 'shi', '', NULL, '沙上月 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b286e2-832c-4d1f-a8cb-2574106041cd', '贈李黯將軍', '贈李黯將軍', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["細柳連營石壍牢，平安狼火赤星高。","巖雲入角雕龍爽，寒日搖旗畫獸豪。","搜伏雄兒欺魍魎，射聲遊騎怯分毫。","聖人唯有河[湟]恨，寰海無虞在一勞。"]', '["細柳連營石壍牢，平安狼火赤星高。","巖云入角雕龙爽，寒日搖旗畫獸豪。","搜伏雄兒欺魍魎，射声游騎怯分毫。","聖人唯有河[湟]恨，寰海無虞在一勞。"]', '诗', 'shi', '', NULL, '贈李黯將軍 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c66b7a4-bfa9-47a1-a650-0a79ba8effab', '人日陪宣州范中丞傳正與范侍御宴', '人日陪宣州范中丞傳正與范侍御宴', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["人日春風綻早梅，謝家兄弟看花來。","吳姬對客歌千曲，秦女留人酒百杯。","絲柳向空輕婉轉，玉山看日漸裴回。","流光易去歡難得，莫厭頻頻上此臺。"]', '["人日春风綻早梅，謝家兄弟看花来。","吳姬对客歌千曲，秦女留人酒百杯。","絲柳向空轻婉轉，玉山看日漸裴回。","流光易去歡难得，莫厭頻頻上此台。"]', '诗', 'shi', '', NULL, '人日陪宣州范中丞傳正與范侍御宴 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9470f560-4dd8-49f4-bd8d-43f70485a5bb', '古鑑', '古鑑', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["古鑑含靈氣象和，蛟龍盤鼻護金波。","隱山道士未曾識，負局先生不敢磨。","曾向春窗分綽約，誤迴秋水照蹉跎。","世間縱有應難比，十斛明珠酬未多。"]', '["古鑑含靈氣象和，蛟龙盤鼻護金波。","隐山道士未曾識，負局先生不敢磨。","曾向春窗分綽約，誤迴秋水照蹉跎。","世间縱有應难比，十斛明珠酬未多。"]', '诗', 'shi', '', NULL, '古鑑 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5eef8f7-e63c-4ba9-9f0b-896f85dbb2fa', '送王煉師', '送王煉師', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["聖母祠堂藥樹香，邑君承命薦椒漿。","風雲大感精神地，雷雨頻過父母鄉。","盡日一川侵草綠，迴車二麥遶山黃。","野人久會神仙事，敢奏歌鍾慶萬箱。"]', '["聖母祠堂藥樹香，邑君承命薦椒漿。","风云大感精神地，雷雨頻過父母乡。","尽日一川侵草綠，迴车二麦遶山黄。","野人久會神仙事，敢奏歌鍾慶万箱。"]', '诗', 'shi', '', NULL, '送王煉師 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de5778f4-dfe8-40b6-bfc3-1f2fe19b3e9e', '寄張十七校書李仁行秀才', '寄張十七校书李仁行秀才', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["去年八月此佳辰，池上閑閑四五人。","久行月影愁迷夢，誤入華光笑認春。","一與清風上芸閣，再期秋雨過龍津。","今年此日何由見，蓬戶蕭條對病身。"]', '["去年八月此佳辰，池上闲闲四五人。","久行月影愁迷梦，誤入华光笑認春。","一與清风上芸閣，再期秋雨過龙津。","今年此日何由见，蓬戶蕭條对病身。"]', '诗', 'shi', '', NULL, '寄張十七校書李仁行秀才 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7390b5b-8957-4923-992d-e6bdff4bba80', '送王損之秀才赴舉', '送王損之秀才赴舉', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["青門珮蘭客，淮水誓風流。","名在鄉書貢，心期月殿遊。","平沙大河急，細雨二陵秋。","感此添離恨，年光不少留。"]', '["青门珮蘭客，淮水誓风流。","名在乡书貢，心期月殿游。","平沙大河急，細雨二陵秋。","感此添離恨，年光不少留。"]', '诗', 'shi', '', NULL, '送王損之秀才赴舉 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f7d8aa-6128-4e64-bbcb-1ef58da7cdff', '舊鏡', '旧镜', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["團團銅鏡似潭水，心愛玉顏私自親。","一經離別少年改，難與清光相見新。"]', '["團團銅镜似潭水，心愛玉顏私自親。","一經離別少年改，难與清光相见新。"]', '诗', 'shi', '', NULL, '舊鏡 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3e4887-952d-462d-a05a-7541926ed3d8', '憶郊天', '憶郊天', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["憶向郊壇望武皇，九軍旗帳下南方。","六龍日馭天行健，神母呈圖地道光。","濃煖氣中生曆草，是非煙裏愛瑤漿。","至今滿耳簫韶曲，徒羨瑤池舞鳳皇。"]', '["憶向郊壇望武皇，九軍旗帳下南方。","六龙日馭天行健，神母呈圖地道光。","濃煖氣中生曆草，是非煙裏愛瑤漿。","至今满耳簫韶曲，徒羨瑤池舞鳳皇。"]', '诗', 'shi', '', NULL, '憶郊天 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d579d63-13e0-471b-a4ad-ff8d47b84bee', '期盡', '期尽', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["魚鏁生衣門不開，玉筐金月共塵埃。","青山石婦千年望，雷雨曾知來不來。"]', '["鱼鏁生衣门不开，玉筐金月共塵埃。","青山石婦千年望，雷雨曾知来不来。"]', '诗', 'shi', '', NULL, '期盡 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d6e7f76-0cb7-4bb0-8ed7-a0adff51bdd4', '晚山蟬', '晚山蟬', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["山蟬秋晚妨人語，客子驚心馬亦嘶。","能閱幾時新碧樹，不知何日寂金閨。","若逢海月明千里，莫忘何郎寄一題。"]', '["山蟬秋晚妨人語，客子驚心马亦嘶。","能閱幾时新碧樹，不知何日寂金閨。","若逢海月明千里，莫忘何郎寄一題。"]', '诗', 'shi', '', NULL, '晚山蟬 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73c7c09-7767-4fb4-8491-308c9bce92ce', '秋暮送裴垍員外刺婺州', '秋暮送裴垍員外刺婺州', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["婺女星邊氣不秋，金華山水似瀛州。","含香太守心清淨，去與神仙日日遊。"]', '["婺女星邊氣不秋，金华山水似瀛州。","含香太守心清淨，去與神仙日日游。"]', '诗', 'shi', '', NULL, '秋暮送裴垍員外刺婺州 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87760030-da65-4d3c-be27-012ac8e0ef12', '寄薛膺昆季', '寄薛膺昆季', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["楚山清洛兩無期，夢裏春風玉樹枝。","何況芙蓉樓上客，海門江月亦相思。"]', '["楚山清洛兩無期，梦裏春风玉樹枝。","何況芙蓉楼上客，海门江月亦相思。"]', '诗', 'shi', '', NULL, '寄薛膺昆季 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb16d45-d6ad-403b-897c-a2aa165d84fa', '楊真人籙中像', '楊真人籙中像', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["畫中留得清虛質，人世難逢白鶴身。","應見茅盈哀老弟，爲持金籙救生人。"]', '["畫中留得清虛質，人世难逢白鹤身。","應见茅盈哀老弟，爲持金籙救生人。"]', '诗', 'shi', '', NULL, '楊真人籙中像 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6568b2a6-3b1d-4343-b22e-3a63f6f752c8', '寄盧給事汀吳員外丹', '寄盧給事汀吳員外丹', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["姓丁黃鶴遼東去，客倩仙翁海上人。","聞道姓名多改變，只今偕是聖朝臣。"]', '["姓丁黄鹤遼东去，客倩仙翁海上人。","闻道姓名多改变，只今偕是聖朝臣。"]', '诗', 'shi', '', NULL, '寄盧給事汀吳員外丹 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11a58ce2-72db-4f34-b361-57e18d82c378', '懷王直秀才', '懷王直秀才', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["鄉無竹圃爲三徑，貧寄鄰家已二年。","惟有素風身未墜，世間開口不言錢。"]', '["乡無竹圃爲三徑，貧寄鄰家已二年。","惟有素风身未墜，世间开口不言錢。"]', '诗', 'shi', '', NULL, '懷王直秀才 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c339a14-415c-4bfa-ba26-7e849a670567', '贈真公影堂', '贈真公影堂', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["舊房西壁畫支公，昨暮今晨色不同。","遠客閑心無處所，獨添香火望虛空。"]', '["旧房西壁畫支公，昨暮今晨色不同。","远客闲心無处所，独添香火望虛空。"]', '诗', 'shi', '', NULL, '贈真公影堂 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38ea3a1e-c591-42a7-a3ee-dddfcb6505c8', '贈僧戒休', '贈僧戒休', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["風行露宿不知貧，明月爲心又是身。","欲問月中無我法，無人無我問何人。"]', '["风行露宿不知貧，明月爲心又是身。","欲问月中無我法，無人無我问何人。"]', '诗', 'shi', '', NULL, '贈僧戒休 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d60bb8-709d-42e9-a29f-edfa99e91a2d', '秋夜懷紫閣峯僧', '秋夜懷紫閣峯僧', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["滿山雨色應難見，隔澗經聲又不聞。","紫閣夜深多入定，石臺誰爲掃秋雲。"]', '["满山雨色應难见，隔澗經声又不闻。","紫閣夜深多入定，石台誰爲掃秋云。"]', '诗', 'shi', '', NULL, '秋夜懷紫閣峯僧 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a672d182-be2c-4a05-810f-b42590988adf', '酬江公見寄', '酬江公见寄', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["曾荅鴈門偈，爲憐同社人。","多慙惠休句，偕得此陽春。"]', '["曾荅鴈门偈，爲怜同社人。","多慙惠休句，偕得此陽春。"]', '诗', 'shi', '', NULL, '酬江公見寄 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdf5f232-7537-4e7d-bfa5-aee4f7671b18', '送羅侍御歸西臺', '送羅侍御归西台', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["歸臺新柱史，辭府舊英髦。","勸酒蓮幕貴，望塵驄馬高。","詩情分繡段，劒彩拂霜毫。","此舉關風化，誰云別恨勞。"]', '["归台新柱史，辞府旧英髦。","勸酒蓮幕貴，望塵驄马高。","诗情分繡段，劒彩拂霜毫。","此舉关风化，誰云別恨勞。"]', '诗', 'shi', '', NULL, '送羅侍御歸西臺 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01fc2844-e7ca-483e-9287-5f491fe2263f', '宿水亭', '宿水亭', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["雕楹綵檻壓通波，魚鱗碧幕銜曲玉。","夜深星月伴芙蓉，如在廣寒宮裏宿。"]', '["雕楹綵檻壓通波，鱼鱗碧幕銜曲玉。","夜深星月伴芙蓉，如在廣寒宮裏宿。"]', '诗', 'shi', '', NULL, '宿水亭 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d10f3d-adfa-4e32-b318-8c94e63f877c', '寄峨嵋山楊煉師', '寄峨嵋山楊煉師', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["道士夜誦蘂珠經，白鶴下遶香煙聽。","夜移經盡人上鶴，仙風吹入秋冥冥。"]', '["道士夜誦蘂珠經，白鹤下遶香煙听。","夜移經尽人上鹤，仙风吹入秋冥冥。"]', '诗', 'shi', '', NULL, '寄峨嵋山楊煉師 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa282553-4e94-4f98-9239-acffb8eb0a51', '寄海陵韓長官', '寄海陵韓长官', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["吏散重門印不開，玉琴招鶴舞裴回。","野人爲此多東望，雲雨仍從海上來。"]', '["吏散重门印不开，玉琴招鹤舞裴回。","野人爲此多东望，云雨仍從海上来。"]', '诗', 'shi', '', NULL, '寄海陵韓長官 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c11d93a-ffc0-4a5b-8998-a57cbb122cc1', '淮南臥病感路羣侍御訪別', '淮南臥病感路羣侍御訪別', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["西臺御史重難言，落木疎籬遶病魂。","一望青雲感驄馬，欵行黃草出柴門。"]', '["西台御史重难言，落木疎籬遶病魂。","一望青云感驄马，欵行黄草出柴门。"]', '诗', 'shi', '', NULL, '淮南臥病感路羣侍御訪別 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce50fc2-2b72-4f27-9caa-6c4ef13b9856', '題禪定寺集公竹院', '題禪定寺集公竹院', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["公門得休靜，禪寺少逢迎。","任客看花醉，隨僧入竹行。","歸時常犯夜，雲裏有經聲。"]', '["公门得休静，禪寺少逢迎。","任客看花醉，隨僧入竹行。","归时常犯夜，云裏有經声。"]', '诗', 'shi', '', NULL, '題禪定寺集公竹院 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a56ae0a-0370-4797-9ec3-e5d61af5780d', '風箏', '风箏', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["何響與天通，瑤箏挂望中。","彩弦非觸指，錦瑟忽聞風。","鴈柱虛連勢，鸞歌且墜空。","夜和霜擊磬，晴引鳳歸桐。","幽咽誰生怨，清泠自匪躬。","秦姬收寶匣，搔首不成功。"]', '["何响與天通，瑤箏挂望中。","彩弦非觸指，錦瑟忽闻风。","鴈柱虛連勢，鸾歌且墜空。","夜和霜擊磬，晴引鳳归桐。","幽咽誰生怨，清泠自匪躬。","秦姬收寶匣，搔首不成功。"]', '诗', 'shi', '', NULL, '風箏 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b03d28d8-db35-4ba8-b14e-aeeb4ee040a2', '經舊遊', '經旧游', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["遊魚懷故池，倦鳥懷故窠。","故山繫歸念，行坐青巍峨。","羸馬經舊途，此鄉喜重過。","居人無故老，倍感別日多。","但見野中墳，纍纍如青螺。","涼風日搖落，桑下松婆娑。","歎息追古人，臨風傷逝波。","古人無不死，歎息欲如何。","朅來遂遠心，默默存天和。"]', '["游鱼懷故池，倦鸟懷故窠。","故山繫归念，行坐青巍峨。","羸马經旧途，此乡喜重過。","居人無故老，倍感別日多。","但见野中墳，纍纍如青螺。","涼风日搖落，桑下松婆娑。","歎息追古人，臨风傷逝波。","古人無不死，歎息欲如何。","朅来遂远心，默默存天和。"]', '诗', 'shi', '', NULL, '經舊遊 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c3a522-891d-47f2-934a-1396a3a99bdc', '過薛舍人舊隱', '過薛舍人旧隐', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["寢門來哭夜，此月小祥初。","風意猶憶瑟，螢光乍近書。","牆蒿藏宿鳥，池月上鉤魚。","徒引相思淚，涓涓東逝餘。"]', '["寢门来哭夜，此月小祥初。","风意猶憶瑟，螢光乍近书。","牆蒿藏宿鸟，池月上鉤鱼。","徒引相思泪，涓涓东逝餘。"]', '诗', 'shi', '', NULL, '過薛舍人舊隱 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddff19c3-95ce-4590-a612-ddf958a308f6', '山居', '山居', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["窈窕垂澗蘿，蒙茸黃葛花。","鴛鴦憐碧水，照影舞金沙。"]', '["窈窕垂澗蘿，蒙茸黄葛花。","鴛鴦怜碧水，照影舞金沙。"]', '诗', 'shi', '', NULL, '山居 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3db0baa7-cb74-422c-b606-17dadb3a97f4', '暮秋與裴居晦宴因見採菊花之作', '暮秋與裴居晦宴因见採菊花之作', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["菊花低色過重陽，似憶王孫白玉觴。","今日王孫好收採，高天已下兩迴霜。"]', '["菊花低色過重陽，似憶王孫白玉觴。","今日王孫好收採，高天已下兩迴霜。"]', '诗', 'shi', '', NULL, '暮秋與裴居晦宴因見採菊花之作 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0959e8e-9389-41a7-96a3-70158ff4cc6e', '望麻姑山', '望麻姑山', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["幽人往往懷麻姑，浮世悠悠仙景殊。","自從青鳥不堪使，更得蓬萊消息無。"]', '["幽人往往懷麻姑，浮世悠悠仙景殊。","自從青鸟不堪使，更得蓬萊消息無。"]', '诗', 'shi', '', NULL, '望麻姑山 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3ddf00-bc47-419d-852a-9197051301d1', '湖上望月', '湖上望月', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["湖上清涼月更好，天邊旅人猶未歸。","幾見金波滿還破，草蟲聲畔露沾衣。"]', '["湖上清涼月更好，天邊旅人猶未归。","幾见金波满還破，草蟲声畔露沾衣。"]', '诗', 'shi', '', NULL, '湖上望月 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5de197e-533a-4ed5-b7f4-0db235c342d0', '襄陽懷古', '襄陽懷古', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["襄陽太守沈碑意，身後身前幾年事。","湘江千歲未爲陵，水底魚龍應識字。"]', '["襄陽太守沈碑意，身後身前幾年事。","湘江千歲未爲陵，水底鱼龙應識字。"]', '诗', 'shi', '', NULL, '襄陽懷古 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e9e17c-6b88-4b50-b361-df97be55d8f1', '秋夜對月寄僧特', '秋夜对月寄僧特', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["憶見特公賞秋處，涼溪看月清光寒。","今夕深溪又相映，特公何處共團圓。"]', '["憶见特公賞秋处，涼溪看月清光寒。","今夕深溪又相映，特公何处共團圓。"]', '诗', 'shi', '', NULL, '秋夜對月寄僧特 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c3bb20-1355-4c17-92d2-dc055ef661ec', '望江中金山寺', '望江中金山寺', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["一朵蓬萊在世間，梵王宮闕翠雲間。","近南溪水更清淺，聞道遊人未忍還。"]', '["一朵蓬萊在世间，梵王宮闕翠云间。","近南溪水更清淺，闻道游人未忍還。"]', '诗', 'shi', '', NULL, '望江中金山寺 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('069d738d-6c35-4099-95ac-4b8972162df3', '宿青牛谷梁煉師仙居', '宿青牛谷梁煉師仙居', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["隨雲步入青牛谷，青牛道士留我宿。","可憐夜久月中行，惟有壇邊一枝竹。"]', '["隨云步入青牛谷，青牛道士留我宿。","可怜夜久月中行，惟有壇邊一枝竹。"]', '诗', 'shi', '', NULL, '宿青牛谷梁煉師仙居 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0027eff-5bad-47eb-92da-3fd15f486e9f', '得僧書', '得僧书', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["身歸紫霄嶺，書下白雲來。","翦筍發寒字，燒花芳夜雷。","想隨香馭至，不假定鐘催。"]', '["身归紫霄嶺，书下白云来。","翦筍發寒字，燒花芳夜雷。","想隨香馭至，不假定鐘催。"]', '诗', 'shi', '', NULL, '得僧書 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('420bc1a0-deb2-4441-9db7-bb0f3630b3b3', '見袁德師侍御說江南有仙檀花因以戲贈', '见袁德師侍御说江南有仙檀花因以戲贈', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["聞說天壇花耐涼，笑風含露對秋光。","欲求御史更分別，何似衣花歲歲香。"]', '["闻说天壇花耐涼，笑风含露对秋光。","欲求御史更分別，何似衣花歲歲香。"]', '诗', 'shi', '', NULL, '見袁德師侍御說江南有仙檀花因以戲贈 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ef4016a-16d9-469b-b64d-f0894b84ad17', '和王璠侍御酬友人贈白角冠', '和王璠侍御酬友人贈白角冠', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["芙蓉寒豔鏤冰姿，天朗燈深拔豸時。","好見吹笙伊洛上，紫煙丹鳳亦相隨。"]', '["芙蓉寒豔鏤冰姿，天朗灯深拔豸时。","好见吹笙伊洛上，紫煙丹鳳亦相隨。"]', '诗', 'shi', '', NULL, '和王璠侍御酬友人贈白角冠 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e9db4c7-df87-4d13-8f53-8a0b47942ac3', '送僧擇棲遊天台二首 一', '送僧擇棲游天台二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["身非居士常多病，心愛空王稍覺閑。","師問寄禪何處所，浙東青翠沃洲山。"]', '["身非居士常多病，心愛空王稍覺闲。","師问寄禪何处所，浙东青翠沃洲山。"]', '诗', 'shi', '', NULL, '送僧擇棲遊天台二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f67239-7f09-4ea1-bc1f-8cf0ea8fa05e', '送僧擇棲遊天台二首 二', '送僧擇棲游天台二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["金嶺雪晴僧獨歸，水文霞彩衲禪衣。","可憐石室燒香夜，江月對心無是非。"]', '["金嶺雪晴僧独归，水文霞彩衲禪衣。","可怜石室燒香夜，江月对心無是非。"]', '诗', 'shi', '', NULL, '送僧擇棲遊天台二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd0ade3-99a2-4442-8d41-79098d86f8c3', '上巳日寄樊瓘樊宗憲兼呈上浙東孟中丞簡', '上巳日寄樊瓘樊宗憲兼呈上浙东孟中丞簡', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["世間禊事風流處，鏡裏雲山若畫屏。","今日會稽王內史，好將賓客醉蘭亭。"]', '["世间禊事风流处，镜裏云山若畫屏。","今日會稽王內史，好將賓客醉蘭亭。"]', '诗', 'shi', '', NULL, '上巳日寄樊瓘樊宗憲兼呈上浙東孟中丞簡 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa237e0-c9d2-459e-9633-290fdff9cacb', '暮春戲贈樊宗憲', '暮春戲贈樊宗憲', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["羌笛胡琴春調長，美人何處樂年芳。","野船弄酒鴛鴦醉，官路攀花騕褭狂。","應和朝雲垂手語，肯嫌夜色斷刀光。"]', '["羌笛胡琴春調长，美人何处乐年芳。","野船弄酒鴛鴦醉，官路攀花騕褭狂。","應和朝云垂手語，肯嫌夜色斷刀光。"]', '诗', 'shi', '', NULL, '暮春戲贈樊宗憲 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30e5ef0b-ed7f-4250-88f2-84f6b7103952', '酬王侍御', '酬王侍御', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["慙非青玉製，故以贈仙郎。","希翼留書閤，提攜在筆牀。","詎能輝繡服，安得似芸香。","所報何珍重，清明勝夜光。"]', '["慙非青玉製，故以贈仙郎。","希翼留书閤，提携在笔牀。","詎能輝繡服，安得似芸香。","所報何珍重，清明勝夜光。"]', '诗', 'shi', '', NULL, '酬王侍御 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72da81b5-8de5-4b5f-bc46-820925a90d64', '寄宋申錫評事時從李少師移軍回歸', '寄宋申錫評事时從李少師移軍回归', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["君逐元侯靜虜歸，虎旗龍節駐春暉。","欲求岱岳燔柴禮，已錫魯人縫掖衣。","長劒一時天外倚，五雲多遶日邊飛。","心期共賀太平世，去去故鄉親食薇。"]', '["君逐元侯静虜归，虎旗龙節駐春暉。","欲求岱岳燔柴禮，已錫魯人縫掖衣。","长劒一时天外倚，五云多遶日邊飞。","心期共賀太平世，去去故乡親食薇。"]', '诗', 'shi', '', NULL, '寄宋申錫評事時從李少師移軍回歸 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cab1cb0-0c9e-414a-b890-849a045932a7', '夏日懷杜悰駙馬', '夏日懷杜悰駙马', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["五月清涼蕭史家，瑤池分水種菱花。","迴文地簟龍鱗浪，交鏁天窗蟬翼紗。","閑遣青琴飛小雪，自看碧玉破甘瓜。","仍聞聖主知書癖，鳳閣燒香對五車。"]', '["五月清涼蕭史家，瑤池分水種菱花。","迴文地簟龙鱗浪，交鏁天窗蟬翼紗。","闲遣青琴飞小雪，自看碧玉破甘瓜。","仍闻聖主知书癖，鳳閣燒香对五车。"]', '诗', 'shi', '', NULL, '夏日懷杜悰駙馬 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2469da2-1e59-4b57-a94e-0e38823783a4', '鶯雛', '鶯雛', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["雙鶯銜野蝶，枝上教雛飛。","避日花陰語，愁風竹裏啼。","須防美人賞，爲爾好毛衣。"]', '["雙鶯銜野蝶，枝上教雛飞。","避日花陰語，愁风竹裏啼。","須防美人賞，爲爾好毛衣。"]', '诗', 'shi', '', NULL, '鶯雛 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ee3248-bc97-4ab9-a1fe-96d1145a10e6', '上陽宮月', '上陽宮月', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["水北宮城夜柝嚴，宮西新月影纖纖。","受環花幌小開鏡，移燭瑤房皆捲簾。","學織機邊娥影靜，拜新衣上露華沾。","合裁班扇思行幸，願託涼風篋笥嫌。"]', '["水北宮城夜柝嚴，宮西新月影纖纖。","受环花幌小开镜，移燭瑤房皆捲簾。","学织機邊娥影静，拜新衣上露华沾。","合裁班扇思行幸，願託涼风篋笥嫌。"]', '诗', 'shi', '', NULL, '上陽宮月 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15411047-e7fb-44f1-bf52-a0d04f1b31be', '淮南臥病聞李相夷簡移軍山陽以靖東寇感激之下因抒長句', '淮南臥病闻李相夷簡移軍山陽以靖东寇感激之下因抒长句', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["太白星前龍虎符，元臣出將順天誅。","教聞清淨蕭丞相，計立安危范大夫。","玉帳黃昏大刁斗，月營寒曉小單于。","魯連未必蹈滄海，應見麒麟新畫圖。"]', '["太白星前龙虎符，元臣出將順天誅。","教闻清淨蕭丞相，計立安危范大夫。","玉帳黄昏大刁斗，月營寒晓小單于。","魯連未必蹈滄海，應见麒麟新畫圖。"]', '诗', 'shi', '', NULL, '淮南臥病聞李相夷簡移軍山陽以靖東寇感激之下因抒長句 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad65dbf7-ab89-4de7-afa4-dce073a5ce8f', '讀淮南李相行營至楚州詩', '读淮南李相行營至楚州诗', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["閫外建牙威不賓，古來戡難憶忠臣。","已分舟楫歸元老，更使熊羆屬丈人。","玄象合教滄海晏，青龍喜應太山春。","來年二月登封禮，去望台星扈日輪。"]', '["閫外建牙威不賓，古来戡难憶忠臣。","已分舟楫归元老，更使熊羆屬丈人。","玄象合教滄海晏，青龙喜應太山春。","来年二月登封禮，去望台星扈日輪。"]', '诗', 'shi', '', NULL, '讀淮南李相行營至楚州詩 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a7b3d37-b52e-4a13-b5d7-05f4237ce79e', '讀李相心中樂', '读李相心中乐', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["負海狂鯨縱巨鱗，四朝天子阻時巡。","誰將侯玉乖南面，幾使戎軍殷左輪。","久作妖星虛費日，終□天洞亦何人。","果聞丞相心中樂，上贊陶唐一萬春。"]', '["負海狂鯨縱巨鱗，四朝天子阻时巡。","誰將侯玉乖南面，幾使戎軍殷左輪。","久作妖星虛費日，終□天洞亦何人。","果闻丞相心中乐，上贊陶唐一万春。"]', '诗', 'shi', '', NULL, '讀李相心中樂 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55d67245-4ceb-49d0-be30-a0c64000d208', '聞國家將行封禪聊抒臣情', '闻国家將行封禪聊抒臣情', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["雲雨由來隨六龍，玉泥瑤檢不乾封。","山知槱柞新煙火，臣望簫韶舊鼓鐘。","清蹕間過素王廟，翠華高映大夫松。","旅中病客諳堯曲，身賤何由奏九重。"]', '["云雨由来隨六龙，玉泥瑤檢不乾封。","山知槱柞新煙火，臣望簫韶旧鼓鐘。","清蹕间過素王廟，翠华高映大夫松。","旅中病客諳堯曲，身賤何由奏九重。"]', '诗', 'shi', '', NULL, '聞國家將行封禪聊抒臣情 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0b0d0f-6635-4947-9d9d-32414660c861', '和淮南李相公夷簡喜平淄青迴軍之作', '和淮南李相公夷簡喜平淄青迴軍之作', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["橫笛臨吹發曉軍，元戎幢節拂寒雲。","搜山羽騎乘風引，下瀨樓船背水分。","天際獸旗搖火燄，日前魚甲動金文。","馬毛不汗東方靖，行見蕭何第一勳。"]', '["橫笛臨吹發晓軍，元戎幢節拂寒云。","搜山羽騎乘风引，下瀨楼船背水分。","天際獸旗搖火燄，日前鱼甲动金文。","马毛不汗东方靖，行见蕭何第一勳。"]', '诗', 'shi', '', NULL, '和淮南李相公夷簡喜平淄青迴軍之作 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59abfb44-de57-473b-9d2e-f61c85a79984', '秋暮八月十五夜與王璠侍御賞月因愴遠離聊以奉寄', '秋暮八月十五夜與王璠侍御賞月因愴远離聊以奉寄', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["前月月明夜，美人同遠光。","清塵一以間，今夕坐相忘。","風落芙蓉露，凝餘繡服香。"]', '["前月月明夜，美人同远光。","清塵一以间，今夕坐相忘。","风落芙蓉露，凝餘繡服香。"]', '诗', 'shi', '', NULL, '秋暮八月十五夜與王璠侍御賞月因愴遠離聊以奉寄 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a45f38a-4f30-4e8a-b6a2-ec8ef813a10f', '送蕭世秀才', '送蕭世秀才', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["心交別我西京去，愁滿春魂不易醒。","從此無人訪窮病，馬蹄車轍草青青。"]', '["心交別我西京去，愁满春魂不易醒。","從此無人訪窮病，马蹄车轍草青青。"]', '诗', 'shi', '', NULL, '送蕭世秀才 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89729cf7-40bf-41e5-a452-cf2c2b09dbd6', '懷惠明禪師', '懷惠明禪師', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["秋天欲霜夜無風，我意不在天地中。","雪山世界此涼夜，寶月獨照琉璃宮。","解空長老蓮花手，曾以佛書親指授。","雪嶺無人又問來，十年夏臘平安否。"]', '["秋天欲霜夜無风，我意不在天地中。","雪山世界此涼夜，寶月独照琉璃宮。","解空长老蓮花手，曾以佛书親指授。","雪嶺無人又问来，十年夏臘平安否。"]', '诗', 'shi', '', NULL, '懷惠明禪師 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec543382-f300-4b5a-9332-9262cf0e7d63', '吳中夜別', '吳中夜別', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["楚客秋思著黃葉，吳姬夜歌停碧雲。","聲盡燈前各流淚，水天涼冷鴈離羣。"]', '["楚客秋思著黄葉，吳姬夜歌停碧云。","声尽灯前各流泪，水天涼冷鴈離羣。"]', '诗', 'shi', '', NULL, '吳中夜別 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf6b1b1-a0a8-4242-8d2c-03f1115e911b', '隋家井', '隋家井', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["玉鉤欄下寒泉水，金轆轤邊影照人。","此水今爲九泉路，數枝花照數堆塵。"]', '["玉鉤欄下寒泉水，金轆轤邊影照人。","此水今爲九泉路，數枝花照數堆塵。"]', '诗', 'shi', '', NULL, '隋家井 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cea8716-cedd-4e7b-b782-bf69ccdc81e3', '寄王璠侍御求蜀箋', '寄王璠侍御求蜀箋', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["蜀川牋紙綵雲初，聞說王家最有餘。","野客思將池上學，石楠紅葉不堪書。"]', '["蜀川牋紙綵云初，闻说王家最有餘。","野客思將池上学，石楠紅葉不堪书。"]', '诗', 'shi', '', NULL, '寄王璠侍御求蜀箋 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de00136-585e-4ae2-acd9-913ff6f83610', '湘妃列女操', '湘妃列女操', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["有虞夫人哭虞后，淑女何事又傷離，竹上淚跡生不盡。","寄哀雲和五十絲，雲和終奏鈞天曲。","乍聽寶琴遙嗣續，三湘測測流急綠。","秋夜露寒蜀帝飛，楓林月斜楚臣宿。","更疑川宮日黃昏，闇攜女手殷勤言。","環珮玲瓏有無間，終疑既遠雙悄悄。","蒼梧舊雲豈難召，老猨心寒不可嘯。","目眄眄兮意蹉跎，魂騰騰兮驚秋波。","曲一盡兮憶再奏，衆弦不聲且如何。"]', '["有虞夫人哭虞后，淑女何事又傷離，竹上泪跡生不尽。","寄哀云和五十絲，云和終奏鈞天曲。","乍听寶琴遙嗣續，三湘測測流急綠。","秋夜露寒蜀帝飞，楓林月斜楚臣宿。","更疑川宮日黄昏，闇携女手殷勤言。","环珮玲瓏有無间，終疑既远雙悄悄。","蒼梧旧云豈难召，老猨心寒不可嘯。","目眄眄兮意蹉跎，魂腾腾兮驚秋波。","曲一尽兮憶再奏，衆弦不声且如何。"]', '诗', 'shi', '', NULL, '湘妃列女操 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e282923c-87ed-4db0-82a7-75675531fec0', '羽林行', '羽林行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["朝出羽林宮，入參雲臺議。","獨請萬里行，不奏和親事。","君王重年少，深納開邊利。","寶馬雕玉鞍，一朝從萬騎。","煌煌都門外，祖帳光七貴。","歌鍾樂行軍，雲物慘別地。","簫笳整部曲，幢蓋動郊次。","臨風親戚懷，滿袖兒女淚。","行行復何贈，長劒報恩字。"]', '["朝出羽林宮，入參云台議。","独請万里行，不奏和親事。","君王重年少，深納开邊利。","寶马雕玉鞍，一朝從万騎。","煌煌都门外，祖帳光七貴。","歌鍾乐行軍，云物慘別地。","簫笳整部曲，幢蓋动郊次。","臨风親戚懷，满袖兒女泪。","行行复何贈，长劒報恩字。"]', '诗', 'shi', '', NULL, '羽林行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04243e6-fedd-4dbe-8d52-01794bfcbf97', '鳴鴈行', '鳴鴈行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["七月朔方鴈心苦，聯影翻空落南土。","八月江南陰復晴，浮雲繞天難夜行。","羽翼勞痛心虛驚，一聲相呼百處鳴。","楚童夜宿煙波側，沙上布羅連草色。","月闇風悲欲下天，不知何處容棲息？","楚童胡爲傷我神，爾不曾作遠行人。","江南羽族本不少，寧得網羅此客鳥。"]', '["七月朔方鴈心苦，聯影翻空落南土。","八月江南陰复晴，浮云繞天难夜行。","羽翼勞痛心虛驚，一声相呼百处鳴。","楚童夜宿煙波側，沙上布羅連草色。","月闇风悲欲下天，不知何处容棲息？","楚童胡爲傷我神，爾不曾作远行人。","江南羽族本不少，寧得網羅此客鸟。"]', '诗', 'shi', '', NULL, '鳴鴈行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7caf1299-3cb3-4c66-8bea-9bdefc869030', '織婦詞', '织婦词', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["百日織綵絲，一朝停杼機。","機中有雙鳳，化作天邊衣。","使人馬如風，誠不阻音徽。","影響隨羽翼，雙雙繞君飛。","行人豈願行，不怨不知歸。","所怨天盡處，何人見光輝。"]', '["百日织綵絲，一朝停杼機。","機中有雙鳳，化作天邊衣。","使人马如风，誠不阻音徽。","影响隨羽翼，雙雙繞君飞。","行人豈願行，不怨不知归。","所怨天尽处，何人见光輝。"]', '诗', 'shi', '', NULL, '織婦詞 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f95bdf64-5896-4551-b323-33039eeef5df', '塞上行', '塞上行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["西風應時筋角堅，承露牧馬水草冷。","可憐黃河九曲盡，氈館牢落胡無影。"]', '["西风應时筋角堅，承露牧马水草冷。","可怜黄河九曲尽，氈館牢落胡無影。"]', '诗', 'shi', '', NULL, '塞上行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e529d70-a02f-4879-9b17-94a3b0b827da', '採珠行', '採珠行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["東方暮空海面平，驪龍弄珠燒月明。","海人驚窺水底火，百寶錯落隨龍行。","浮心一夜生姦見，月質龍軀看幾遍。","擘波下去忘此身，迢迢謂海無靈神。","海宮正當龍睡重，昨夜孤光今得弄。","河伯空憂水府貧，天吳不敢相驚動。","一團冰容掌上清，四面人入光中行。","騰華乍搖白日影，銅鏡萬古羞爲靈。","海邊老翁怨狂子，抱珠哭向無底水。","一富何須龍頷前，千金幾葬魚腹裏。","鱗蟲變化爲陰陽，填海破山無景光。","拊心髣髴失珠意，此土爲爾離農桑。","飲風衣日亦飽煖，老翁擲却荆雞卵。"]', '["东方暮空海面平，驪龙弄珠燒月明。","海人驚窺水底火，百寶錯落隨龙行。","浮心一夜生姦见，月質龙軀看幾遍。","擘波下去忘此身，迢迢謂海無靈神。","海宮正當龙睡重，昨夜孤光今得弄。","河伯空憂水府貧，天吳不敢相驚动。","一團冰容掌上清，四面人入光中行。","腾华乍搖白日影，銅镜万古羞爲靈。","海邊老翁怨狂子，抱珠哭向無底水。","一富何須龙頷前，千金幾葬鱼腹裏。","鱗蟲变化爲陰陽，填海破山無景光。","拊心髣髴失珠意，此土爲爾離農桑。","饮风衣日亦飽煖，老翁擲却荆雞卵。"]', '诗', 'shi', '', NULL, '採珠行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba0ea996-a761-4dcc-9d40-a3fea9e9b2c9', '采葛行', '采葛行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["春溪幾回葛花黃，黃麝引子山山香。","蠻女不惜手足損，鉤刀一一牽柔長。","葛絲茸茸春雪體，深澗擇泉清處洗。","殷勤十指蠶吐絲，當窗嫋嫋聲高機。","織成一尺無一兩，供進天子五月衣。","水精夏殿開涼戶，冰山繞座猶難御。","衣親玉體又何如，杳然獨對秋風曙。","鏡湖女兒嫁鮫人，鮫綃逼肖也不分。","吳中角簟泛清水，搖曳勝被三素雲。","自茲貢薦無人惜，那敢更爭龍手跡。","蠻女將來海市頭，賣與嶺南貧估客。"]', '["春溪幾回葛花黄，黄麝引子山山香。","蠻女不惜手足損，鉤刀一一牽柔长。","葛絲茸茸春雪體，深澗擇泉清处洗。","殷勤十指蠶吐絲，當窗嫋嫋声高機。","织成一尺無一兩，供進天子五月衣。","水精夏殿开涼戶，冰山繞座猶难御。","衣親玉體又何如，杳然独对秋风曙。","镜湖女兒嫁鮫人，鮫綃逼肖也不分。","吳中角簟泛清水，搖曳勝被三素云。","自茲貢薦無人惜，那敢更爭龙手跡。","蠻女將来海市头，賣與嶺南貧估客。"]', '诗', 'shi', '', NULL, '采葛行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f17410d-4423-4455-8c91-1cc8a33a3c35', '南塘二首 一', '南塘二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["南塘旅舍秋淺清，夜深綠蘋風不生。","蓮花受露重如睡，斜月起動鴛鴦聲。"]', '["南塘旅舍秋淺清，夜深綠蘋风不生。","蓮花受露重如睡，斜月起动鴛鴦声。"]', '诗', 'shi', '', NULL, '南塘二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a349dddb-7734-4ba3-a1c9-4bc836bb2ca3', '南塘二首 二', '南塘二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["塘東白日駐紅霧，早魚翻光落碧潯。","畫舟蘭棹欲破浪，恐畏驚動蓮花心。"]', '["塘东白日駐紅霧，早鱼翻光落碧潯。","畫舟蘭棹欲破浪，恐畏驚动蓮花心。"]', '诗', 'shi', '', NULL, '南塘二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f07029-4e68-4be0-a478-77eba63c82c1', '東鄰女', '东鄰女', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["雙飛鷓鴣春影斜，美人盤金衣上花。","身爲父母幾時客，一生知向何人家。"]', '["雙飞鷓鴣春影斜，美人盤金衣上花。","身爲父母幾时客，一生知向何人家。"]', '诗', 'shi', '', NULL, '東鄰女 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a3554c-2d7e-4fc6-b736-90e3af47c4a6', '寄李都護', '寄李都護', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["去年河上送行人，萬里弓旌一武臣。","聞道玉關烽火滅，犬戎知有外家親。"]', '["去年河上送行人，万里弓旌一武臣。","闻道玉关烽火滅，犬戎知有外家親。"]', '诗', 'shi', '', NULL, '寄李都護 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6be383-e054-4811-a564-a310bffa3923', '長安旅舍懷舊山', '长安旅舍懷旧山', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["昨夜清涼夢本山，眠雲喚鶴有慙顏。","青蓮道士長堪羨，身外無名至老閑。"]', '["昨夜清涼梦本山，眠云喚鹤有慙顏。","青蓮道士长堪羨，身外無名至老闲。"]', '诗', 'shi', '', NULL, '長安旅舍懷舊山 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b5ab29-a93d-416e-a28b-05b862e86c49', '漢宮詞二首 一', '漢宮词二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["栢梁宸居清窈窕，東方先生夜待詔。","夜久月當承露盤，內人吹笙舞鳳鸞。"]', '["栢梁宸居清窈窕，东方先生夜待詔。","夜久月當承露盤，內人吹笙舞鳳鸾。"]', '诗', 'shi', '', NULL, '漢宮詞二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed236e32-c4ce-466b-8003-00c6dc1381be', '漢宮詞二首 二', '漢宮词二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["月映東窗似玉輪，未央前殿絕聲塵。","宮槐花落西風起，鸚鵡驚寒夜喚人。"]', '["月映东窗似玉輪，未央前殿絕声塵。","宮槐花落西风起，鸚鵡驚寒夜喚人。"]', '诗', 'shi', '', NULL, '漢宮詞二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86441272-ac1c-41be-9a97-eb4716e67041', '薦冰', '薦冰', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["西陵宜先啓，春寒寢廟清。","曆官分氣候，天子薦精誠。","已辨瑤池色，如和玉珮鳴。","禮餘神轉肅，曙後月殘明。","雅合霜容潔，非同雪體輕。","空憐一掬水，珍重此時情。"]', '["西陵宜先啓，春寒寢廟清。","曆官分氣候，天子薦精誠。","已辨瑤池色，如和玉珮鳴。","禮餘神轉肅，曙後月殘明。","雅合霜容潔，非同雪體轻。","空怜一掬水，珍重此时情。"]', '诗', 'shi', '', NULL, '薦冰 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdae75ba-bdbf-43eb-a613-6567a002ebbc', '送薛補闕入朝', '送薛補闕入朝', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["平原門下十餘人，獨受恩多未殺身。","每歎陸家兄弟少，更憐楊氏子孫貧。","柴門已斷施行馬，魯酒那能醉近臣。","賴有軍中遺令在，猶將談笑對風塵。"]', '["平原门下十餘人，独受恩多未殺身。","每歎陸家兄弟少，更怜楊氏子孫貧。","柴门已斷施行马，魯酒那能醉近臣。","賴有軍中遺令在，猶將談笑对风塵。"]', '诗', 'shi', '', NULL, '送薛補闕入朝 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe82fb41-b086-416f-b761-b5415757f083', '句', '句', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["萬里岐路多，一身天地窄。"]', '["万里岐路多，一身天地窄。"]', '诗', 'shi', '', NULL, '句 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216f56cd-d4b2-4dee-8cf4-543dd3d897d0', '薦冰', '薦冰', 'ca44c773-a5bc-4d6d-9b93-7d6263479a3e', '唐', '["薦冰朝日後，闢廟曉光清。","不改晶熒質，能彰語露情。","且無霜共潔，豈與水均明。","在捧搖寒色，當呈表素誠。","凝姿陳俎豆，浮彩映牕楹。","皎皎盤盂側，稜稜嚴氣生。"]', '["薦冰朝日後，闢廟晓光清。","不改晶熒質，能彰語露情。","且無霜共潔，豈與水均明。","在捧搖寒色，當呈表素誠。","凝姿陳俎豆，浮彩映牕楹。","皎皎盤盂側，稜稜嚴氣生。"]', '诗', 'shi', '', NULL, '薦冰 盧鈞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a6e1aa-30ef-4d4f-a1bb-489b8f06c522', '薦冰', '薦冰', '555cfe2f-b29f-4bf7-8dfc-5d5a2934573d', '唐', '["乘春方啓閉，羞獻有常程。","潔朗寒光徹，輝華素彩明。","色凝霜雪淨，影照冕旒清。","肅肅將崇禮，兢兢示捧盈。","方圓陳玉座，小大表精誠。","朝覿當西陸，桃弧每共行。"]', '["乘春方啓閉，羞獻有常程。","潔朗寒光徹，輝华素彩明。","色凝霜雪淨，影照冕旒清。","肅肅將崇禮，兢兢示捧盈。","方圓陳玉座，小大表精誠。","朝覿當西陸，桃弧每共行。"]', '诗', 'shi', '', NULL, '薦冰 范傳質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d41ad1a-63a4-4546-887e-afb658f1a4d9', '賦得芙蓉出水', '賦得芙蓉出水', '03be75ae-1a53-4899-aa55-adb05364bbcd', '唐', '["的皪舒芳豔，紅姿映綠蘋。","搖風開細浪，出沼媚清晨。","翻影初迎日，流香暗襲人。","獨披千葉淺，不競百花春。","魚戲參差動，龜游次第新。","涉江如可採，從此免迷津。"]', '["的皪舒芳豔，紅姿映綠蘋。","搖风开細浪，出沼媚清晨。","翻影初迎日，流香暗襲人。","独披千葉淺，不競百花春。","鱼戲參差动，龟游次第新。","涉江如可採，從此免迷津。"]', '诗', 'shi', '', NULL, '賦得芙蓉出水 賈謩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00517cde-eab7-4033-9959-0d91f76637a2', '恩賜魏文貞公諸孫舊第以𨗳直臣', '恩賜魏文貞公諸孫旧第以𨗳直臣', '25c222cf-22c5-40ec-b00d-52190959c5d5', '唐', '["阿衡隨逝水，池館主他人。","天意能酬德，雲孫喜庇身。","生前由直道，歿後振芳塵。","雨露新恩日，芝蘭舊里春。","勳庸留十代，光彩映諸鄰。","共賀升平日，從茲得諫臣。"]', '["阿衡隨逝水，池館主他人。","天意能酬德，云孫喜庇身。","生前由直道，歿後振芳塵。","雨露新恩日，芝蘭旧里春。","勳庸留十代，光彩映諸鄰。","共賀升平日，從茲得諫臣。"]', '诗', 'shi', '', NULL, '恩賜魏文貞公諸孫舊第以𨗳直臣 陳彥博 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e782eb7-1220-4330-b41e-023d360f8169', '使南海道長沙題道林岳麓寺', '使南海道长沙題道林岳麓寺', '577e373e-baf6-4547-9e0c-146b688138ab', '唐', '["道林岳麓仲與昆，卓犖請從先後論。","松根踏雲二千步，始見大屋開三門。","泉清或戲蛟龍窟，殿豁數盡高帆掀。","即今異鳥聲不斷，聞道看花春更繁。","從容一衲分若有，蕭瑟兩鬢吾能髠。","逢迎侯伯轉覺貴，膜拜佛像心加尊。","稍揖皇英頮濃淚，試與屈賈招清魂。","荒唐大樹悉楠桂，細碎枯草多蘭蓀。","沙彌去學五印字，靜女來懸千尺幡。","主人念我塵眼昏，半夜號令期至暾。","遲回難得上白舫，羈泄不敢言綠尊。","兩祠物色採拾盡，壁間杜甫真少恩。","晚來光彩更騰射，筆鋒正健如可吞。"]', '["道林岳麓仲與昆，卓犖請從先後論。","松根踏云二千步，始见大屋开三门。","泉清或戲蛟龙窟，殿豁數尽高帆掀。","即今異鸟声不斷，闻道看花春更繁。","從容一衲分若有，蕭瑟兩鬢吾能髠。","逢迎侯伯轉覺貴，膜拜佛像心加尊。","稍揖皇英頮濃泪，試與屈賈招清魂。","荒唐大樹悉楠桂，細碎枯草多蘭蓀。","沙彌去学五印字，静女来懸千尺幡。","主人念我塵眼昏，半夜號令期至暾。","遲回难得上白舫，羈泄不敢言綠尊。","兩祠物色採拾尽，壁间杜甫真少恩。","晚来光彩更腾射，笔鋒正健如可吞。"]', '诗', 'shi', '', NULL, '使南海道長沙題道林岳麓寺 唐扶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08b538e-8fca-4237-a266-4609a36d7620', '和兵部鄭侍郎省中四松詩', '和兵部鄭侍郎省中四松诗', '577e373e-baf6-4547-9e0c-146b688138ab', '唐', '["幽抱應無語，貞松遂自栽。","寄懷丞相業，因擢大夫材。","日射蒼鱗動，塵迎翠箒迴。","嫩茸含細粉，初葉泛新桮。","偶聖爲舟去，逢時與鶴來。","寒聲連曉竹，靜氣結陰苔。","赫奕鳴騶至，熒煌洞戶開。","良辰一臨眺，憩樹幾裴回。","恨發風期阻，詩從綺思裁。","還聞舊凋契，凡在此中培。"]', '["幽抱應無語，貞松遂自栽。","寄懷丞相業，因擢大夫材。","日射蒼鱗动，塵迎翠箒迴。","嫩茸含細粉，初葉泛新桮。","偶聖爲舟去，逢时與鹤来。","寒声連晓竹，静氣結陰苔。","赫奕鳴騶至，熒煌洞戶开。","良辰一臨眺，憩樹幾裴回。","恨發风期阻，诗從綺思裁。","還闻旧凋契，凡在此中培。"]', '诗', 'shi', '', NULL, '和兵部鄭侍郎省中四松詩 唐扶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37201913-42e3-4b2d-a331-3ad5cb5b0bb7', '和兵部鄭侍郎省中四松詩', '和兵部鄭侍郎省中四松诗', '77861cfd-2c9e-4686-83fb-4e155ad63968', '唐', '["右相歷兵署，四松皆手栽。","斸時驚鶴去，移處帶雲來。","根倍雙桐植，花分八桂開。","生成造化力，長作棟梁材。","豈羨蘭依省，猶嫌柏占臺。","出樓終百尺，入夢已三台。","幽韻和宮漏，餘香度酒杯。","拂冠枝上雪，染履影中苔。","高位相承地，新詩寡和才。","何由比蘿蔓，攀附在條枚。"]', '["右相歷兵署，四松皆手栽。","斸时驚鹤去，移处带云来。","根倍雙桐植，花分八桂开。","生成造化力，长作棟梁材。","豈羨蘭依省，猶嫌柏占台。","出楼終百尺，入梦已三台。","幽韻和宮漏，餘香度酒杯。","拂冠枝上雪，染履影中苔。","高位相承地，新诗寡和才。","何由比蘿蔓，攀附在條枚。"]', '诗', 'shi', '', NULL, '和兵部鄭侍郎省中四松詩 陶雍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a85b80f8-2f9b-423a-993d-587f00ee24ab', '譚子池', '譚子池', 'f3f140fa-b067-49e3-bce1-cba283290e41', '唐', '["澄水一百步，世名譚子池。","余詰陵陽叟，此池當因誰。","父老謂余說，本郡譚叔皮。","開元末年中，生子字阿宜。","墜地便能語，九歲多鬚眉。","不飲亦不食，未嘗言渴飢。","十五銳行走，快馬不能追。","二十入山林，一去無還期。","父母憶念深，鄉閭爲立祠。","大曆元年春，此兒忽來歸。","頭冠簪鳳皇，身著霞裳衣。","普遍拯疲俗，丁寧告親知。","余爲神仙官，下界不可祈。","恐爲妖魅假，不如早平夷。","此有黃金藏，鎮在茲廟基。","發掘散生聚，可以救貧羸。","金出繼靈泉，湛若清琉璃。","泓澄表符瑞，水旱無竭時。","言訖辭沖虛，杳靄上玄微。","凡情留不得，攀望衆號悲。","尋稟神仙誡，徹廟斸開窺。","果獲無窮寶，均融霑困危。","巨源出嶺頂，噴湧世間稀。","異境流千古，終年福四維。"]', '["澄水一百步，世名譚子池。","余詰陵陽叟，此池當因誰。","父老謂余说，本郡譚叔皮。","开元末年中，生子字阿宜。","墜地便能語，九歲多鬚眉。","不饮亦不食，未嘗言渴飢。","十五銳行走，快马不能追。","二十入山林，一去無還期。","父母憶念深，乡閭爲立祠。","大曆元年春，此兒忽来归。","头冠簪鳳皇，身著霞裳衣。","普遍拯疲俗，丁寧告親知。","余爲神仙官，下界不可祈。","恐爲妖魅假，不如早平夷。","此有黄金藏，鎮在茲廟基。","發掘散生聚，可以救貧羸。","金出繼靈泉，湛若清琉璃。","泓澄表符瑞，水旱無竭时。","言訖辞沖虛，杳靄上玄微。","凡情留不得，攀望衆號悲。","尋稟神仙誡，徹廟斸开窺。","果獲無窮寶，均融霑困危。","巨源出嶺頂，噴湧世间稀。","異境流千古，終年福四維。"]', '诗', 'shi', '', NULL, '譚子池 郭周藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d121b6-8e10-4dce-b0dd-c373b74654dc', '金谷園花發懷古', '金谷园花發懷古', '83ea587f-a8d3-40f1-aff8-d53587e35ce3', '唐', '["金谷千年後，春花發滿園。","紅芳徒笑日，穠豔尚迎軒。","雨濕輕光軟，風搖碎影翻。","猶疑施錦帳，堪歎罷朱紈。","愁態鶯吟澀，啼容露綴繁。","慇懃問前事，桃李竟無言。"]', '["金谷千年後，春花發满园。","紅芳徒笑日，穠豔尚迎軒。","雨濕轻光軟，风搖碎影翻。","猶疑施錦帳，堪歎罷朱紈。","愁態鶯吟澀，啼容露綴繁。","慇懃问前事，桃李竟無言。"]', '诗', 'shi', '', NULL, '金谷園花發懷古 侯冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6c69b03-f779-4961-a4ef-4a82baf3da9f', '花發上林', '花發上林', '83ea587f-a8d3-40f1-aff8-d53587e35ce3', '唐', '["花發三陽盛，香飄五柞深。","素暉雲積苑，紅彩繡張林。","落水隨魚戲，搖風映鳥吟。","瓊樓出高豔，玉輦駐濃陰。","亂蝶枝開影，繁蜂蘂上音。","鮮芳盈禁籞，布澤荷天心。"]', '["花發三陽盛，香飄五柞深。","素暉云積苑，紅彩繡張林。","落水隨鱼戲，搖风映鸟吟。","瓊楼出高豔，玉輦駐濃陰。","亂蝶枝开影，繁蜂蘂上音。","鲜芳盈禁籞，布澤荷天心。"]', '诗', 'shi', '', NULL, '花發上林 侯冽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cebecba-1673-44c6-a83b-e525e331bad5', '金谷園花發懷古', '金谷园花發懷古', '3d44f55c-c392-46e6-b046-9a60fc5be3a2', '唐', '["寂寥金谷澗，花發舊時園。","人事空懷古，煙霞此獨存。","管弦非上客，歌舞少王孫。","繁蘂風驚散，輕紅鳥乍翻。","山川終不改，桃李自無言。","今日經塵路，淒涼詎可論。"]', '["寂寥金谷澗，花發旧时园。","人事空懷古，煙霞此独存。","管弦非上客，歌舞少王孫。","繁蘂风驚散，轻紅鸟乍翻。","山川終不改，桃李自無言。","今日經塵路，淒涼詎可論。"]', '诗', 'shi', '', NULL, '金谷園花發懷古 王質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19387623-b6c7-4a43-90c0-6c2208eab545', '和太原張相公山亭懷古', '和太原張相公山亭懷古', '231b3e8c-089c-4a46-8059-7b05ee760183', '唐', '["鬬石類巖巘，飛流瀉潺湲。","遠壑簷宇際，孤巒雉堞間。","何必到海岳，境幽機自閑。","茲焉得高趣，高步謝東山。"]', '["鬬石類巖巘，飞流瀉潺湲。","远壑簷宇際，孤巒雉堞间。","何必到海岳，境幽機自闲。","茲焉得高趣，高步謝东山。"]', '诗', 'shi', '', NULL, '和太原張相公山亭懷古 高銖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f3f5c8-ea7b-4b37-b96d-e1fb5a1ebe00', '八月五日中部官舍讀唐曆天寶已來追愴故事', '八月五日中部官舍读唐曆天寶已来追愴故事', 'ca192c17-2433-4371-a87b-d46bb9c29767', '唐', '["將尋國朝事，靜讀柳芳曆。","八月日之五，開卷忽感激。","正當天寶末，撫事坐追惜。","仰思聖明帝，貽禍在肘腋。","楊李盜吏權，貪殘日狼籍。","燕戎伺其便，百萬奮長戟。","兩河連煙塵，二京成瓦礫。","生人死欲盡，揳業猶不息。","肅宗傳寶圖，寇難連年擊。","天地方開泰，鑄鼎成繼述。","萬國哭龍衮，悲思動蠻[貊]。","自此千秋節，不復動金石。","悲風揚霜天，繐帷冷塵席。","零落太平老，東西亂離客。","往往爲余言，嗚咽淚雙滴。","況當近塞地，哀吹起邊笛。","撫几觀陳文，使我心不懌。","花萼笑繁華，溫泉樹容碧。","霓裳煙雲盡，梨園風雨隔。","露囊與金鏡，東逝驚波溺。","昔聞歡娛事，今日成慘慼。","神仙不可求，劒璽苔文積。","萬古長恨端，蕭蕭泰陵陌。"]', '["將尋国朝事，静读柳芳曆。","八月日之五，开卷忽感激。","正當天寶末，撫事坐追惜。","仰思聖明帝，貽禍在肘腋。","楊李盜吏權，貪殘日狼籍。","燕戎伺其便，百万奮长戟。","兩河連煙塵，二京成瓦礫。","生人死欲尽，揳業猶不息。","肅宗傳寶圖，寇难連年擊。","天地方开泰，鑄鼎成繼述。","万国哭龙衮，悲思动蠻[貊]。","自此千秋節，不复动金石。","悲风揚霜天，繐帷冷塵席。","零落太平老，东西亂離客。","往往爲余言，嗚咽泪雙滴。","況當近塞地，哀吹起邊笛。","撫几观陳文，使我心不懌。","花萼笑繁华，溫泉樹容碧。","霓裳煙云尽，梨园风雨隔。","露囊與金镜，东逝驚波溺。","昔闻歡娛事，今日成慘慼。","神仙不可求，劒璽苔文積。","万古长恨端，蕭蕭泰陵陌。"]', '诗', 'shi', '', NULL, '八月五日中部官舍讀唐曆天寶已來追愴故事 舒元輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61a43cef-fa94-4700-bfd7-f2d8c1144294', '坊州按獄', '坊州按獄', 'ca192c17-2433-4371-a87b-d46bb9c29767', '唐', '["中部接戎塞，頑山四周遭。","風冷木長瘦，石磽人亦勞。","牧守苟懷仁，癢之時爲搔。","其愛如赤子，始得無啼號。","奈何貪狼心，潤屋沈脂膏。","攫搏如猛虎，吞噬若狂獒。","山禿逾高採，水窮益深撈。","龜魚即絕跡，鹿兔無遺毛。","氓苦稅外緡，吏憂笑中刀。","大君明四目，燭之洞秋毫。","眷茲一州命，慮齊墜波濤。","臨軒詔小臣，汝往窮貪饕。","分明舉公法，爲我緩窮騷。","小臣誠小心，奉命如煎熬。","飲冰不待夕，驅馬凌晨臯。","及此督簿書，遊詞出狴牢。","門牆見狼狽，案牘聞腥臊。","探情與之言，變態如姦猱。","真非既巧飾，僞意乃深韜。","去惡猶農夫，稂莠須耘耨。","恢恢布疎網，罪者何由逃。","自顧孱鈍姿，利器非能操。","六旬始歸奏，霜落秋原蒿。","寄謝守土臣，努力清郡曹。","須知聽甚卑，勿謂天之高。"]', '["中部接戎塞，頑山四周遭。","风冷木长瘦，石磽人亦勞。","牧守苟懷仁，癢之时爲搔。","其愛如赤子，始得無啼號。","奈何貪狼心，潤屋沈脂膏。","攫搏如猛虎，吞噬若狂獒。","山禿逾高採，水窮益深撈。","龟鱼即絕跡，鹿兔無遺毛。","氓苦稅外緡，吏憂笑中刀。","大君明四目，燭之洞秋毫。","眷茲一州命，慮齊墜波濤。","臨軒詔小臣，汝往窮貪饕。","分明舉公法，爲我緩窮騷。","小臣誠小心，奉命如煎熬。","饮冰不待夕，驱马凌晨臯。","及此督簿书，游词出狴牢。","门牆见狼狽，案牘闻腥臊。","探情與之言，变態如姦猱。","真非既巧飾，僞意乃深韜。","去惡猶農夫，稂莠須耘耨。","恢恢布疎網，罪者何由逃。","自顧孱鈍姿，利器非能操。","六旬始归奏，霜落秋原蒿。","寄謝守土臣，努力清郡曹。","須知听甚卑，勿謂天之高。"]', '诗', 'shi', '', NULL, '坊州按獄 舒元輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a05f18-277c-410c-b4bf-11d9e9e5589e', '橋山懷古', '橋山懷古', 'ca192c17-2433-4371-a87b-d46bb9c29767', '唐', '["軒轅厭代千萬秋，淥波浩蕩東南流。","今來古往無不死，獨有天地長悠悠。","我乘驛騎到中部，古聞此地爲渠搜。","橋山突兀在其左，荒榛交鏁寒風愁。","神仙天下亦如此，況我慼促同蜉蝣。","誰言衣冠葬其下，不見弓劒何人收。","哀喧呌笑牧童戲，陰天月落狐狸遊。","却思皇墳立人極，車輪馬跡無不周。","洞庭張樂降玄鶴，涿鹿大戰摧蚩尤。","知勇神天不自大，風后力牧輸長籌。","襄城迷路問童子，帝鄉歸去無人留。","崆峒求道失遺跡，荆山鑄鼎餘荒丘。","君不見黃龍飛去山下路，斷髯成草風颼颼。"]', '["軒轅厭代千万秋，淥波浩蕩东南流。","今来古往無不死，独有天地长悠悠。","我乘驛騎到中部，古闻此地爲渠搜。","橋山突兀在其左，荒榛交鏁寒风愁。","神仙天下亦如此，況我慼促同蜉蝣。","誰言衣冠葬其下，不见弓劒何人收。","哀喧呌笑牧童戲，陰天月落狐狸游。","却思皇墳立人極，车輪马跡無不周。","洞庭張乐降玄鹤，涿鹿大戰摧蚩尤。","知勇神天不自大，风后力牧輸长籌。","襄城迷路问童子，帝乡归去無人留。","崆峒求道失遺跡，荆山鑄鼎餘荒丘。","君不见黄龙飞去山下路，斷髯成草风颼颼。"]', '诗', 'shi', '', NULL, '橋山懷古 舒元輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f005e39-eb18-4fc5-863c-019384013154', '坊州按獄蘇氏莊記室二賢自鄜州走馬相訪留連數日發後獨坐寂寞因成詩寄之', '坊州按獄蘇氏莊記室二賢自鄜州走马相訪留連數日發後独坐寂寞因成诗寄之', 'ca192c17-2433-4371-a87b-d46bb9c29767', '唐', '["十年一相見，世俗信多岐。","雲雨易分散，山川長間之。","我銜鳳闕恩，按獄橋山陲。","君在龍驤府，掌奏羽檄詞。","相去百餘里，魂夢自相馳。","形容在胸臆，書札通相思。","煩君愛我深，輕車忽載脂。","塞門秋色老，霜氣方凝姿。","此地少平川，岡阜相參差。","誰知路非遠，行者多云疲。","君能犯勁風，信宿凌欹危。","情親不自倦，下馬開雙眉。","相對坐沉吟，屈指驚歲時。","萬事且莫問，一杯欣共持。","陽烏忽西傾，明蟾挂高枝。","卷簾引瑤玉，滅燭臨霜墀。","中庭有疎蘆，淅淅聞風吹。","長河卷雲色，凝碧無瑕疵。","一言開我懷，曠然澹希夷。","悠悠夜方永，冷思偏相宜。","眉睫無他人，與君閑解題。","陶然叩寂寞，更請吟清詩。","得意且忘言，何況竹與絲。","頃刻過三夕，起坐輕四肢。","明朝告行去，慘然還別離。","出門送君去，君馬揚金羈。","迴來坐空堂，寂寞無人知。"]', '["十年一相见，世俗信多岐。","云雨易分散，山川长间之。","我銜鳳闕恩，按獄橋山陲。","君在龙驤府，掌奏羽檄词。","相去百餘里，魂梦自相驰。","形容在胸臆，书札通相思。","煩君愛我深，轻车忽載脂。","塞门秋色老，霜氣方凝姿。","此地少平川，岡阜相參差。","誰知路非远，行者多云疲。","君能犯勁风，信宿凌欹危。","情親不自倦，下马开雙眉。","相对坐沉吟，屈指驚歲时。","万事且莫问，一杯欣共持。","陽烏忽西傾，明蟾挂高枝。","卷簾引瑤玉，滅燭臨霜墀。","中庭有疎蘆，淅淅闻风吹。","长河卷云色，凝碧無瑕疵。","一言开我懷，曠然澹希夷。","悠悠夜方永，冷思偏相宜。","眉睫無他人，與君闲解題。","陶然叩寂寞，更請吟清诗。","得意且忘言，何況竹與絲。","頃刻過三夕，起坐轻四肢。","明朝告行去，慘然還別離。","出门送君去，君马揚金羈。","迴来坐空堂，寂寞無人知。"]', '诗', 'shi', '', NULL, '坊州按獄蘇氏莊記室二賢自鄜州走馬相訪留連數日發後獨坐寂寞因成詩寄之 舒元輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2f4134-1086-417e-823e-9d7520565734', '履春冰', '履春冰', 'ca192c17-2433-4371-a87b-d46bb9c29767', '唐', '["投跡清冰上，凝光動早春。","兢兢愁陷履，步步怯移身。","鳥照微生水，狐聽或過人。","細遷形外影，輕躡鏡中輪。","咫尺憂偏遠，危疑懼已頻。","願堅容足分，莫使獨驚神。"]', '["投跡清冰上，凝光动早春。","兢兢愁陷履，步步怯移身。","鸟照微生水，狐听或過人。","細遷形外影，轻躡镜中輪。","咫尺憂偏远，危疑懼已頻。","願堅容足分，莫使独驚神。"]', '诗', 'shi', '', NULL, '履春冰 舒元輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c10c09d5-198e-49c6-bd4c-c8a4e9fb3b74', '贈李翺', '贈李翺', 'ca192c17-2433-4371-a87b-d46bb9c29767', '唐', '["湘江舞罷忽成悲，便脫蠻靴出絳帷。","誰是蔡邕琴酒客，魏公懷舊嫁文姬。"]', '["湘江舞罷忽成悲，便脫蠻靴出絳帷。","誰是蔡邕琴酒客，魏公懷旧嫁文姬。"]', '诗', 'shi', '', NULL, '贈李翺 舒元輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff7fafbf-e19a-4a7c-980f-272855e8697c', '登長安慈恩寺塔', '登长安慈恩寺塔', '58a20f63-c5a5-4edd-82f5-fcc5ba0f3b40', '唐', '["東方曉日上翔鸞，西轉蒼龍拂露盤。","渭水寒光搖藻井，玉峰晴色上朱闌。","九重宮闕參差見，百二山河表裏觀。","蹔輟去蓬悲不定，一凭金界望長安。"]', '["东方晓日上翔鸾，西轉蒼龙拂露盤。","渭水寒光搖藻井，玉峰晴色上朱闌。","九重宮闕參差见，百二山河表裏观。","蹔輟去蓬悲不定，一凭金界望长安。"]', '诗', 'shi', '', NULL, '登長安慈恩寺塔 盧宗回 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf99789-f0e2-4426-a983-c0c4e4a54c02', '古鏡歌', '古镜歌', 'b84e79b6-bd64-45ff-b2a2-8596498c9971', '唐', '["軒轅鑄鏡誰將去，曾被良工瀉金取。","明月心中桂不生，輕冰面上菱初吐。","蛟龍久無雷雨聲，鸞鳳空踏莓苔舞。","欲向高臺對曉開，不知誰是孤光主。"]', '["軒轅鑄镜誰將去，曾被良工瀉金取。","明月心中桂不生，轻冰面上菱初吐。","蛟龙久無雷雨声，鸾鳳空踏莓苔舞。","欲向高台对晓开，不知誰是孤光主。"]', '诗', 'shi', '', NULL, '古鏡歌 周匡物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2864a846-fb51-470c-9ab9-1ee5aeb7ed12', '及第謠', '及第謠', 'b84e79b6-bd64-45ff-b2a2-8596498c9971', '唐', '["水國寒消春日長，燕鶯催促花枝忙。","風吹金榜落凡世，三十三人名字香。","遙望龍墀新得意，九天勅下多狂醉。","驊騮一百三十蹄，踏破蓬萊五雲地。","物經千載出塵埃，從此便爲天下瑞。"]', '["水国寒消春日长，燕鶯催促花枝忙。","风吹金榜落凡世，三十三人名字香。","遙望龙墀新得意，九天勅下多狂醉。","驊騮一百三十蹄，踏破蓬萊五云地。","物經千載出塵埃，從此便爲天下瑞。"]', '诗', 'shi', '', NULL, '及第謠 周匡物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ad0f6d3-0168-44c5-9287-5998f18a03bc', '及第後謝座主', '及第後謝座主', 'b84e79b6-bd64-45ff-b2a2-8596498c9971', '唐', '["一縱東越入西秦，十度聞鶯不見春。","試向崑山投瓦礫，便容靈沼濯埃塵。","悲歡暗負風雲力，感激潛生草木身。","中夜自將形影語，古來吞炭是何人。"]', '["一縱东越入西秦，十度闻鶯不见春。","試向崑山投瓦礫，便容靈沼濯埃塵。","悲歡暗負风云力，感激潛生草木身。","中夜自將形影語，古来吞炭是何人。"]', '诗', 'shi', '', NULL, '及第後謝座主 周匡物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e7ccc08-1ca4-42a4-a0c3-b14401aa5ecf', '自題讀書堂', '自題读书堂', 'b84e79b6-bd64-45ff-b2a2-8596498c9971', '唐', '["窗外捲簾侵碧落，檻前敲竹嚮青冥。","黃昏不欲留人宿，雲起風生龍虎醒。"]', '["窗外捲簾侵碧落，檻前敲竹嚮青冥。","黄昏不欲留人宿，云起风生龙虎醒。"]', '诗', 'shi', '', NULL, '自題讀書堂 周匡物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('254c4cd0-d581-445f-9bb0-ecb42bcd7937', '應舉題錢塘公館', '應舉題錢塘公館', 'b84e79b6-bd64-45ff-b2a2-8596498c9971', '唐', '["萬里茫茫天塹遙，秦皇底事不安橋。","錢塘江口無錢過，又阻西陵兩信潮。"]', '["万里茫茫天塹遙，秦皇底事不安橋。","錢塘江口無錢過，又阻西陵兩信潮。"]', '诗', 'shi', '', NULL, '應舉題錢塘公館 周匡物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94ac20fc-63c7-4e81-9136-10b40842a946', '題旅櫬', '題旅櫬', '4b98957a-485f-4d58-b54d-6781183a874e', '唐', '["嗟君沒世委空囊，幾度勞心翰墨場。"]', '["嗟君沒世委空囊，幾度勞心翰墨場。"]', '诗', 'shi', '', NULL, '題旅櫬 廖有方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e3b505d-7444-47fc-8b0d-3c73e0d616c6', '立春日呈宮傅侍郎', '立春日呈宮傅侍郎', '00fa3bf2-ac76-4fc2-9171-a1d4d0319966', '唐', '["朝旦微風吹曉霞，散爲和氣滿家家。","不知容貌潛消落，且喜春光動物華。","出問池冰猶塞岸，歸尋園柳未生芽。","摩娑酒甕重封閉，待入新年共賞花。"]', '["朝旦微风吹晓霞，散爲和氣满家家。","不知容貌潛消落，且喜春光动物华。","出问池冰猶塞岸，归尋园柳未生芽。","摩娑酒甕重封閉，待入新年共賞花。"]', '诗', 'shi', '', NULL, '立春日呈宮傅侍郎 皇甫曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fc9aa7b-17b6-4b54-b463-b19bab873234', '賦得玉聲如樂', '賦得玉声如乐', 'a496f5b7-7e38-4645-95b7-a4c1f9e6244d', '唐', '["表質自堅貞，因人一扣鳴。","靜將金並響，妙與樂同聲。","杳杳疑風送，泠泠似曲成。","韻含湘瑟切，音帶舜弦清。","不獨藏虹氣，猶能暢物情。","后夔如爲聽，從此振琮琤。"]', '["表質自堅貞，因人一扣鳴。","静將金並响，妙與乐同声。","杳杳疑风送，泠泠似曲成。","韻含湘瑟切，音带舜弦清。","不独藏虹氣，猶能暢物情。","后夔如爲听，從此振琮琤。"]', '诗', 'shi', '', NULL, '賦得玉聲如樂 潘存實 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d84edc-a6c2-4fc3-b2b8-3349c971c7e8', '送林刺史簡言之漳州', '送林刺史簡言之漳州', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["江樹欲含曛，清歌一送君。","征驂辭荔浦，別袂暗松雲。","路狹橫柯度，山深墜葉聞。","明朝宿何處，未忍醉中分。"]', '["江樹欲含曛，清歌一送君。","征驂辞荔浦，別袂暗松云。","路狹橫柯度，山深墜葉闻。","明朝宿何处，未忍醉中分。"]', '诗', 'shi', '', NULL, '送林刺史簡言之漳州 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d07fed2b-5187-4dab-8875-f62bdbdb6fef', '憶山中', '憶山中', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["長吟重悒然，爲憶山中年。","清瑟泛遙夜，亂花隨暮煙。","珠林餘露氣，乳竇滴香泉。","跡遠塵埃外，花開綺藻前。","巖羅雲貌逸，竹抱水容妍。","蕙磴飛英遶，萍潭片影懸。","林藏諸曲勝，臺擅一峰偏。","會可標真寄，焚香對石筵。"]', '["长吟重悒然，爲憶山中年。","清瑟泛遙夜，亂花隨暮煙。","珠林餘露氣，乳竇滴香泉。","跡远塵埃外，花开綺藻前。","巖羅云貌逸，竹抱水容妍。","蕙磴飞英遶，萍潭片影懸。","林藏諸曲勝，台擅一峰偏。","會可標真寄，焚香对石筵。"]', '诗', 'shi', '', NULL, '憶山中 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ec4948-b06c-4306-9e23-5a0c4bf2c494', '元夕京城和歐陽衮', '元夕京城和歐陽衮', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["蘭焰芳芬徹曉開，珠光新靄映人來。","歌迎甲夜催銀管，影動繁星綴玉臺。","別有朱門春澹蕩，不妨芝火翠崔嵬。"]', '["蘭焰芳芬徹晓开，珠光新靄映人来。","歌迎甲夜催銀管，影动繁星綴玉台。","別有朱门春澹蕩，不妨芝火翠崔嵬。"]', '诗', 'shi', '', NULL, '元夕京城和歐陽衮 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('608a774e-46b3-4398-b8ef-3bdda66b739f', '送韓將軍之鴈門', '送韓將軍之鴈门', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["荒塞峰煙百道馳，鴈門風色暗旌旗。","破圍鐵騎長驅疾，飲血將軍轉戰危。","畫角吹開邊月靜，縵纓不信虜塵窺。","歸來長揖功成後，黃石當年故有期。"]', '["荒塞峰煙百道驰，鴈门风色暗旌旗。","破圍鐵騎长驱疾，饮血將軍轉戰危。","畫角吹开邊月静，縵纓不信虜塵窺。","归来长揖功成後，黄石當年故有期。"]', '诗', 'shi', '', NULL, '送韓將軍之鴈門 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1dfe31c-e559-4b84-b675-683cea1bbebb', '賦得騏驥長鳴', '賦得騏驥长鳴', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["騏驥忻知己，嘶鳴忽異常。","積悲攄怨抑，一舉徹穹蒼。","迹類三年鳥，心馳五達莊。","何言從蹇躓，今日逐騰驤。","牛皁休維縶，天衢恣陸梁。","向非逢伯樂，誰足見其長。"]', '["騏驥忻知己，嘶鳴忽異常。","積悲攄怨抑，一舉徹穹蒼。","迹類三年鸟，心驰五達莊。","何言從蹇躓，今日逐腾驤。","牛皁休維縶，天衢恣陸梁。","向非逢伯乐，誰足见其长。"]', '诗', 'shi', '', NULL, '賦得騏驥長鳴 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac5b2e1-ecc7-49a3-b317-30edb0cf2404', '偶題', '偶題', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["魂夢天南垂，宿昔萬里道。","池臺花氣深，到處生春草。"]', '["魂梦天南垂，宿昔万里道。","池台花氣深，到处生春草。"]', '诗', 'shi', '', NULL, '偶題 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca055d23-e444-4523-ac89-7f9384dfd94c', '春宮曲', '春宮曲', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["流鶯春曉喚櫻桃，花外傳呼殿影高。","抱裏琵琶最承寵，君王勅賜玉檀槽。"]', '["流鶯春晓喚櫻桃，花外傳呼殿影高。","抱裏琵琶最承寵，君王勅賜玉檀槽。"]', '诗', 'shi', '', NULL, '春宮曲 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61910feb-385f-40e9-8a51-1b356ecf21a8', '采蓮曲', '采蓮曲', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["粉光花色葉中開，荷氣衣香水上來。","棹響清潭見斜領，雙鴛何事亦相猜。"]', '["粉光花色葉中开，荷氣衣香水上来。","棹响清潭见斜領，雙鴛何事亦相猜。"]', '诗', 'shi', '', NULL, '采蓮曲 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f55da3dd-e810-4e90-b065-acb1459bf7c5', '踏歌行 一', '踏歌行 一', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["鴛鴦樓下萬花新，翡翠宮前百戲陳。","夭矯翔龍銜火樹，飛來瑞鳳散芳春。"]', '["鴛鴦楼下万花新，翡翠宮前百戲陳。","夭矯翔龙銜火樹，飞来瑞鳳散芳春。"]', '诗', 'shi', '', NULL, '踏歌行 一 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa068d91-f11f-4117-a87d-9643c1fec8b9', '踏歌行 二', '踏歌行 二', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["仙蹕初傳紫禁香，瑞雲開處夜花芳。","繁弦促管升平調，綺綴丹蓮借月光。"]', '["仙蹕初傳紫禁香，瑞云开处夜花芳。","繁弦促管升平調，綺綴丹蓮借月光。"]', '诗', 'shi', '', NULL, '踏歌行 二 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f4b9db-bd91-4ee3-96d1-25f0e4971191', '塞下曲', '塞下曲', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["春至金河雪似花，蕭條玉塞但胡沙。","曉來重上關城望，惟見驚塵不見家。"]', '["春至金河雪似花，蕭條玉塞但胡沙。","晓来重上关城望，惟见驚塵不见家。"]', '诗', 'shi', '', NULL, '塞下曲 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f8277a2-8d19-4104-bc98-531e293bb85f', '送人謫幽州', '送人謫幽州', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["臨路深懷放廢慚，夢中猶自憶江南。","莫言塞北春風少，還勝炎荒入瘴嵐。"]', '["臨路深懷放廢慚，梦中猶自憶江南。","莫言塞北春风少，還勝炎荒入瘴嵐。"]', '诗', 'shi', '', NULL, '送人謫幽州 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb3dfbf-8e29-4a6e-a589-57c158100882', '西上辭母墳', '西上辞母墳', '6e510a30-b107-4b37-b466-16dfa47bcfbd', '唐', '["高蓋山頭日影微，黃昏獨立宿禽稀。","林間滴酒空垂淚，不見丁寧囑早歸。"]', '["高蓋山头日影微，黄昏独立宿禽稀。","林间滴酒空垂泪，不见丁寧囑早归。"]', '诗', 'shi', '', NULL, '西上辭母墳 陳去疾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df9886f-9eeb-4974-9813-418b92f62fb2', '履春冰', '履春冰', '52966ee9-6b26-48e4-a71b-eb49dcd095aa', '唐', '["一步一愁新，輕輕恐陷人。","薄光全透日，殘影半銷春。","蟬想行時翼，魚驚蹋處鱗。","底虛難駐足，岸闊怯迴身。","豈暇踟躕久，寧辭顧盼頻。","願將兢慎意，從此赴通津。"]', '["一步一愁新，轻轻恐陷人。","薄光全透日，殘影半銷春。","蟬想行时翼，鱼驚蹋处鱗。","底虛难駐足，岸闊怯迴身。","豈暇踟躕久，寧辞顧盼頻。","願將兢慎意，從此赴通津。"]', '诗', 'shi', '', NULL, '履春冰 張蕭遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9687a143-c526-4bdc-b779-f95ea0de8e69', '觀燈', '观灯', '52966ee9-6b26-48e4-a71b-eb49dcd095aa', '唐', '["十萬人家火燭光，門門開處見紅妝。","歌鐘喧夜更漏暗，羅綺滿街塵土香。","星宿別從天畔出，蓮花不向水中芳。","寶釵驟馬多遺落，依舊明朝在路傍。"]', '["十万人家火燭光，门门开处见紅妝。","歌鐘喧夜更漏暗，羅綺满街塵土香。","星宿別從天畔出，蓮花不向水中芳。","寶釵驟马多遺落，依旧明朝在路傍。"]', '诗', 'shi', '', NULL, '觀燈 張蕭遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59b3e4d-be19-4eb5-9973-5715571286d1', '送宮人入道', '送宮人入道', '52966ee9-6b26-48e4-a71b-eb49dcd095aa', '唐', '["捨寵求仙畏色衰，辭天素面立堦墀。","金丹擬駐千年貌，玉指休勻八字眉。","師主與收珠翠後，君王看戴角冠時。","從來宮女皆相妬，聞向瑤臺盡淚垂。"]', '["捨寵求仙畏色衰，辞天素面立堦墀。","金丹擬駐千年貌，玉指休勻八字眉。","師主與收珠翠後，君王看戴角冠时。","從来宮女皆相妬，闻向瑤台尽泪垂。"]', '诗', 'shi', '', NULL, '送宮人入道 張蕭遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3677fc-4aae-4269-9ad3-ba301f27aa6e', '句', '句', '52966ee9-6b26-48e4-a71b-eb49dcd095aa', '唐', '["秦雲寂寂僧還定，盡日無人鹿遶牀。","日暮風吹官渡柳，白鵶飛出石頭牆。","雙雙白燕入詞堂。"]', '["秦云寂寂僧還定，尽日無人鹿遶牀。","日暮风吹官渡柳，白鵶飞出石头牆。","雙雙白燕入词堂。"]', '诗', 'shi', '', NULL, '句 張蕭遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd6ae1a7-051d-44d4-8d5d-bf790209a438', '見志', '见志', '13f7b2aa-1470-42f9-9ca6-fac4b26349ef', '唐', '["去歲買琴不與價，今年沽酒未還錢。","門前債主雁行立，屋裏醉人魚貫眠。"]', '["去歲買琴不與價，今年沽酒未還錢。","门前債主雁行立，屋裏醉人鱼貫眠。"]', '诗', 'shi', '', NULL, '見志 李播 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a7da93-3623-4caa-88b6-17cf3fa84ebc', '魚上冰', '鱼上冰', '82741b90-1ce1-4dc2-bc1a-ca7aa7c167d2', '唐', '["北陸收寒盡，東風解凍初。","冰消通淺溜，氣變躍潛魚。","應節似知化，揚鬐任所如。","浮沈非樂藻，沿泝異傳書。","結網時空久，臨川意有餘。","爲龍將可望，今日媿才虛。"]', '["北陸收寒尽，东风解凍初。","冰消通淺溜，氣变躍潛鱼。","應節似知化，揚鬐任所如。","浮沈非乐藻，沿泝異傳书。","結網时空久，臨川意有餘。","爲龙將可望，今日媿才虛。"]', '诗', 'shi', '', NULL, '魚上冰 王季則 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d47b98-62c5-4133-895a-1f0d1949ab61', '魚上冰', '鱼上冰', 'a62410f4-52cd-4616-be07-f65a4a325db0', '唐', '["春生寒氣滅，稍動伏泉魚。","乍喜東風至，來觀曲浦初。","近冰朱鬣見，望日錦鱗舒。","漸覺流澌退，還忻掉尾餘。","噞喁情自樂，沿泝意寧疎。","儻得隨鯤化，終能戾太虛。"]', '["春生寒氣滅，稍动伏泉鱼。","乍喜东风至，来观曲浦初。","近冰朱鬣见，望日錦鱗舒。","漸覺流澌退，還忻掉尾餘。","噞喁情自乐，沿泝意寧疎。","儻得隨鯤化，終能戾太虛。"]', '诗', 'shi', '', NULL, '魚上冰 紀元臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad6b76d-ba12-4cdd-b597-2382e8a4ee39', '魚上冰', '鱼上冰', 'b1da5176-8684-48c3-875c-19899e9927c8', '唐', '["春水潛鱗發，寒潭舊藻疎。","揚鬐順氣後，振鬣上冰初。","戲廣憐空潔，浮清媚景虛。","戒貪還避餌，思達每懷書。","濕映流澌薄，狂遊觸浪餘。","終希泮渙澤，爲化北溟魚。"]', '["春水潛鱗發，寒潭旧藻疎。","揚鬐順氣後，振鬣上冰初。","戲廣怜空潔，浮清媚景虛。","戒貪還避餌，思達每懷书。","濕映流澌薄，狂游觸浪餘。","終希泮渙澤，爲化北溟鱼。"]', '诗', 'shi', '', NULL, '魚上冰 吳晃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c093e466-f501-4b24-824f-2584ef749425', '贈柳氏妓', '贈柳氏妓', 'c4e8039f-0b68-4196-a13a-c8cb63dcfac9', '唐', '["冶豔出神仙，歌聲勝管弦。","詞輕白紵曲，歌遏碧雲天。","未擬生裴秀，如何乞鄭玄。","不堪金谷水，橫過墜樓前。"]', '["冶豔出神仙，歌声勝管弦。","词轻白紵曲，歌遏碧云天。","未擬生裴秀，如何乞鄭玄。","不堪金谷水，橫過墜楼前。"]', '诗', 'shi', '', NULL, '贈柳氏妓 鄭還古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c121c33-b9a1-4153-a27a-8eff830755c6', '吉州道中', '吉州道中', 'c4e8039f-0b68-4196-a13a-c8cb63dcfac9', '唐', '["吉州新置掾，馳驛到條山。","薏苡殊非謗，羊腸未是艱。","自慚多白髮，爭敢競朱顏。","若有前生債，今朝不懊還。"]', '["吉州新置掾，驰驛到條山。","薏苡殊非謗，羊腸未是艱。","自慚多白髮，爭敢競朱顏。","若有前生債，今朝不懊還。"]', '诗', 'shi', '', NULL, '吉州道中 鄭還古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d63222-c052-4217-833d-8497032bc744', '望思臺', '望思台', 'c4e8039f-0b68-4196-a13a-c8cb63dcfac9', '唐', '["讒語能令骨肉離，姦情難測事堪悲。","何因掘得江充骨，搗作微塵祭望思。"]', '["讒語能令骨肉離，姦情难測事堪悲。","何因掘得江充骨，捣作微塵祭望思。"]', '诗', 'shi', '', NULL, '望思臺 鄭還古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e064c6-fb3e-45d1-9438-fa4543145dfa', '日南長至', '日南长至', 'ad26d6c1-7438-4853-a71f-959e6754be65', '唐', '["玉曆頒新律，凝陰發一陽。","輪輝猶惜短，圭影此偏長。","晷度經南斗，流晶盡北堂。","乍疑周戶耀，可愛逗林光。","積雪銷微照，初萌動早芒。","更升臺上望，雲物已昭彰。"]', '["玉曆頒新律，凝陰發一陽。","輪輝猶惜短，圭影此偏长。","晷度經南斗，流晶尽北堂。","乍疑周戶耀，可愛逗林光。","積雪銷微照，初萌动早芒。","更升台上望，云物已昭彰。"]', '诗', 'shi', '', NULL, '日南長至 獨孤鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a4980a7-d4ba-4c16-ba4c-b628ac2d279b', '延平天慶觀', '延平天慶观', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["劒化江邊綠構新，層臺不染玉梯塵。","千章隱篆標龍簡，一曲空歌降鳳鈞。","嵐氣濕衣雲葉晚，天香飄戶月枝春。","盟經早晚聞仙語，學種三芝伴羽人。"]', '["劒化江邊綠構新，層台不染玉梯塵。","千章隐篆標龙簡，一曲空歌降鳳鈞。","嵐氣濕衣云葉晚，天香飄戶月枝春。","盟經早晚闻仙語，学種三芝伴羽人。"]', '诗', 'shi', '', NULL, '延平天慶觀 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57444b76-3bd5-4667-8998-b0888da88a61', '送葉秀才', '送葉秀才', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["快騎璁瓏刻玉羈，河梁返照上征衣。","層冰春近蟠龍起，九澤雲閑獨鶴飛。","行想北山清夢斷，重遊西洛故人稀。","漢庭狗監深知己，有日前驅負弩歸。"]', '["快騎璁瓏刻玉羈，河梁返照上征衣。","層冰春近蟠龙起，九澤云闲独鹤飞。","行想北山清梦斷，重游西洛故人稀。","漢庭狗監深知己，有日前驱負弩归。"]', '诗', 'shi', '', NULL, '送葉秀才 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c671f7-9fc9-4028-9862-9da98d712d23', '送王秀才謁池州吳都督', '送王秀才謁池州吳都督', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["池陽去去躍雕鞍，十里長亭百草乾。","衣袂障風金鏤細，劒光橫雪玉龍寒。","晴郊別岸鄉魂斷，曉樹啼烏客夢殘。","南館星郎東道主，搖鞭休問路行難。"]', '["池陽去去躍雕鞍，十里长亭百草乾。","衣袂障风金鏤細，劒光橫雪玉龙寒。","晴郊別岸乡魂斷，晓樹啼烏客梦殘。","南館星郎东道主，搖鞭休问路行难。"]', '诗', 'shi', '', NULL, '送王秀才謁池州吳都督 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e1de59f-fb3f-4bb4-8ab0-09fa64b5e833', '青帝', '青帝', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["青帝邀春隔歲還，月娥孀獨夜漫漫。","韓憑舞羽身猶在，素女商弦調未殘。","終古蘭巖棲偶鶴，從來玉谷有離鸞。","幾時幽恨飄然斷，共待天池一水乾。"]', '["青帝邀春隔歲還，月娥孀独夜漫漫。","韓憑舞羽身猶在，素女商弦調未殘。","終古蘭巖棲偶鹤，從来玉谷有離鸾。","幾时幽恨飄然斷，共待天池一水乾。"]', '诗', 'shi', '', NULL, '青帝 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2c1310-be63-4c49-b3e1-efb7022cdea1', '銀河', '銀河', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["閶闔疎雲漏絳津，橋頭秋夜鵲飛頻。","猶殘仙媛湔帬水，幾見星妃度襪塵。","歷歷素榆飄玉葉，涓涓清月濕冰輪。","年來若有乘槎客，爲弔波靈是楚臣。"]', '["閶闔疎云漏絳津，橋头秋夜鵲飞頻。","猶殘仙媛湔帬水，幾见星妃度襪塵。","歷歷素榆飄玉葉，涓涓清月濕冰輪。","年来若有乘槎客，爲弔波靈是楚臣。"]', '诗', 'shi', '', NULL, '銀河 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b974919-a5d6-4c72-a85f-7085f5894019', '書秋', '书秋', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["千里南雲度塞鴻，秋容無跡淡平空。","人間玉嶺清宵月，天上銀河白晝風。","潘賦登山魂易斷，楚歌遺佩怨何窮。","往來未若奇張翰，欲鱠霜鯨碧海東。"]', '["千里南云度塞鴻，秋容無跡淡平空。","人间玉嶺清宵月，天上銀河白晝风。","潘賦登山魂易斷，楚歌遺佩怨何窮。","往来未若奇張翰，欲鱠霜鯨碧海东。"]', '诗', 'shi', '', NULL, '書秋 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba57838-95d0-4e43-bbdf-9289d061a237', '自和書秋', '自和书秋', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["隴首斜飛避弋鴻，頹雲蕭索見層空。","漢宮夜結雙莖露，閶闔涼生六幕風。","湘女怨弦愁不禁，鄂君香被夢難窮。","江邊兩槳連歌渡，驚散遊魚蓮葉東。"]', '["隴首斜飞避弋鴻，頹云蕭索见層空。","漢宮夜結雙莖露，閶闔涼生六幕风。","湘女怨弦愁不禁，鄂君香被梦难窮。","江邊兩槳連歌渡，驚散游鱼蓮葉东。"]', '诗', 'shi', '', NULL, '自和書秋 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5075cf-690e-4cff-9949-ff5dde8643aa', '立春後作', '立春後作', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["東君珂佩響珊珊，青馭多時下九關。","方信玉霄千萬里，春風猶未到人間。"]', '["东君珂佩响珊珊，青馭多时下九关。","方信玉霄千万里，春风猶未到人间。"]', '诗', 'shi', '', NULL, '立春後作 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5154a66-2e69-41ff-bc12-718763201e90', '梅花二首 一', '梅花二首 一', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["應爲陽春信未傳，固將青豔屬殘年。","東君欲待尋佳約，剩寄衣香與粉綿。"]', '["應爲陽春信未傳，固將青豔屬殘年。","东君欲待尋佳約，剩寄衣香與粉綿。"]', '诗', 'shi', '', NULL, '梅花二首 一 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253ad6ba-185c-4915-9b9a-95e2d1a4515a', '梅花二首 二', '梅花二首 二', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["迎春雪豔飄零極，度夕蟾華掩映多。","欲托清香傳遠信，一枝無計奈愁何。"]', '["迎春雪豔飄零極，度夕蟾华掩映多。","欲托清香傳远信，一枝無計奈愁何。"]', '诗', 'shi', '', NULL, '梅花二首 二 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f198211f-331a-4f1f-87f2-ca57cc5264cd', '春日詠梅花二首 一', '春日詠梅花二首 一', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["靚妝纔罷粉痕新，遞曉風回散玉塵。","若遣有情應悵望，已兼殘雪又兼春。"]', '["靚妝纔罷粉痕新，遞晓风回散玉塵。","若遣有情應悵望，已兼殘雪又兼春。"]', '诗', 'shi', '', NULL, '春日詠梅花二首 一 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d71a5667-a683-40ec-bb82-94373c508595', '春日詠梅花二首 二', '春日詠梅花二首 二', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["青帝來時值遠芳，殘花殘雪尚交光。","隔年擬待春消息，得見春風已斷腸。"]', '["青帝来时值远芳，殘花殘雪尚交光。","隔年擬待春消息，得见春风已斷腸。"]', '诗', 'shi', '', NULL, '春日詠梅花二首 二 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ef39ee-54bd-4c29-8cb5-0bc1a4a74693', '即夕', '即夕', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["榆葉飄零碧漢流，玉蟾珠露兩清秋。","僊家若有單棲恨，莫向銀臺半夜遊。"]', '["榆葉飄零碧漢流，玉蟾珠露兩清秋。","僊家若有單棲恨，莫向銀台半夜游。"]', '诗', 'shi', '', NULL, '即夕 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef714f7a-8241-415a-bd19-5136b5c2ffbf', '送陳校勘入宿', '送陳校勘入宿', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["日落風回卷碧霓，芳蓬一夜拆龍泥。","銀臺級級連清漢，桂子香濃月杵低。"]', '["日落风回卷碧霓，芳蓬一夜拆龙泥。","銀台級級連清漢，桂子香濃月杵低。"]', '诗', 'shi', '', NULL, '送陳校勘入宿 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34efb8ee-6813-404f-b8ba-add243a46f61', '即夕', '即夕', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["風幌涼生白袷衣，星榆纔亂絳河低。","月明休近相思樹，恐有韓憑一處棲。"]', '["风幌涼生白袷衣，星榆纔亂絳河低。","月明休近相思樹，恐有韓憑一处棲。"]', '诗', 'shi', '', NULL, '即夕 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8330209e-72b9-44b5-8518-a11eeaf322c4', '早春詠雪', '早春詠雪', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["句芒宮樹已先開，珠蘂瓊花鬬剪裁。","散作上林今夜雪，送教春色一時來。"]', '["句芒宮樹已先开，珠蘂瓊花鬬剪裁。","散作上林今夜雪，送教春色一时来。"]', '诗', 'shi', '', NULL, '早春詠雪 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d2a1ab-f256-4445-96b0-21638984ef5d', '望雪', '望雪', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["銀花珠樹曉來看，宿醉初醒一倍寒。","已似王恭披鶴氅，憑欄仍是玉欄干。"]', '["銀花珠樹晓来看，宿醉初醒一倍寒。","已似王恭披鹤氅，憑欄仍是玉欄干。"]', '诗', 'shi', '', NULL, '望雪 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83d38511-e21c-4835-8cb3-8e8284d89794', '雪霽', '雪霽', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["星榆葉葉晝離披，雲粉千重凝不飛。","崑玉樓臺珠樹密，夜來誰向月中歸。"]', '["星榆葉葉晝離披，云粉千重凝不飞。","崑玉楼台珠樹密，夜来誰向月中归。"]', '诗', 'shi', '', NULL, '雪霽 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09eaea92-39bf-4a3c-976c-4de09f3b4885', '舟次汴堤', '舟次汴堤', 'a1181710-4669-458e-806e-31b7d9432061', '唐', '["曲岸蘭叢雁飛起，野客維舟碧煙裏。","竿頭五兩轉天風，白日楊花滿流水。"]', '["曲岸蘭叢雁飞起，野客維舟碧煙裏。","竿头五兩轉天风，白日楊花满流水。"]', '诗', 'shi', '', NULL, '舟次汴堤 王初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95773780-e922-4deb-b323-38b8224acbca', '玉聲如樂', '玉声如乐', '1a5966ca-a24c-480f-8386-1afa004da16c', '唐', '["玉叩能旋止，人言與樂并。","繁音忽已闋，雅韻詘然清。","佩想停仙步，泉疑咽夜聲。","曲終無異聽，響極有餘情。","特達知難擬，玲瓏豈易名。","崑山如可得，一片佇爲榮。"]', '["玉叩能旋止，人言與乐并。","繁音忽已闋，雅韻詘然清。","佩想停仙步，泉疑咽夜声。","曲終無異听，响極有餘情。","特達知难擬，玲瓏豈易名。","崑山如可得，一片佇爲榮。"]', '诗', 'shi', '', NULL, '玉聲如樂 劉軻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ecc28c-64d3-44c2-8b91-535d4347a449', '喜陳懿老示新製', '喜陳懿老示新製', 'c0ca1083-05a3-4d30-ab2f-7c9cf7c37c86', '唐', '["一別一千日，一日十二憶。","苦心無閑時，今夕見玉色。","玉色復何異，弘明含羣德。","有文如星宿，飛入我胷臆。","憂愁方破壞，歡喜重補塞。","使我心貌全，且非黃金力。","將攀下風手，願假仙鸞翼。"]', '["一別一千日，一日十二憶。","苦心無闲时，今夕见玉色。","玉色复何異，弘明含羣德。","有文如星宿，飞入我胷臆。","憂愁方破壞，歡喜重補塞。","使我心貌全，且非黄金力。","將攀下风手，願假仙鸾翼。"]', '诗', 'shi', '', NULL, '喜陳懿老示新製 朱晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c9f704-045f-42dc-b2e2-a7239e33ca88', '贈友人古鏡', '贈友人古镜', 'c0ca1083-05a3-4d30-ab2f-7c9cf7c37c86', '唐', '["我有古時鏡，初自壞陵得。","蛟龍猶泥蟠，魑魅幸月蝕。","摩久見菱蘂，青於藍水色。","贈君將照色，無使心受惑。"]', '["我有古时镜，初自壞陵得。","蛟龙猶泥蟠，魑魅幸月蝕。","摩久见菱蘂，青於藍水色。","贈君將照色，無使心受惑。"]', '诗', 'shi', '', NULL, '贈友人古鏡 朱晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e9e760-8d24-440c-a26f-a2eb0dc65d20', '賦得花藤藥合寄頴陰故人', '賦得花藤藥合寄頴陰故人', 'c0ca1083-05a3-4d30-ab2f-7c9cf7c37c86', '唐', '["藤生南海濱，引蔓青且長。","剪削爲花枝，何人無文章。","非才亦有心，割骨聞餘芳。","繁葉落何處，孤貞在中央。","願盛黃金膏，寄與青眼郎。","路遠莫知意，水深天蒼蒼。"]', '["藤生南海濱，引蔓青且长。","剪削爲花枝，何人無文章。","非才亦有心，割骨闻餘芳。","繁葉落何处，孤貞在中央。","願盛黄金膏，寄與青眼郎。","路远莫知意，水深天蒼蒼。"]', '诗', 'shi', '', NULL, '賦得花藤藥合寄頴陰故人 朱晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b86cd9-d293-4da5-baef-f1810ed648ae', '春色滿皇州', '春色满皇州', 'c6d49214-8563-47f3-9ec3-24699c780fdf', '唐', '["藹藹復悠悠，春歸十二樓。","最明雲裏闕，先滿日邊州。","色媚青門外，光搖紫陌頭。","上林榮舊樹，太液鏡新流。","曖帶祥煙起，清添瑞景浮。","陽和如啓蟄，從此事芳遊。"]', '["藹藹复悠悠，春归十二楼。","最明云裏闕，先满日邊州。","色媚青门外，光搖紫陌头。","上林榮旧樹，太液镜新流。","曖带祥煙起，清添瑞景浮。","陽和如啓蟄，從此事芳游。"]', '诗', 'shi', '', NULL, '春色滿皇州 滕邁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fffdf240-fa11-4a36-beef-62862800ce61', '楊柳枝詞', '楊柳枝词', 'c6d49214-8563-47f3-9ec3-24699c780fdf', '唐', '["三條陌上拂金羈，萬里橋邊映酒旗。","此日令人腸欲斷，不堪將入笛中吹。"]', '["三條陌上拂金羈，万里橋邊映酒旗。","此日令人腸欲斷，不堪將入笛中吹。"]', '诗', 'shi', '', NULL, '楊柳枝詞 滕邁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a384cb-9b95-437d-8217-a2531e7c5bf9', '句', '句', 'c6d49214-8563-47f3-9ec3-24699c780fdf', '唐', '["陶令門前罥接䍦，亞夫營裏拂朱旗。"]', '["陶令门前罥接䍦，亞夫營裏拂朱旗。"]', '诗', 'shi', '', NULL, '句 滕邁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebedd92e-2f68-4dfe-92ac-03a4c62c0ca0', '留別吉州太守宗人邁', '留別吉州太守宗人邁', '74ec0f85-5580-4ec3-a008-602655cee7d5', '唐', '["秋初江上別旌旗，故國無家淚欲垂。","千里未知投足處，前程便是聽猨時。","誤攻文字身空老，却返漁樵計已遲。","羽翼彫零飛不得，丹霄無路接差池。"]', '["秋初江上別旌旗，故国無家泪欲垂。","千里未知投足处，前程便是听猨时。","誤攻文字身空老，却返漁樵計已遲。","羽翼彫零飞不得，丹霄無路接差池。"]', '诗', 'shi', '', NULL, '留別吉州太守宗人邁 滕倪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca0ac5d-647e-4a5e-bd02-680516875798', '句', '句', '74ec0f85-5580-4ec3-a008-602655cee7d5', '唐', '["映水有深意，見人無懼心。","白髮不能容相國，也同閑客滿頭生。"]', '["映水有深意，见人無懼心。","白髮不能容相国，也同闲客满头生。"]', '诗', 'shi', '', NULL, '句 滕倪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f62f201-87ad-4d1a-ab1d-a20974e65f18', '吳宮', '吳宮', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["吳王愛歌舞，夜夜醉嬋娟。","見日吹紅燭，和塵掃翠鈿。","徒令句踐霸，不信子胥賢。","莫問長洲草，荒涼無限年。"]', '["吳王愛歌舞，夜夜醉嬋娟。","见日吹紅燭，和塵掃翠鈿。","徒令句踐霸，不信子胥賢。","莫问长洲草，荒涼無限年。"]', '诗', 'shi', '', NULL, '吳宮 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93d49dd-43a0-4426-9f3a-9915864386e9', '久雨', '久雨', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["雲影蔽遙空，無端淡復濃。","兩旬綿密雨，二月似深冬。","詩酒從教數，簾幃一任重。","孰知春有地，微露小桃紅。"]', '["云影蔽遙空，無端淡复濃。","兩旬綿密雨，二月似深冬。","诗酒從教數，簾幃一任重。","孰知春有地，微露小桃紅。"]', '诗', 'shi', '', NULL, '久雨 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3addb04-8aaf-4348-b1f1-8e872077800d', '郊行逢社日', '郊行逢社日', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["酒熟送迎便，村村慶有年。","妻孥親稼穡，老稚効漁畋。","紅樹青林外，黃蘆白鳥邊。","稔看風景美，寧不羨歸田。"]', '["酒熟送迎便，村村慶有年。","妻孥親稼穡，老稚効漁畋。","紅樹青林外，黄蘆白鸟邊。","稔看风景美，寧不羨归田。"]', '诗', 'shi', '', NULL, '郊行逢社日 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c59b75c-f151-4ab7-8c36-076983223349', '過友人幽居', '過友人幽居', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["身坐衆香國，蒲團詩思新。","一貧曾累我，此興未輸人。","陋巷誰爲俗，寒窗不染塵。","石齋盟四友，年下頓生春。"]', '["身坐衆香国，蒲團诗思新。","一貧曾累我，此兴未輸人。","陋巷誰爲俗，寒窗不染塵。","石斋盟四友，年下頓生春。"]', '诗', 'shi', '', NULL, '過友人幽居 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c31bcc0c-7dad-4572-b0b5-090256079374', '過雍陶博士邸中飲', '過雍陶博士邸中饮', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["落葉下蕭蕭，幽居遠市朝。","偶成投轄飲，不待致書招。","塞鴈衝寒過，山雲傍檻飄。","此身何所似，天地一漁樵。"]', '["落葉下蕭蕭，幽居远市朝。","偶成投轄饮，不待致书招。","塞鴈衝寒過，山云傍檻飄。","此身何所似，天地一漁樵。"]', '诗', 'shi', '', NULL, '過雍陶博士邸中飲 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a281f900-74c5-452f-869c-75364decc82f', '遊王羽士山房', '游王羽士山房', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["落日半樓明，琳宮事事清。","山橫萬古色，鶴帶九臯聲。","易作神仙侶，難忘父子情。","道人應識我，未肯說長生。"]', '["落日半楼明，琳宮事事清。","山橫万古色，鹤带九臯声。","易作神仙侶，难忘父子情。","道人應識我，未肯说长生。"]', '诗', 'shi', '', NULL, '遊王羽士山房 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e396fc1-435a-4a68-a2d7-a1f0b0aa3359', '署中答武功姚合', '署中答武功姚合', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["原中多陰雨，惟留一室明。","自宜居靜者，誰得問先生。","深井泉香出，危沙藥更榮。","全家笑無辱，曾不見戈兵。"]', '["原中多陰雨，惟留一室明。","自宜居静者，誰得问先生。","深井泉香出，危沙藥更榮。","全家笑無辱，曾不见戈兵。"]', '诗', 'shi', '', NULL, '署中答武功姚合 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2568b21b-c081-4f1d-b93c-c715a0225114', '贈龍陽尉馬戴', '贈龙陽尉马戴', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["早學全身術，惟令耕近田。","自輸官稅後，常臥晚雲邊。","細草沿堦長，高蘿出石懸。","向來名姓茂，空被外情牽。"]', '["早学全身術，惟令耕近田。","自輸官稅後，常臥晚云邊。","細草沿堦长，高蘿出石懸。","向来名姓茂，空被外情牽。"]', '诗', 'shi', '', NULL, '贈龍陽尉馬戴 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b7b087-7e6d-423e-9e2c-34c9d71825a4', '上巳日贈都上人 一', '上巳日贈都上人 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["三月初三日，千家與萬家。","蝶飛秦地草，鶯入漢宮花。","鞍馬皆爭麗，笙歌盡鬬奢。","吾師無所願，惟願老煙霞。"]', '["三月初三日，千家與万家。","蝶飞秦地草，鶯入漢宮花。","鞍马皆爭丽，笙歌尽鬬奢。","吾師無所願，惟願老煙霞。"]', '诗', 'shi', '', NULL, '上巳日贈都上人 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e5a6f6-2c67-4977-9eba-b255737e68ba', '上巳日贈都上人 二', '上巳日贈都上人 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["曲水公卿宴，香塵盡滿街。","無心修禊事，獨步到禪齋。","細草縈愁目，繁花逆旅懷。","綺羅人走馬，遺落鳳皇釵。"]', '["曲水公卿宴，香塵尽满街。","無心修禊事，独步到禪斋。","細草縈愁目，繁花逆旅懷。","綺羅人走马，遺落鳳皇釵。"]', '诗', 'shi', '', NULL, '上巳日贈都上人 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e31364-11d7-422a-b2a3-d0142a85608a', '送沈亞之尉南康', '送沈亞之尉南康', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["行邁南康路，客心離怨多。","暮煙葵葉屋，秋月竹枝歌。","孤鶴唳殘夢，驚猨嘯薜蘿。","對江翹首望，愁淚疊如波。"]', '["行邁南康路，客心離怨多。","暮煙葵葉屋，秋月竹枝歌。","孤鹤唳殘梦，驚猨嘯薜蘿。","对江翹首望，愁泪叠如波。"]', '诗', 'shi', '', NULL, '送沈亞之尉南康 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e6da3d-9bd2-4d7e-89b8-2c775c3837b1', '奉送劉使君王屋山隱居', '奉送劉使君王屋山隐居', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["散髮風簷下，沈沈日漸曛。","鷹拳擒野雀，蛛網獵飛蚊。","羣動能歸計，吾生亦謾勤。","塵緣難著眼，晚興寄青雲。"]', '["散髮风簷下，沈沈日漸曛。","鷹拳擒野雀，蛛網獵飞蚊。","羣动能归計，吾生亦謾勤。","塵緣难著眼，晚兴寄青云。"]', '诗', 'shi', '', NULL, '奉送劉使君王屋山隱居 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249acc9f-3402-4fd5-a184-5c8de6bc2e6d', '寄許渾秀才', '寄許渾秀才', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["文字飢難煮，爲農策最良。","興來鉏曉月，倦後臥斜陽。","秋稼連千頃，春花醉幾場。","任他名利客，車馬鬧康莊。"]', '["文字飢难煮，爲農策最良。","兴来鉏晓月，倦後臥斜陽。","秋稼連千頃，春花醉幾場。","任他名利客，车马鬧康莊。"]', '诗', 'shi', '', NULL, '寄許渾秀才 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eddfe9a7-6e8f-4184-b074-0fbbac6d2a23', '送客遊吳', '送客游吳', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["吳國水中央，波濤白渺茫。","衣逢梅雨漬，船入稻花香。","海戍通鹽竈，山村帶蜜房。","欲知蘇小小，君試到錢塘。"]', '["吳国水中央，波濤白渺茫。","衣逢梅雨漬，船入稻花香。","海戍通鹽竈，山村带蜜房。","欲知蘇小小，君試到錢塘。"]', '诗', 'shi', '', NULL, '送客遊吳 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa0163f-9a64-46c0-8177-ad3aa1e328f7', '陸丞相故宅', '陸丞相故宅', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["衣冠零落久，今日事堪傷。","廚起青烟薄，門開白日長。","殘梅欹古道，名石臥頹牆。","山色依然好，興衰未可量。"]', '["衣冠零落久，今日事堪傷。","廚起青烟薄，门开白日长。","殘梅欹古道，名石臥頹牆。","山色依然好，兴衰未可量。"]', '诗', 'shi', '', NULL, '陸丞相故宅 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fb4393-c9cf-4599-b0ca-3ef1f61eb9e5', '中元日觀諸道士步虛', '中元日观諸道士步虛', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["玄都開秘籙，白石禮先生。","上界秋光淨，中元夜氣清。","星辰朝帝處，鸞鶴步虛聲。","玉洞花長發，珠宮月最明。","掃壇天地肅，投簡鬼神驚。","儻賜刀圭藥，還留不死名。"]', '["玄都开秘籙，白石禮先生。","上界秋光淨，中元夜氣清。","星辰朝帝处，鸾鹤步虛声。","玉洞花长發，珠宮月最明。","掃壇天地肅，投簡鬼神驚。","儻賜刀圭藥，還留不死名。"]', '诗', 'shi', '', NULL, '中元日觀諸道士步虛 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5667b8-5454-42eb-a593-24ec36a52c44', '醉贈劉十二', '醉贈劉十二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["春草正淒淒，知君過惡溪。","鶯將吉了語，猿共猓然啼。","別路魂先斷，還家夢幾迷。","定尋雷令劒，應識越王笄。","樹色多於北，潮聲少向西。","椰花好爲酒，誰伴醉如泥。"]', '["春草正淒淒，知君過惡溪。","鶯將吉了語，猿共猓然啼。","別路魂先斷，還家梦幾迷。","定尋雷令劒，應識越王笄。","樹色多於北，潮声少向西。","椰花好爲酒，誰伴醉如泥。"]', '诗', 'shi', '', NULL, '醉贈劉十二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29eef040-1804-4265-9c38-5248be13fd83', '早朝', '早朝', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["曙鍾催入紫宸朝，列炬流虹映絳綃。","天近鰲頭花簇杖，風低豹尾樂鳴韶。","衣冠一變無夷俗，律令重頒有正條。","昨日鍾山甘露降，玻璃滿賜出宮瓢。"]', '["曙鍾催入紫宸朝，列炬流虹映絳綃。","天近鰲头花簇杖，风低豹尾乐鳴韶。","衣冠一变無夷俗，律令重頒有正條。","昨日鍾山甘露降，玻璃满賜出宮瓢。"]', '诗', 'shi', '', NULL, '早朝 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a81c2c8f-25ce-4ae1-b2d1-cb3530865370', '帝京二首 一', '帝京二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["列郡徵才起俊髦，萬機獨使聖躬勞。","開藩上相頒龍節，破虜將軍展豹韜。","地入黃圖三輔壯，天垂華蓋七星高。","迎春別賜瑤池宴，捧進金盤五色桃。"]', '["列郡徵才起俊髦，万機独使聖躬勞。","开藩上相頒龙節，破虜將軍展豹韜。","地入黄圖三輔壯，天垂华蓋七星高。","迎春別賜瑤池宴，捧進金盤五色桃。"]', '诗', 'shi', '', NULL, '帝京二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ffab61-1c67-43ed-b2b6-5928ce04d052', '帝京二首 二', '帝京二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["龍虎山河御氣通，遙瞻帝闕五雲紅。","英雄盡入江東籍，將相多收薊北功。","禮樂日稽三代盛，梯航歲貢萬方同。","都將儉德熙文治，淳俗應還太古風。"]', '["龙虎山河御氣通，遙瞻帝闕五云紅。","英雄尽入江东籍，將相多收薊北功。","禮乐日稽三代盛，梯航歲貢万方同。","都將儉德熙文治，淳俗應還太古风。"]', '诗', 'shi', '', NULL, '帝京二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9825c19-aa51-4fbf-93f0-3d940f13e2de', '宮詞', '宮词', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["悄悄深宮不見人，倚闌惟見石麒麟。","芙蓉帳冷愁長夜，翡翠簾垂隔小春。","天遠難通青鳥信，風寒欲動錦花茵。","夜深怕有羊車過，自起籠燈看雪紋。"]', '["悄悄深宮不见人，倚闌惟见石麒麟。","芙蓉帳冷愁长夜，翡翠簾垂隔小春。","天远难通青鸟信，风寒欲动錦花茵。","夜深怕有羊车過，自起籠灯看雪紋。"]', '诗', 'shi', '', NULL, '宮詞 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('224283cd-4894-4b68-ac4f-9011f1dfa59c', '郊居作', '郊居作', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["碧樹濃陰護短垣，蒼江春煖渚鳧喧。","買魚試喚鳴榔艇，尋鶴因行隔壠村。","生理何憑文是業，世情縱遣酒盈樽。","相逢謂我迂疎甚，欲辨還憎恐失言。"]', '["碧樹濃陰護短垣，蒼江春煖渚鳧喧。","買鱼試喚鳴榔艇，尋鹤因行隔壠村。","生理何憑文是業，世情縱遣酒盈樽。","相逢謂我迂疎甚，欲辨還憎恐失言。"]', '诗', 'shi', '', NULL, '郊居作 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d475d066-270f-4466-aef1-ed6c8cf346fc', '閑居', '闲居', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["茂苑閑居木石同，旋開小逕翦蒿蓬。","虛遊心在鴻蒙外，穴處身疑培塿中。","花影一闌吟夜月，松聲半榻臥秋風。","百年寄傲聊容膝，何必高車駟馬通。"]', '["茂苑闲居木石同，旋开小逕翦蒿蓬。","虛游心在鴻蒙外，穴处身疑培塿中。","花影一闌吟夜月，松声半榻臥秋风。","百年寄傲聊容膝，何必高车駟马通。"]', '诗', 'shi', '', NULL, '閑居 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80971174-d3d6-44ac-879c-7aaab5058a8a', '暮春述懷', '暮春述懷', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["爲客山南二十年，愁來怳近落花天。","陰雲帶雨連山脊，濕氣成嵐滴樹巔。","隣屋有聲敲石火，野禽無語避茶煙。","此時若遇孫陽顧，肯服鹽車不受鞭。"]', '["爲客山南二十年，愁来怳近落花天。","陰云带雨連山脊，濕氣成嵐滴樹巔。","隣屋有声敲石火，野禽無語避茶煙。","此时若遇孫陽顧，肯服鹽车不受鞭。"]', '诗', 'shi', '', NULL, '暮春述懷 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508e5a40-2ce9-41af-9bf5-7c58830b0fae', '端午日', '端午日', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["少年佳節倍多情，老去誰知感慨生。","不効艾符趨習俗，但祈蒲酒話昇平。","鬢絲日日添頭白，榴錦年年照眼明。","千載賢愚同瞬息，幾人湮沒幾垂名。"]', '["少年佳節倍多情，老去誰知感慨生。","不効艾符趨習俗，但祈蒲酒話昇平。","鬢絲日日添头白，榴錦年年照眼明。","千載賢愚同瞬息，幾人湮沒幾垂名。"]', '诗', 'shi', '', NULL, '端午日 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd14cb55-cb21-4ae0-99b0-763b408906c0', '九日', '九日', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["萬里飄零十二秋，不堪今倚夕陽樓。","壯懷空擲班超筆，久客誰憐季子裘。","瘴雨蠻煙朝暮景，平蕪野草古今愁。","酣歌欲盡登高興，強把黃花插滿頭。"]', '["万里飄零十二秋，不堪今倚夕陽楼。","壯懷空擲班超笔，久客誰怜季子裘。","瘴雨蠻煙朝暮景，平蕪野草古今愁。","酣歌欲尽登高兴，強把黄花插满头。"]', '诗', 'shi', '', NULL, '九日 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9443bc15-f9d4-44c7-908c-86bc2fe051d6', '九日病起', '九日病起', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["重陽開滿菊花金，病起榰牀惜賞心。","紫蟹霜肥秋縱好，綠醅蟻滑晚慵斟。","眼窺薄霧行殊倦，身怯寒風坐未禁。","沈醉又成來歲約，遣懷聊作記時吟。"]', '["重陽开满菊花金，病起榰牀惜賞心。","紫蟹霜肥秋縱好，綠醅蟻滑晚慵斟。","眼窺薄霧行殊倦，身怯寒风坐未禁。","沈醉又成来歲約，遣懷聊作記时吟。"]', '诗', 'shi', '', NULL, '九日病起 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08de206-97dd-42ef-8bd6-c81a3e6496e0', '寒夜', '寒夜', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["雲冷江空歲暮時，竹陰梅影月參差。","雞催夢枕司晨早，更咽寒城報點遲。","人事紛華潛動息，天心靜默運推移。","憑誰蕩滌窮殘候，入眼東風喜在期。"]', '["云冷江空歲暮时，竹陰梅影月參差。","雞催梦枕司晨早，更咽寒城報点遲。","人事紛华潛动息，天心静默運推移。","憑誰蕩滌窮殘候，入眼东风喜在期。"]', '诗', 'shi', '', NULL, '寒夜 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('973d40f8-bd19-485b-b579-b994216de74a', '喜雨', '喜雨', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["臨岐終日自裴回，乾我茅齋半畝苔。","山上亂雲隨手變，淛東飛雨過江來。","一元和氣歸中正，百怪蒼淵起蟄雷。","千里稻花應秀色，酒樽風月醉亭臺。"]', '["臨岐終日自裴回，乾我茅斋半畝苔。","山上亂云隨手变，淛东飞雨過江来。","一元和氣归中正，百怪蒼淵起蟄雷。","千里稻花應秀色，酒樽风月醉亭台。"]', '诗', 'shi', '', NULL, '喜雨 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c874ec-1437-4b41-891b-055e4b17d08d', '春遊', '春游', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["明日城東看杏花，叮嚀童子蚤將車。","路從丹鳳樓前過，酒向金魚館裏賒。","綠水滿溝生杜若，暖雲將雨濕泥沙。","絕勝羊傅襄陽道，車騎西風擁鼓笳。"]', '["明日城东看杏花，叮嚀童子蚤將车。","路從丹鳳楼前過，酒向金鱼館裏賒。","綠水满溝生杜若，暖云將雨濕泥沙。","絕勝羊傅襄陽道，车騎西风擁鼓笳。"]', '诗', 'shi', '', NULL, '春遊 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bfcf79-65ed-4366-929a-17dadd48a13c', '夜酌溪樓', '夜酌溪楼', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["樓居溪上涼生早，坐對城頭起暮笳。","打鼓泊船何處客，搗衣隔竹是誰家。","玉繩低轉宵初迥，銀燭高燒月近斜。","得意引杯須痛飲，好懷那許負年華。"]', '["楼居溪上涼生早，坐对城头起暮笳。","打鼓泊船何处客，捣衣隔竹是誰家。","玉繩低轉宵初迥，銀燭高燒月近斜。","得意引杯須痛饮，好懷那許負年华。"]', '诗', 'shi', '', NULL, '夜酌溪樓 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f8b9123-32a0-4680-af8c-5e951b48c1b2', '旅行', '旅行', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["煙樹寒林半有無，野人行李更蕭疎。","堠長堠短逢官馬，山北山南聞鷓鴣。","萬里關河成傳舍，五更風雨憶呼盧。","寂寥一點寒燈在，酒熟隣家許夜沽。"]', '["煙樹寒林半有無，野人行李更蕭疎。","堠长堠短逢官马，山北山南闻鷓鴣。","万里关河成傳舍，五更风雨憶呼盧。","寂寥一点寒灯在，酒熟隣家許夜沽。"]', '诗', 'shi', '', NULL, '旅行 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc26018-2064-4d31-a8d3-24cf504cdf2a', '下第東歸作', '下第东归作', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["十載驅馳倦荷鋤，三年生計鬢蕭疎。","辛勤幾逐英雄後，乙榜猶然姓氏虛。","欲射狼星把弓箭，休將螢火讀詩書。","身賤自慙貧骨相，朗嘯東歸學釣魚。"]', '["十載驱驰倦荷鋤，三年生計鬢蕭疎。","辛勤幾逐英雄後，乙榜猶然姓氏虛。","欲射狼星把弓箭，休將螢火读诗书。","身賤自慙貧骨相，朗嘯东归学釣鱼。"]', '诗', 'shi', '', NULL, '下第東歸作 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6362ff5-193b-47ff-8c28-2fe2f3bb4748', '還京口', '還京口', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["黃鶴山頭雪未消，行人歸計在今朝。","城高鐵甕江山壯，地接金陵草木彫。","北府市樓聞舊酒，南橋官柳識歸橈。","吏民莫見參軍面，水宿風餐鬢髮焦。"]', '["黄鹤山头雪未消，行人归計在今朝。","城高鐵甕江山壯，地接金陵草木彫。","北府市楼闻旧酒，南橋官柳識归橈。","吏民莫见參軍面，水宿风餐鬢髮焦。"]', '诗', 'shi', '', NULL, '還京口 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8312baaf-e786-428b-87a9-abf170987597', '襄口阻風', '襄口阻风', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["雪浪排空接海門，孤舟三日阻龍津。","曹瞞曾墮周郎計，王導難遮庚亮塵。","鷗散白雲沈遠浦，花飛紅雨送殘春。","篙師整纜候明發，仍謁荒祠問鬼神。"]', '["雪浪排空接海门，孤舟三日阻龙津。","曹瞞曾墮周郎計，王導难遮庚亮塵。","鷗散白云沈远浦，花飞紅雨送殘春。","篙師整纜候明發，仍謁荒祠问鬼神。"]', '诗', 'shi', '', NULL, '襄口阻風 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f838f56-3248-4e2f-9cc1-2500f9917744', '潭州獨步', '潭州独步', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["鶴髮垂肩懶著巾，晚涼獨步楚江濱。","一帆暝色鷗邊雨，數尺筇枝物外身。","習巧未逢醫拙手，聞歌先識採蓮人。","笑看斥鷃飛翔去，樂處蓬萊便有春。"]', '["鹤髮垂肩懶著巾，晚涼独步楚江濱。","一帆暝色鷗邊雨，數尺筇枝物外身。","習巧未逢醫拙手，闻歌先識採蓮人。","笑看斥鷃飞翔去，乐处蓬萊便有春。"]', '诗', 'shi', '', NULL, '潭州獨步 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86837d23-eab6-4655-85d4-2eef4e834377', '金陵懷古', '金陵懷古', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["黃道天清擁珮珂，東南王氣秣陵多。","江吞彭蠡來三蜀，地接崑崙帶九河。","鳳闕曉霞紅散綺，龍池春水綠生波。","華夷混一歸真主，端拱無爲樂太和。"]', '["黄道天清擁珮珂，东南王氣秣陵多。","江吞彭蠡来三蜀，地接崑崙带九河。","鳳闕晓霞紅散綺，龙池春水綠生波。","华夷混一归真主，端拱無爲乐太和。"]', '诗', 'shi', '', NULL, '金陵懷古 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8bc5926-51e9-4ce6-8a27-eb11747359e7', '登鳳凰臺二首 一', '登鳳凰台二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["鳳凰臺上望長安，五色宮袍照水寒。","綵筆十年留翰墨，銀河一夜臥闌干。","三山飛鳥江天暮，六代離宮草樹殘。","始信人生如一夢，壯懷莫使酒杯乾。"]', '["鳳凰台上望长安，五色宮袍照水寒。","綵笔十年留翰墨，銀河一夜臥闌干。","三山飞鸟江天暮，六代離宮草樹殘。","始信人生如一梦，壯懷莫使酒杯乾。"]', '诗', 'shi', '', NULL, '登鳳凰臺二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471b6247-847c-4875-988a-2f4848374c88', '登鳳凰臺二首 二', '登鳳凰台二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["梧桐葉落秋風老，人去臺空鳳不來。","梁武臺成芳草合，吳王宮殿野花開。","石頭城下春生水，燕子堂前雨長苔。","莫問人間興廢事，百年相遇且銜杯。"]', '["梧桐葉落秋风老，人去台空鳳不来。","梁武台成芳草合，吳王宮殿野花开。","石头城下春生水，燕子堂前雨长苔。","莫问人间兴廢事，百年相遇且銜杯。"]', '诗', 'shi', '', NULL, '登鳳凰臺二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de9f8c26-1560-4366-9272-914b47f7d0f8', '韓信廟', '韓信廟', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["長空鳥盡將軍死，無復中原入馬蹄。","身向九泉還屬漢，功超諸將合封齊。","荒涼古廟惟松柏，咫尺長陵又鹿麋。","此日深憐蕭相國，竟無一語到金閨。"]', '["长空鸟尽將軍死，無复中原入马蹄。","身向九泉還屬漢，功超諸將合封齊。","荒涼古廟惟松柏，咫尺长陵又鹿麋。","此日深怜蕭相国，竟無一語到金閨。"]', '诗', 'shi', '', NULL, '韓信廟 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f5d5d9-4318-46dd-8db5-dd46c302ca72', '訪許渾', '訪許渾', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["去郭來尋隱者居，柳陰假步小籃輿。","每期會面初償約，却計論心舊得書。","淺綠垣牆綿薜荔，淡紅池沼映芙蕖。","爲言肯共留連飲，澗有青芹罟有魚。"]', '["去郭来尋隐者居，柳陰假步小籃輿。","每期會面初償約，却計論心旧得书。","淺綠垣牆綿薜荔，淡紅池沼映芙蕖。","爲言肯共留連饮，澗有青芹罟有鱼。"]', '诗', 'shi', '', NULL, '訪許渾 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33fc062-a8c2-4b8b-b5f0-477bfdc3beb6', '李舍人席上感遇', '李舍人席上感遇', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["微雲歛雨天氣清，松聲出樹秋泠泠。","窗戶長含碧蘿色，溪流時帶蛟龍腥。","一官到手不可避，萬事役我徒勞形。","飄然曳杖出門去，無數好山江上橫。"]', '["微云歛雨天氣清，松声出樹秋泠泠。","窗戶长含碧蘿色，溪流时带蛟龙腥。","一官到手不可避，万事役我徒勞形。","飄然曳杖出门去，無數好山江上橫。"]', '诗', 'shi', '', NULL, '李舍人席上感遇 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256c5592-148e-490a-8fe7-f60b89a7b9c4', '和趙相公登鸛雀樓', '和趙相公登鸛雀楼', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["危樓高架泬寥天，上相閑登立綵旃。","樹色到京三百里，河流歸漢幾千年。","晴峰聳日當周道，秋穀垂花滿舜田。","雲路何人見高志，最看西面赤闌前。"]', '["危楼高架泬寥天，上相闲登立綵旃。","樹色到京三百里，河流归漢幾千年。","晴峰聳日當周道，秋穀垂花满舜田。","云路何人见高志，最看西面赤闌前。"]', '诗', 'shi', '', NULL, '和趙相公登鸛雀樓 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87415ae6-c00a-4e83-a8a6-10962c744c36', '冬至酬劉使君', '冬至酬劉使君', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["異鄉冬至又今朝，回首家山入夢遙。","漸喜一陽從地復，却憐羣沴逐冰消。","梅含露蘂知迎臘，柳拂宮袍憶候朝。","多少故人承宴賞，五雲堆裏聽簫韶。"]', '["異乡冬至又今朝，回首家山入梦遙。","漸喜一陽從地复，却怜羣沴逐冰消。","梅含露蘂知迎臘，柳拂宮袍憶候朝。","多少故人承宴賞，五云堆裏听簫韶。"]', '诗', 'shi', '', NULL, '冬至酬劉使君 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e05996a-1b8c-4927-9b04-cc0c55a3b28e', '李節度平虜詩', '李節度平虜诗', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["百萬王師下日邊，將軍雄略可圖全。","元勳未論封茅異，捷勢應知破竹然。","燕警無烽清朔漠，秦文有寶進藍田。","太平從此銷兵甲，記取紅羊換劫年。"]', '["百万王師下日邊，將軍雄略可圖全。","元勳未論封茅異，捷勢應知破竹然。","燕警無烽清朔漠，秦文有寶進藍田。","太平從此銷兵甲，記取紅羊換劫年。"]', '诗', 'shi', '', NULL, '李節度平虜詩 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32518b87-8559-473b-b0b9-734549503863', '金陵上李公垂侍郎', '金陵上李公垂侍郎', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["海國微茫散曉暾，鬱葱佳氣滿乾坤。","六朝空據長江險，一統今歸聖代尊。","西北諸峰連朔漠，東南衆水合崑崙。","願從吾道禧文運，再使河清俗化淳。"]', '["海国微茫散晓暾，鬱葱佳氣满乾坤。","六朝空據长江險，一統今归聖代尊。","西北諸峰連朔漠，东南衆水合崑崙。","願從吾道禧文運，再使河清俗化淳。"]', '诗', 'shi', '', NULL, '金陵上李公垂侍郎 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebb080f5-34bb-42fa-b766-1151e5ab367c', '贈惟儼師', '贈惟儼師', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["煥然文采照青春，一策江湖自在身。","雲鎖木龕聊息影，雪香紙襖不生塵。","談禪早續燈無盡，護法重編論有神。","擬掃綠陰浮佛寺，桫欏高樹結爲隣。"]', '["煥然文采照青春，一策江湖自在身。","云鎖木龕聊息影，雪香紙襖不生塵。","談禪早續灯無尽，護法重編論有神。","擬掃綠陰浮佛寺，桫欏高樹結爲隣。"]', '诗', 'shi', '', NULL, '贈惟儼師 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('239e2af4-d0c2-4a39-b0c8-3c327ad7f30f', '寄許渾秀才', '寄許渾秀才', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["萬木驚秋葉漸稀，靜探造化見玄機。","眼前誰悟先天理，去後還知今日非。","樹擁秣陵千嶂合，雲開蕭寺一僧歸。","漢廷累下徵賢詔，未許嚴陵老釣磯。"]', '["万木驚秋葉漸稀，静探造化见玄機。","眼前誰悟先天理，去後還知今日非。","樹擁秣陵千嶂合，云开蕭寺一僧归。","漢廷累下徵賢詔，未許嚴陵老釣磯。"]', '诗', 'shi', '', NULL, '寄許渾秀才 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ceb01c-86b9-47dc-a51f-912013abd5c3', '送白舍人渡江', '送白舍人渡江', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["曉發龍江第一程，諸公同濟似登瀛。","海門日上千峰出，桃葉波平一棹輕。","橫鎖已沈王濬筏，投鞭難阻謝玄兵。","片時喜得東風便，回首鐘聲隔鳳城。"]', '["晓發龙江第一程，諸公同濟似登瀛。","海门日上千峰出，桃葉波平一棹轻。","橫鎖已沈王濬筏，投鞭难阻謝玄兵。","片时喜得东风便，回首鐘声隔鳳城。"]', '诗', 'shi', '', NULL, '送白舍人渡江 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3781db86-9a0f-4243-806a-63bfbd4bc927', '送劉禹錫侍御出刺連州', '送劉禹錫侍御出刺連州', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["遐荒迢遰五羊城，歸興濃消客裏情。","家近似忘山路險，土甘殊覺瘴煙輕。","梅花清入羅浮夢，荔子紅分廣海程。","此去定知償隱趣，石田春雨讀書耕。"]', '["遐荒迢遰五羊城，归兴濃消客裏情。","家近似忘山路險，土甘殊覺瘴煙轻。","梅花清入羅浮梦，荔子紅分廣海程。","此去定知償隐趣，石田春雨读书耕。"]', '诗', 'shi', '', NULL, '送劉禹錫侍御出刺連州 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab25ce2-70a6-4ea4-b1a6-fb9ecfd56419', '送韋侍御報使西蕃', '送韋侍御報使西蕃', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["歸奏聖朝行萬里，却銜天詔報蕃臣。","本是諸生守文墨，今將匹馬靜煙塵。","旅宿關河逢暮雨，春耕亭障識遺民。","此去多應收故地，寧辭沙塞往來頻。"]', '["归奏聖朝行万里，却銜天詔報蕃臣。","本是諸生守文墨，今將匹马静煙塵。","旅宿关河逢暮雨，春耕亭障識遺民。","此去多應收故地，寧辞沙塞往来頻。"]', '诗', 'shi', '', NULL, '送韋侍御報使西蕃 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c215a9b-bcc9-47d8-9442-c5178ddc2158', '寒食城南即事因訪藍田韋明府', '寒食城南即事因訪藍田韋明府', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["閑出城南禁火天，路傍騎馬獨搖鞭。","青松古墓傷碑碣，紅杏春園羨管弦。","徒說鸊鵜膏玉劒，漫誇蚨血點銅錢。","世間盡是悠悠事，且飲韋家冷酒眠。"]', '["闲出城南禁火天，路傍騎马独搖鞭。","青松古墓傷碑碣，紅杏春园羨管弦。","徒说鸊鵜膏玉劒，漫誇蚨血点銅錢。","世间尽是悠悠事，且饮韋家冷酒眠。"]', '诗', 'shi', '', NULL, '寒食城南即事因訪藍田韋明府 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3875233a-01b7-4468-a0d9-3df625ed03eb', '送源中丞使新羅', '送源中丞使新羅', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["赤墀奉命使殊方，官重霜臺紫綬光。","玉節在船清海怪，金函開詔撫夷王。","雲晴漸覺山川異，風便寧知道路長。","誰得似君將雨露，海東萬里灑扶桑。"]', '["赤墀奉命使殊方，官重霜台紫綬光。","玉節在船清海怪，金函开詔撫夷王。","云晴漸覺山川異，风便寧知道路长。","誰得似君將雨露，海东万里灑扶桑。"]', '诗', 'shi', '', NULL, '送源中丞使新羅 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e41cea-639f-4c69-b858-41e5b6063ceb', '送景玄上人還山', '送景玄上人還山', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["嵩陽聽罷講經鐘，遠訪庭闈錫度空。","蒲履謾從歸後織，衲衣猶記別時縫。","地橫龍朔連沙暝，山入烏桓碧樹重。","梵宇傳來金貝葉，花前拜捧慰親容。"]', '["嵩陽听罷講經鐘，远訪庭闈錫度空。","蒲履謾從归後织，衲衣猶記別时縫。","地橫龙朔連沙暝，山入烏桓碧樹重。","梵宇傳来金貝葉，花前拜捧慰親容。"]', '诗', 'shi', '', NULL, '送景玄上人還山 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e3186c9-6cbc-45c1-a558-767973706727', '宮人入道', '宮人入道', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["卸却宮妝錦繡衣，黃冠素服製相宜。","錫名近奉君王旨，佩籙新參老氏師。","白晝無情趨玉陛，清宵有夢步瑤池。","綠鬟女伴含愁別，釋盡當年妬寵私。"]', '["卸却宮妝錦繡衣，黄冠素服製相宜。","錫名近奉君王旨，佩籙新參老氏師。","白晝無情趨玉陛，清宵有梦步瑤池。","綠鬟女伴含愁別，釋尽當年妬寵私。"]', '诗', 'shi', '', NULL, '宮人入道 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f86f129-519b-46fd-a95f-b9f1f29c352d', '友人山中梅花', '友人山中梅花', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["南國看花動遠情，沈郎詩苦瘦容生。","鐵心自儗山中賦，玉笛誰將月下橫。","臨水一枝春占早，照人千樹雪同清。","好風吹醒羅浮夢，莫聽空林翠羽聲。"]', '["南国看花动远情，沈郎诗苦瘦容生。","鐵心自儗山中賦，玉笛誰將月下橫。","臨水一枝春占早，照人千樹雪同清。","好风吹醒羅浮梦，莫听空林翠羽声。"]', '诗', 'shi', '', NULL, '友人山中梅花 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('775398c8-b809-40aa-af2f-93746dbc82ca', '客中有感', '客中有感', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["天地一身在，頭顱五十過。","流年消壯志，空使淚成河。"]', '["天地一身在，头顱五十過。","流年消壯志，空使泪成河。"]', '诗', 'shi', '', NULL, '客中有感 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0454b343-4523-408c-8506-63cde404cd84', '憶家二首 一', '憶家二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["新霽颺林初，蘋花貼岸舒。","故鄉今夜月，猶得照孤廬。"]', '["新霽颺林初，蘋花貼岸舒。","故乡今夜月，猶得照孤廬。"]', '诗', 'shi', '', NULL, '憶家二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c052c1e-110f-4411-91c0-4330065c29ff', '憶家二首 二', '憶家二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["樹擁溪邊閣，山浮雨後嵐。","白頭歸未得，夢裏望江南。"]', '["樹擁溪邊閣，山浮雨後嵐。","白头归未得，梦裏望江南。"]', '诗', 'shi', '', NULL, '憶家二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a689898-1c77-46ae-b059-bc4ca2963ec1', '江行二首 一', '江行二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["暝色滄州迥，秋聲玉峽長。","只因江上月，不覺過潯陽。"]', '["暝色滄州迥，秋声玉峽长。","只因江上月，不覺過潯陽。"]', '诗', 'shi', '', NULL, '江行二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('381f5d55-87b3-41c8-9ce1-a9b3f745d50a', '江行二首 二', '江行二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["晚泊長江口，寒沙白似霜。","年光流不盡，東去水聲長。"]', '["晚泊长江口，寒沙白似霜。","年光流不尽，东去水声长。"]', '诗', 'shi', '', NULL, '江行二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c525574a-b5a7-478f-af9b-4c1869a81dd5', '偶題', '偶題', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["越女收龍眼，蠻兒拾象牙。","長安千萬里，走馬送誰家。"]', '["越女收龙眼，蠻兒拾象牙。","长安千万里，走马送誰家。"]', '诗', 'shi', '', NULL, '偶題 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('002f4e51-2332-4f16-a5c9-31bad79b8f16', '關中傷亂後', '关中傷亂後', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["去歲干戈險，今年蝗旱憂。","關西歸戰馬，海內賣耕牛。"]', '["去歲干戈險，今年蝗旱憂。","关西归戰马，海內賣耕牛。"]', '诗', 'shi', '', NULL, '關中傷亂後 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80596e47-dd8a-4e79-b9c0-cafb5e26a857', '楚江懷古', '楚江懷古', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["騷靈不可見，楚些竟誰聞。","欲采蘋花去，滄州隔暮雲。"]', '["騷靈不可见，楚些竟誰闻。","欲采蘋花去，滄州隔暮云。"]', '诗', 'shi', '', NULL, '楚江懷古 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd4650e-1f41-413e-8611-027882561915', '張飛廟', '張飞廟', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["威名垂萬古，勇力冠當時。","回首三分國，何人賦黍離。"]', '["威名垂万古，勇力冠當时。","回首三分国，何人賦黍離。"]', '诗', 'shi', '', NULL, '張飛廟 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4c4d35-c226-42e3-960e-581851f93f53', '生公講臺', '生公講台', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["暝色護樓臺，陰雲晝未開。","一塵無處著，花雨遍蒼苔。"]', '["暝色護楼台，陰云晝未开。","一塵無处著，花雨遍蒼苔。"]', '诗', 'shi', '', NULL, '生公講臺 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb247193-1b85-41c1-8acd-1385d918b8a5', '席上聽琴', '席上听琴', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["高堂流月明，萬籟不到耳。","一聽清心魂，飛絮春紛起。"]', '["高堂流月明，万籟不到耳。","一听清心魂，飞絮春紛起。"]', '诗', 'shi', '', NULL, '席上聽琴 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fad6962-b685-4393-87bb-b3abec93f17f', '酬雍秀才二首 一', '酬雍秀才二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["晚市人煙合，歸帆帶夕陽。","棲遲未歸客，猶著錦衣裳。"]', '["晚市人煙合，归帆带夕陽。","棲遲未归客，猶著錦衣裳。"]', '诗', 'shi', '', NULL, '酬雍秀才二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac427db-6703-4f85-b134-b306273c6a50', '酬雍秀才二首 二', '酬雍秀才二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["臥病茅窗下，驚聞兩月過。","興來聊賦詠，清婉逼陰何。"]', '["臥病茅窗下，驚闻兩月過。","兴来聊賦詠，清婉逼陰何。"]', '诗', 'shi', '', NULL, '酬雍秀才二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d740990-b897-4b98-b836-800bb0831c42', '竹', '竹', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["窗戶盡蕭森，空堦凝碧陰。","不緣冰雪裏，爲識歲寒心。"]', '["窗戶尽蕭森，空堦凝碧陰。","不緣冰雪裏，爲識歲寒心。"]', '诗', 'shi', '', NULL, '竹 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dacd468-9b4c-4962-8581-9ffc1c03e009', '春怨', '春怨', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["柳花撲簾春欲盡，綠陰障林鶯亂啼。","秖愁明日送春去，落日滿園啼竹雞。"]', '["柳花撲簾春欲尽，綠陰障林鶯亂啼。","秖愁明日送春去，落日满园啼竹雞。"]', '诗', 'shi', '', NULL, '春怨 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01561bdb-edd8-42be-9c9c-e9cc215c4419', '館娃宮', '館娃宮', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["宮女三千去不回，真珠翠羽是塵埃。","夫差舊國久破碎，紅燕自歸花自開。"]', '["宮女三千去不回，真珠翠羽是塵埃。","夫差旧国久破碎，紅燕自归花自开。"]', '诗', 'shi', '', NULL, '館娃宮 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c60eea-df9b-4e43-ad73-efd9995488fc', '漢宮詞三首 一', '漢宮词三首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["成帝夫人淚滿懷，璧宮相趁落空堦。","可憐玉貌花前死，惟有君恩白燕釵。"]', '["成帝夫人泪满懷，璧宮相趁落空堦。","可怜玉貌花前死，惟有君恩白燕釵。"]', '诗', 'shi', '', NULL, '漢宮詞三首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3381f3b8-d80d-4a5a-80c4-46cddb27b1dd', '漢宮詞三首 二', '漢宮词三首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["霍家有女字成君，年少教人著繡裙。","枉殺宮中許皇后，椒房恩澤是浮雲。"]', '["霍家有女字成君，年少教人著繡裙。","枉殺宮中許皇后，椒房恩澤是浮云。"]', '诗', 'shi', '', NULL, '漢宮詞三首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb16db8-4174-4bee-8fd6-edd40ac8b14d', '漢宮詞三首 三', '漢宮词三首 三', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["駿馬金鞍白玉鞭，宮中來取李延年。","承恩直日鴛鴦殿，一曲清歌在九天。"]', '["駿马金鞍白玉鞭，宮中来取李延年。","承恩直日鴛鴦殿，一曲清歌在九天。"]', '诗', 'shi', '', NULL, '漢宮詞三首 三 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8071036-9e39-49c2-b3e9-09fdeb4a5f82', '同州端午', '同州端午', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["鶴髮垂肩尺許長，離家三十五端陽。","兒童見說深驚訝，却問何方是故鄉。"]', '["鹤髮垂肩尺許长，離家三十五端陽。","兒童见说深驚訝，却问何方是故乡。"]', '诗', 'shi', '', NULL, '同州端午 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a511791-268e-4e61-975c-6fbd0018a8da', '夜過洞庭', '夜過洞庭', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["笙歌只解鬧花天，誰是敲冰掉小船。","爲覓瀟湘幽隱處，夜深載月聽鳴泉。"]', '["笙歌只解鬧花天，誰是敲冰掉小船。","爲覓瀟湘幽隐处，夜深載月听鳴泉。"]', '诗', 'shi', '', NULL, '夜過洞庭 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ddfd5c3-0a0f-4d2f-b92d-413946b29a6e', '遊山南寺二首 一', '游山南寺二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["山中盡日無人到，竹外交加百鳥鳴。","昨日小樓微雨過，櫻桃花落晚風晴。"]', '["山中尽日無人到，竹外交加百鸟鳴。","昨日小楼微雨過，櫻桃花落晚风晴。"]', '诗', 'shi', '', NULL, '遊山南寺二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2f6b41-9470-41a3-8a03-ca77b668bc49', '遊山南寺二首 二', '游山南寺二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["踏碎羊山黃葉堆，天飛細雨隱輕雷。","朗陵莫訝來何晚，不忍聽君話別杯。"]', '["踏碎羊山黄葉堆，天飞細雨隐轻雷。","朗陵莫訝来何晚，不忍听君話別杯。"]', '诗', 'shi', '', NULL, '遊山南寺二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df22a14d-cb97-4ce9-a855-630f5d40587e', '寄太僕田卿二首 一', '寄太僕田卿二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["客窗強飲太怱怱，急雨寒風意萬重。","驀上心來消未得，夢回又聽五更鐘。"]', '["客窗強饮太怱怱，急雨寒风意万重。","驀上心来消未得，梦回又听五更鐘。"]', '诗', 'shi', '', NULL, '寄太僕田卿二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b764f6-a1f0-46d5-95ef-5324058f3ea0', '寄太僕田卿二首 二', '寄太僕田卿二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["一陽纔動伏羣陰，萬物於今寓太音。","若喜長生添線日，微微消息識天心。"]', '["一陽纔动伏羣陰，万物於今寓太音。","若喜长生添線日，微微消息識天心。"]', '诗', 'shi', '', NULL, '寄太僕田卿二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab287f91-8d9a-4355-8b08-513aa7b8a224', '新昌井', '新昌井', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["轆轤千轉勞筋力，待得甘泉渴殺人。","且共山麋同飲澗，玉沙鋪底淺磷磷。"]', '["轆轤千轉勞筋力，待得甘泉渴殺人。","且共山麋同饮澗，玉沙鋪底淺磷磷。"]', '诗', 'shi', '', NULL, '新昌井 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e59b6cc-23aa-42d8-9810-b1f74e1846c9', '經靖安里', '經靖安里', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["巷底蕭蕭絕市塵，供愁疎雨打黃昏。","悠然一曲泉明調，淺立閑愁輕閉門。"]', '["巷底蕭蕭絕市塵，供愁疎雨打黄昏。","悠然一曲泉明調，淺立闲愁轻閉门。"]', '诗', 'shi', '', NULL, '經靖安里 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6f5f80-7fcd-4488-b72d-37569e593656', '聞箏歌', '闻箏歌', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["淒淒切切斷腸聲，指滑音柔萬種情。","花影深沈遮不住，度幃穿幕又殘更。"]', '["淒淒切切斷腸声，指滑音柔万種情。","花影深沈遮不住，度幃穿幕又殘更。"]', '诗', 'shi', '', NULL, '聞箏歌 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2a94d9-f6a0-42c2-b6c7-62c04121ab64', '吹笙歌', '吹笙歌', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["伶兒竹聲愁繞空，秦女淚濕燕支紅。","玉桃花片落不住，三十六簧能喚風。"]', '["伶兒竹声愁繞空，秦女泪濕燕支紅。","玉桃花片落不住，三十六簧能喚风。"]', '诗', 'shi', '', NULL, '吹笙歌 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee121fc-5a0a-4690-9d6c-f6386c58d982', '贈歌人郭婉二首 一', '贈歌人郭婉二首 一', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["石家金谷舊歌人，起唱花筵淚滿巾。","紅粉少年諸弟子，一時惆悵望梁塵。"]', '["石家金谷旧歌人，起唱花筵泪满巾。","紅粉少年諸弟子，一时惆悵望梁塵。"]', '诗', 'shi', '', NULL, '贈歌人郭婉二首 一 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0ac822-812d-4ea3-9eb7-b0c1021ff1a3', '贈歌人郭婉二首 二', '贈歌人郭婉二首 二', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["雲滿衣裳月滿身，輕盈歸步過流塵。","五更無限留連意，常恐風花又一春。"]', '["云满衣裳月满身，轻盈归步過流塵。","五更無限留連意，常恐风花又一春。"]', '诗', 'shi', '', NULL, '贈歌人郭婉二首 二 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eead6632-0c59-47e5-b39a-47673ee0324a', '潭州席上贈舞柘枝妓', '潭州席上贈舞柘枝妓', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["姑蘇太守青娥女，流落長沙舞柘枝。","坐滿繡衣皆不識，可憐紅臉淚雙垂。"]', '["姑蘇太守青娥女，流落长沙舞柘枝。","坐满繡衣皆不識，可怜紅臉泪雙垂。"]', '诗', 'shi', '', NULL, '潭州席上贈舞柘枝妓 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3078d4c-c0da-4965-8905-ca0669c558ce', '句', '句', 'eb3cca39-3612-47f2-a640-cf6e592f0a82', '唐', '["瘴雨出虹蝀，蠻煙渡江急。","嘗聞島夷俗，犀象滿城邑。"]', '["瘴雨出虹蝀，蠻煙渡江急。","嘗闻島夷俗，犀象满城邑。"]', '诗', 'shi', '', NULL, '句 殷堯藩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a2014c-1579-4128-a861-1e9e1e71b22d', '虎丘山真娘墓', '虎丘山真娘墓', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["金釵淪劒壑，茲地似花臺。","油壁何人值，錢塘度曲哀。","翠餘長染柳，香重欲薰梅。","但道行雲去，應隨魂夢來。"]', '["金釵淪劒壑，茲地似花台。","油壁何人值，錢塘度曲哀。","翠餘长染柳，香重欲薰梅。","但道行云去，應隨魂梦来。"]', '诗', 'shi', '', NULL, '虎丘山真娘墓 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e325f400-746a-4c84-9654-14b1bb2c290d', '荅殷堯藩贈罷涇源記室', '荅殷堯藩贈罷涇源記室', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["勞君輟雅話，聽說事疆場。","提筆從征虜，飛書始伏羌。","河流辭馬嶺，節臥聽龍驤。","孤負平生劒，空憐射斗光。"]', '["勞君輟雅話，听说事疆場。","提笔從征虜，飞书始伏羌。","河流辞马嶺，節臥听龙驤。","孤負平生劒，空怜射斗光。"]', '诗', 'shi', '', NULL, '荅殷堯藩贈罷涇源記室 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db4b846a-707e-4763-85f7-44a3381003f2', '五月六日發石頭城步望前船示舍弟兼寄侯郎', '五月六日發石头城步望前船示舍弟兼寄侯郎', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["客子去淮陽，逶迤別夢長。","水關開夜鎖，霧櫂起晨涼。","煙月期同賞，風波勿異行。","隱山曾撼櫓，轉瀨指遙檣。","蒲葉吳刀綠，筠筒楚粽香。","因書報惠遠，爲我憶檀郎。"]', '["客子去淮陽，逶迤別梦长。","水关开夜鎖，霧櫂起晨涼。","煙月期同賞，风波勿異行。","隐山曾撼櫓，轉瀨指遙檣。","蒲葉吳刀綠，筠筒楚粽香。","因书報惠远，爲我憶檀郎。"]', '诗', 'shi', '', NULL, '五月六日發石頭城步望前船示舍弟兼寄侯郎 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde43d6e-40e5-4cd0-93a5-950a9ca07500', '別龐子肅', '別龐子肅', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["自爲應仙才，丹砂鍊幾迴。","山秋夢桂樹，月曉憶瑤臺。","雨雪依巖避，煙雲逐步開。","今朝龍杖去，早晚鶴書來。"]', '["自爲應仙才，丹砂鍊幾迴。","山秋梦桂樹，月晓憶瑤台。","雨雪依巖避，煙云逐步开。","今朝龙杖去，早晚鹤书来。"]', '诗', 'shi', '', NULL, '別龐子肅 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfaf01bf-3c20-4c9a-94ca-574eeaac03c2', '春色滿皇州', '春色满皇州', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["何處春輝好，偏宜在雍州。","花明夾城道，柳暗曲江頭。","風軟遊絲重，光融瑞氣浮。","鬬雞憐短草，乳燕傍高樓。","繡轂盈香陌，新泉溢御溝。","迴看日欲暮，還騎似川流。"]', '["何处春輝好，偏宜在雍州。","花明夾城道，柳暗曲江头。","风軟游絲重，光融瑞氣浮。","鬬雞怜短草，乳燕傍高楼。","繡轂盈香陌，新泉溢御溝。","迴看日欲暮，還騎似川流。"]', '诗', 'shi', '', NULL, '春色滿皇州 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('650d0c88-6efb-437f-ae8a-1760ce4e0f4e', '宿白馬津寄寇立', '宿白马津寄寇立', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["客思聽蛩嗟，秋懷似亂砂。","劒頭懸日影，蠅鼻落燈花。","天外歸鴻斷，漳南別路賒。","聞君同旅舍，幾得夢還家。"]', '["客思听蛩嗟，秋懷似亂砂。","劒头懸日影，蠅鼻落灯花。","天外归鴻斷，漳南別路賒。","闻君同旅舍，幾得梦還家。"]', '诗', 'shi', '', NULL, '宿白馬津寄寇立 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ca18f0-dded-445e-9f54-31fe745c75e3', '汴州船行賦岸傍所見', '汴州船行賦岸傍所见', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["古木曉蒼蒼，秋林拂岸香。","露珠蟲網細，金縷兔絲長。","秋浪時迴沫，驚鱗乍觸航。","蓬煙拈綠線，棘實綴紅囊。","亂穗搖鼯尾，出根挂鳳腸。","聊持一濯足，誰道比滄浪。"]', '["古木晓蒼蒼，秋林拂岸香。","露珠蟲網細，金縷兔絲长。","秋浪时迴沫，驚鱗乍觸航。","蓬煙拈綠線，棘實綴紅囊。","亂穗搖鼯尾，出根挂鳳腸。","聊持一濯足，誰道比滄浪。"]', '诗', 'shi', '', NULL, '汴州船行賦岸傍所見 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49d072a1-20bb-4f77-9899-55d219490663', '送文頴上人遊天台', '送文頴上人游天台', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["露花浮翠瓦，鮮思起芳叢。","此際斷客夢，況復別志公。","既歷天台去，言過赤城東。","莫說人間事，崎嶇塵土中。"]', '["露花浮翠瓦，鲜思起芳叢。","此際斷客梦，況复別志公。","既歷天台去，言過赤城东。","莫说人间事，崎嶇塵土中。"]', '诗', 'shi', '', NULL, '送文頴上人遊天台 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9216bb62-c647-414c-bf80-eee0eea40f30', '宿後自華陽行次昭應寄王直方', '宿後自华陽行次昭應寄王直方', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["重歸能幾日，物意早如春。","暖色先驪岫，寒聲別鴈羣。","川光如戲劒，帆態似翔雲。","爲報東園蝶，南枝日已曛。"]', '["重归能幾日，物意早如春。","暖色先驪岫，寒声別鴈羣。","川光如戲劒，帆態似翔云。","爲報东园蝶，南枝日已曛。"]', '诗', 'shi', '', NULL, '宿後自華陽行次昭應寄王直方 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd21ad3c-e08e-4569-9978-078b6e38a4e4', '題海榴樹呈八叔大人', '題海榴樹呈八叔大人', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["曾在蓬壺伴衆仙，文章枝葉五雲邊。","幾時奉宴瑤臺下，何日移榮玉砌前。","染日裁霞深雨露，凌寒送暖占風煙。","應笑強如河畔柳，逢波逐浪送張騫。"]', '["曾在蓬壺伴衆仙，文章枝葉五云邊。","幾时奉宴瑤台下，何日移榮玉砌前。","染日裁霞深雨露，凌寒送暖占风煙。","應笑強如河畔柳，逢波逐浪送張騫。"]', '诗', 'shi', '', NULL, '題海榴樹呈八叔大人 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdabc46-057b-4cd1-9af9-748ffa6901e3', '西蕃請謁廟', '西蕃請謁廟', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["肅肅層城裏，巍巍祖廟清。","聖恩覃布濩，異域獻精誠。","冠蓋分行列，戎夷辨姓名。","禮終齊百拜，心潔表忠貞。","瑞氣千重色，簫韶九奏聲。","杖移迎日轉，旌動逐風輕。","休運威儀正，年推俎豆盈。","不才慙聖澤，空此望華纓。"]', '["肅肅層城裏，巍巍祖廟清。","聖恩覃布濩，異域獻精誠。","冠蓋分行列，戎夷辨姓名。","禮終齊百拜，心潔表忠貞。","瑞氣千重色，簫韶九奏声。","杖移迎日轉，旌动逐风轻。","休運威儀正，年推俎豆盈。","不才慙聖澤，空此望华纓。"]', '诗', 'shi', '', NULL, '西蕃請謁廟 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0a653f-3704-4ce0-a33f-1848559fe425', '勸政樓下觀百官獻壽', '勸政楼下观百官獻壽', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["御氣黃花節，臨軒紫陌頭。","早陽生彩杖，霽色入仙樓。","獻壽皆鴛鷺，瞻天在冕旒。","菊尊開九日，鳳曆啓千秋。","樂闋祥煙起，杯酣瑞影收。","年年歌舞夕，此地慶皇休。"]', '["御氣黄花節，臨軒紫陌头。","早陽生彩杖，霽色入仙楼。","獻壽皆鴛鷺，瞻天在冕旒。","菊尊开九日，鳳曆啓千秋。","乐闋祥煙起，杯酣瑞影收。","年年歌舞夕，此地慶皇休。"]', '诗', 'shi', '', NULL, '勸政樓下觀百官獻壽 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87aac1f6-ef12-4e11-a777-2119b06112bb', '山出雲', '山出云', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["片雲朝出岫，孤色逈難親。","蓋小辭山早，根輕觸石新。","飄揚經綠野，明麗照青春。","拂樹疑舒葉，臨江似結鱗。","從龍方有感，捧日豈無因。","看助爲霖去，恩沾雨露均。"]', '["片云朝出岫，孤色逈难親。","蓋小辞山早，根轻觸石新。","飄揚經綠野，明丽照青春。","拂樹疑舒葉，臨江似結鱗。","從龙方有感，捧日豈無因。","看助爲霖去，恩沾雨露均。"]', '诗', 'shi', '', NULL, '山出雲 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('780b5267-9b33-47e2-8953-d4a07a4eac9d', '曲江亭望慈恩杏花發', '曲江亭望慈恩杏花發', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["曲臺晴好望，近接梵王家。","十畝開金地，千株發杏花。","帶雲猶誤雪，映日欲欺霞。","紫陌傳香遠，紅泉落影斜。","園中春尚早，亭上路非賒。","芳景偏堪賞，其如積歲華。"]', '["曲台晴好望，近接梵王家。","十畝开金地，千株發杏花。","带云猶誤雪，映日欲欺霞。","紫陌傳香远，紅泉落影斜。","园中春尚早，亭上路非賒。","芳景偏堪賞，其如積歲华。"]', '诗', 'shi', '', NULL, '曲江亭望慈恩杏花發 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63fe1ca-1982-47e2-881a-c9c5fb68ecfa', '村居', '村居', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["有樹巢宿鳥，無酒共客醉。","月上蟬韻殘，梧桐陰繞地。","獨出村舍門，吟劇微風起。","蕭蕭蘆荻叢，呌嘯如山鬼。","應緣我憔悴，爲我哭秋思。"]', '["有樹巢宿鸟，無酒共客醉。","月上蟬韻殘，梧桐陰繞地。","独出村舍门，吟劇微风起。","蕭蕭蘆荻叢，呌嘯如山鬼。","應緣我憔悴，爲我哭秋思。"]', '诗', 'shi', '', NULL, '村居 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32795c3d-dbfe-4b37-9a5d-327883b3eac7', '春詞酬元微之', '春词酬元微之', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["黃鶯啼時春日高，紅芳發盡井邊桃。","美人手暖裁衣易，片片輕花落翦刀。"]', '["黄鶯啼时春日高，紅芳發尽井邊桃。","美人手暖裁衣易，片片轻花落翦刀。"]', '诗', 'shi', '', NULL, '春詞酬元微之 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516f9d8c-997b-403c-9281-092858b4c05e', '題侯仙亭', '題侯仙亭', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["新創仙亭覆石壇，雕梁峻宇入雲端。","嶺北嘯猨高枕聽，湖南山色捲簾看。"]', '["新創仙亭覆石壇，雕梁峻宇入云端。","嶺北嘯猨高枕听，湖南山色捲簾看。"]', '诗', 'shi', '', NULL, '題侯仙亭 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0224c269-eaff-42a2-8789-4152a70430ab', '送龐子肅', '送龐子肅', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["三年遊宦也迷津，馬困長安九陌塵。","都作無成不歸去，古來妻嫂笑蘇秦。"]', '["三年游宦也迷津，马困长安九陌塵。","都作無成不归去，古来妻嫂笑蘇秦。"]', '诗', 'shi', '', NULL, '送龐子肅 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c21860-e614-4699-9549-69b46e8acb1d', '夢輓秦弄玉', '梦輓秦弄玉', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["泣葬一枝紅，生同死不同。","金鈿墜芳草，香繡滿春風。","舊日聞簫處，高樓當月中。","梨花寒食夜，深閉翠微宮。"]', '["泣葬一枝紅，生同死不同。","金鈿墜芳草，香繡满春风。","旧日闻簫处，高楼當月中。","梨花寒食夜，深閉翠微宮。"]', '诗', 'shi', '', NULL, '夢輓秦弄玉 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8dafcdd-c993-4203-8a5d-77e4941774a0', '夢別秦穆公', '梦別秦穆公', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["擊髆舞，恨滿煙光無處所。","淚如雨，欲擬著辭不成語。","金鳳銜紅舊繡衣，幾度宮中同看舞。","人間春日正歡樂，日暮東風何處去。"]', '["擊髆舞，恨满煙光無处所。","泪如雨，欲擬著辞不成語。","金鳳銜紅旧繡衣，幾度宮中同看舞。","人间春日正歡乐，日暮东风何处去。"]', '诗', 'shi', '', NULL, '夢別秦穆公 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb4b17bd-bee6-4503-989e-4a96f8c6260e', '夢游秦宮', '梦游秦宮', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["君王多感放東歸，從此秦宮不復期。","春景似傷秦喪主，落花如雨淚臙脂。"]', '["君王多感放东归，從此秦宮不复期。","春景似傷秦喪主，落花如雨泪臙脂。"]', '诗', 'shi', '', NULL, '夢游秦宮 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf57231-7c6d-4b4d-a256-a6cf28ce176e', '湘中怨 一', '湘中怨 一', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["隆佳秀兮昭盛時，播薰綠兮淑華歸。","顧室荑與處蕚兮，潛重房以飾姿。","見稚態之韶羞兮，蒙長靄以爲幃。","醉融光兮渺渺瀰瀰，迷千里兮涵煙眉。","晨陶陶兮暮熙熙，舞婑那之穠條兮。","騁盈盈以披遲，酡遊顏兮倡蔓卉縠，流蒨霓兮石髮髓旎。"]', '["隆佳秀兮昭盛时，播薰綠兮淑华归。","顧室荑與处蕚兮，潛重房以飾姿。","见稚態之韶羞兮，蒙长靄以爲幃。","醉融光兮渺渺瀰瀰，迷千里兮涵煙眉。","晨陶陶兮暮熙熙，舞婑那之穠條兮。","騁盈盈以披遲，酡游顏兮倡蔓卉縠，流蒨霓兮石髮髓旎。"]', '诗', 'shi', '', NULL, '湘中怨 一 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c413c74-6169-407f-b440-0854cd6890c5', '湘中怨 二', '湘中怨 二', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["泝青山兮江之隅，拖湘波兮褭綠裾。","荷拳拳兮未舒，匪同歸兮將焉[如]。"]', '["泝青山兮江之隅，拖湘波兮褭綠裾。","荷拳拳兮未舒，匪同归兮將焉[如]。"]', '诗', 'shi', '', NULL, '湘中怨 二 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd2b95f-739c-4e2b-85f7-df48c2512abb', '文祝延二闋 一', '文祝延二闋 一', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["閩山之杭杭兮水堋堋，吞荒抱大兮香疊層。","騰氣清渾兮朝昏，神生其中兮宅幽凝。","居如山兮惠如水，處端卓兮赴下而忘鄙。","集人之祈兮從人之所市，攀清明兮叩髣髴。","我民清兮期吉日，願聽誠兮陳所當。","侯臨我兮恩如光，照導兮天覆。","惠流吾兮樂且康，恭聞侯兮飲食失常。","民縈憂兮心苦瘡，飽我之飢兮侯由有穀。","神有澤兮宜蔭沃，脫侯之恙兮歸侯之多福。","羣卑勤之恭潔兮，鑒貞盟乎山竹。"]', '["閩山之杭杭兮水堋堋，吞荒抱大兮香叠層。","腾氣清渾兮朝昏，神生其中兮宅幽凝。","居如山兮惠如水，处端卓兮赴下而忘鄙。","集人之祈兮從人之所市，攀清明兮叩髣髴。","我民清兮期吉日，願听誠兮陳所當。","侯臨我兮恩如光，照導兮天覆。","惠流吾兮乐且康，恭闻侯兮饮食失常。","民縈憂兮心苦瘡，飽我之飢兮侯由有穀。","神有澤兮宜蔭沃，脫侯之恙兮归侯之多福。","羣卑勤之恭潔兮，鑒貞盟乎山竹。"]', '诗', 'shi', '', NULL, '文祝延二闋 一 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c898cc5-2525-44f3-85e5-e020c8a8d1d1', '文祝延二闋 二', '文祝延二闋 二', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["兕載吹兮音咿咿，銅鐃呶兮睋呼𪾤睢。","樟之蓋兮麓下，雲垂幄兮爲帷。","合吾民兮將安，維吾侯之康兮樂欣。","肴盤列兮荅神，神擺漁篁兮降拂窣窣。","右持妓兮左夫人，態修邃兮佻眇。","調丹含瓊兮瑳佳笑，馨炮羶燔兮溢按豆。","爵盎無虛兮菓摭雜佑，秋雲清醉兮流融光。","巫裾旋兮覡袖翔，瞪虛凝兮覽迴楊。","語神歡兮酒云央，望吾侯兮遵賞事。","朝馬駕兮搦寶轡，千弭函弦兮森道騎。","吾何樂兮神軒，維侯之康兮居遊自遂。"]', '["兕載吹兮音咿咿，銅鐃呶兮睋呼𪾤睢。","樟之蓋兮麓下，云垂幄兮爲帷。","合吾民兮將安，維吾侯之康兮乐欣。","肴盤列兮荅神，神擺漁篁兮降拂窣窣。","右持妓兮左夫人，態修邃兮佻眇。","調丹含瓊兮瑳佳笑，馨炮羶燔兮溢按豆。","爵盎無虛兮菓摭杂佑，秋云清醉兮流融光。","巫裾旋兮覡袖翔，瞪虛凝兮覽迴楊。","語神歡兮酒云央，望吾侯兮遵賞事。","朝马駕兮搦寶轡，千弭函弦兮森道騎。","吾何乐兮神軒，維侯之康兮居游自遂。"]', '诗', 'shi', '', NULL, '文祝延二闋 二 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d460d8-1940-4341-b6d1-940c237ced93', '及第後過楊子江', '及第後過楊子江', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["憶昔將貢年，抱愁此江邊。","魚龍互閃爍，黑浪高於天。","今日步春草，復來經此道。","江神也世情，爲我風色好。"]', '["憶昔將貢年，抱愁此江邊。","鱼龙互閃爍，黑浪高於天。","今日步春草，复来經此道。","江神也世情，爲我风色好。"]', '诗', 'shi', '', NULL, '及第後過楊子江 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03d691a1-9b4f-47c7-aa64-a077286be739', '夜宴曲', '夜宴曲', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["蘭缸如晝曉不眠，玉堂夜起沈香煙。","青娥一行十二仙，欲笑不笑桃花然。","碧窗弄嬌梳洗晚，戶外不知銀漢轉。","被郎嗔罰琉璃盞，酒入四肢紅玉軟。"]', '["蘭缸如晝晓不眠，玉堂夜起沈香煙。","青娥一行十二仙，欲笑不笑桃花然。","碧窗弄嬌梳洗晚，戶外不知銀漢轉。","被郎嗔罰琉璃盞，酒入四肢紅玉軟。"]', '诗', 'shi', '', NULL, '夜宴曲 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa873d9a-0890-47da-a8a6-b6da4f0dbb77', '効古興', '効古兴', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["金雀無舊釵，緗綺無舊裾。","唯有一寸心，長貯萬里夫。","南軒夜蟲織已促，北牖飛蛾遶殘燭。","祗言衆口鑠千金，誰信獨愁銷片玉。","不知歲晚歸不歸，又將啼眼縫征衣。"]', '["金雀無旧釵，緗綺無旧裾。","唯有一寸心，长貯万里夫。","南軒夜蟲织已促，北牖飞蛾遶殘燭。","祗言衆口鑠千金，誰信独愁銷片玉。","不知歲晚归不归，又將啼眼縫征衣。"]', '诗', 'shi', '', NULL, '効古興 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b73dfc-f141-4899-b752-46d1dde2536a', '古別離二首 一', '古別離二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["古人謾歌西飛燕，十年不見狂夫面。","三更風作切夢刀，萬轉愁成繫腸線。","所嗟不及牛女星，一年一度得相見。"]', '["古人謾歌西飞燕，十年不见狂夫面。","三更风作切梦刀，万轉愁成繫腸線。","所嗟不及牛女星，一年一度得相见。"]', '诗', 'shi', '', NULL, '古別離二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f9c5fb-c4fe-4af6-9023-bca86df5119f', '古別離二首 二', '古別離二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["老母別愛子，少妻送征郎。","血流既四面，乃一斷二腸。","不愁寒無衣，不怕飢無糧。","惟恐征戰不還鄉，母化爲鬼妻爲孀。"]', '["老母別愛子，少妻送征郎。","血流既四面，乃一斷二腸。","不愁寒無衣，不怕飢無糧。","惟恐征戰不還乡，母化爲鬼妻爲孀。"]', '诗', 'shi', '', NULL, '古別離二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25c9d1df-051a-4878-9f6f-e77151950e68', '壯士行', '壯士行', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["一斗之膽撐臟腑，如磥之筋礙臂骨。","有時悞入千人叢，自覺一身橫突兀。","當今四海無煙塵，胸襟被壓不得伸。","凍梟殘蠆我不取，汚我匣裏青蛇鱗。"]', '["一斗之膽撐臟腑，如磥之筋礙臂骨。","有时悞入千人叢，自覺一身橫突兀。","當今四海無煙塵，胸襟被壓不得伸。","凍梟殘蠆我不取，汚我匣裏青蛇鱗。"]', '诗', 'shi', '', NULL, '壯士行 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb65e630-133d-478a-9ce0-c1cd1656d5b9', '代征婦怨', '代征婦怨', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["寒窗羞見影相隨，嫁得五陵輕薄兒。","長短豔歌君自解，淺深更漏妾偏知。","畫裙多淚鴛鴦濕，雲鬢慵梳玳瑁垂。","何事不看霜雪裏，堅貞惟有古松枝。"]', '["寒窗羞见影相隨，嫁得五陵轻薄兒。","长短豔歌君自解，淺深更漏妾偏知。","畫裙多泪鴛鴦濕，云鬢慵梳玳瑁垂。","何事不看霜雪裏，堅貞惟有古松枝。"]', '诗', 'shi', '', NULL, '代征婦怨 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fd45cc-d54e-4eb4-8b5d-1a43c306bcf0', '送人南游', '送人南游', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["見說南行偏不易，中途莫忘寄書頻。","凌空瘴氣墮飛鳥，解語山魈惱病人。","閩縣綠娥能引客，泉州烏藥好防身。","異花奇竹分明看，待汝歸來畫取真。"]', '["见说南行偏不易，中途莫忘寄书頻。","凌空瘴氣墮飞鸟，解語山魈惱病人。","閩縣綠娥能引客，泉州烏藥好防身。","異花奇竹分明看，待汝归来畫取真。"]', '诗', 'shi', '', NULL, '送人南游 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cda90ee-803a-48a2-adf8-4b826ff2f4c8', '贈邊將', '贈邊將', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["輕生奉國不爲難，戰苦身多舊箭瘢。","玉匣鎖龍鱗甲冷，金鈴襯鶻羽毛寒。","皂貂擁出花當背，白馬騎來月在鞍。","猶恐犬戎臨虜塞，柳營時把陣圖看。"]', '["轻生奉国不爲难，戰苦身多旧箭瘢。","玉匣鎖龙鱗甲冷，金鈴襯鶻羽毛寒。","皂貂擁出花當背，白马騎来月在鞍。","猶恐犬戎臨虜塞，柳營时把陣圖看。"]', '诗', 'shi', '', NULL, '贈邊將 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a3fdd9-6088-46cc-a9b2-d226237da33b', '上禮部侍郎陳情', '上禮部侍郎陳情', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["九重城裏無親識，八百人中獨姓施。","弱羽飛時攢箭險，蹇驢行處薄冰危。","晴天欲照盆難反，貧女如花鏡不知。","却向從來受恩地，再求青律變寒枝。"]', '["九重城裏無親識，八百人中独姓施。","弱羽飞时攢箭險，蹇驢行处薄冰危。","晴天欲照盆难反，貧女如花镜不知。","却向從来受恩地，再求青律变寒枝。"]', '诗', 'shi', '', NULL, '上禮部侍郎陳情 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a18ef835-add7-499e-948a-25d274acfc09', '早春殘雪', '早春殘雪', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["春景照林巒，玲瓏雪影殘。","井泉添碧甃，藥圃洗朱欄。","雲路迷初醒，書堂映漸難。","花分梅嶺色，塵減玉堦寒。","遠稱棲松鶴，高宜點露盤。","佇逢春律後，陰谷始堪看。"]', '["春景照林巒，玲瓏雪影殘。","井泉添碧甃，藥圃洗朱欄。","云路迷初醒，书堂映漸难。","花分梅嶺色，塵減玉堦寒。","远稱棲松鹤，高宜点露盤。","佇逢春律後，陰谷始堪看。"]', '诗', 'shi', '', NULL, '早春殘雪 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b7ea783-df07-4491-a048-cb315598a41e', '送端上人遊天台', '送端上人游天台', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["師今欲向天台去，來說天台意最真。","溪過石橋爲險處，路逢毛褐是真人。","雲邊望字鐘聲遠，雪裏尋僧脚跡新。","只可且論經夏別，莫教琪樹兩迴春。"]', '["師今欲向天台去，来说天台意最真。","溪過石橋爲險处，路逢毛褐是真人。","云邊望字鐘声远，雪裏尋僧脚跡新。","只可且論經夏別，莫教琪樹兩迴春。"]', '诗', 'shi', '', NULL, '送端上人遊天台 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf6a4672-d840-468f-9a39-c6074c3094ce', '惜花', '惜花', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["落盡萬株紅，無人解繫風。","今朝芳徑裏，惆悵錦機空。"]', '["落尽万株紅，無人解繫风。","今朝芳徑裏，惆悵錦機空。"]', '诗', 'shi', '', NULL, '惜花 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b94cb12f-0b0d-4fc0-8fbe-1458502c32a0', '衝夜行', '衝夜行', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夜行無月時，古路多荒榛。","山鬼搖把火，自照不照人。"]', '["夜行無月时，古路多荒榛。","山鬼搖把火，自照不照人。"]', '诗', 'shi', '', NULL, '衝夜行 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e97218-844f-4719-907e-57e2a55d5aa6', '夜愁曲', '夜愁曲', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["歌者歌未絕，愁人愁轉增。","空把琅玕枝，強挑無心燈。"]', '["歌者歌未絕，愁人愁轉增。","空把琅玕枝，強挑無心灯。"]', '诗', 'shi', '', NULL, '夜愁曲 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1915c7-8b5b-46f5-8710-ee7a6da1c1b7', '雜古詞五首 一', '杂古词五首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["可憐江北女，慣唱江南曲。","搖蕩木蘭舟，雙鳧不成浴。"]', '["可怜江北女，慣唱江南曲。","搖蕩木蘭舟，雙鳧不成浴。"]', '诗', 'shi', '', NULL, '雜古詞五首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('574da8ad-4a82-4a46-979c-849faf124cbb', '雜古詞五首 二', '杂古词五首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["郎爲七上香，妾作籠下灰。","歸時即暖熱，去罷生塵埃。"]', '["郎爲七上香，妾作籠下灰。","归时即暖熱，去罷生塵埃。"]', '诗', 'shi', '', NULL, '雜古詞五首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5efef32-c2b2-4e04-a413-95485b6c431b', '雜古詞五首 三', '杂古词五首 三', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夜裁鴛鴦綺，朝織蒲桃綾。","欲試一寸心，待縫三尺冰。"]', '["夜裁鴛鴦綺，朝织蒲桃綾。","欲試一寸心，待縫三尺冰。"]', '诗', 'shi', '', NULL, '雜古詞五首 三 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ab529b-04dc-4bde-8594-e3b05c8e16c1', '雜古詞五首 四', '杂古词五首 四', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["憐時魚得水，怨罷商與參。","不如山梔子，却能結同心。"]', '["怜时鱼得水，怨罷商與參。","不如山梔子，却能結同心。"]', '诗', 'shi', '', NULL, '雜古詞五首 四 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e73002f-e2fe-4790-b453-106b76df2c44', '雜古詞五首 五', '杂古词五首 五', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["紅顏感暮花，白日同流水。","思君若孤燈，一夜一心死。"]', '["紅顏感暮花，白日同流水。","思君若孤灯，一夜一心死。"]', '诗', 'shi', '', NULL, '雜古詞五首 五 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b81abc2-fe08-4d17-818a-8ff93547eb9a', '幼女詞', '幼女词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["幼女纔六歲，未知巧與拙。","向夜在堂前，學人拜新月。"]', '["幼女纔六歲，未知巧與拙。","向夜在堂前，学人拜新月。"]', '诗', 'shi', '', NULL, '幼女詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82e9313e-2ceb-49ae-8a95-e73b15b55cb8', '買地詞', '買地词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["買地不惜錢，爲多芳桂叢。","所期在清涼，坐起聞香風。"]', '["買地不惜錢，爲多芳桂叢。","所期在清涼，坐起闻香风。"]', '诗', 'shi', '', NULL, '買地詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a32175d3-ae78-4240-bf42-94a9eb6f194c', '弋陽訪古', '弋陽訪古', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["行逢葛溪水，不見葛仙人。","空拋青竹杖，呪作葛陂神。"]', '["行逢葛溪水，不见葛仙人。","空拋青竹杖，呪作葛陂神。"]', '诗', 'shi', '', NULL, '弋陽訪古 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca607987-8ab9-464f-8802-c5e45bb12ca6', '幽居樂', '幽居乐', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["萬籟不在耳，寂寥心境清。","無妨數莖竹，時有蕭蕭聲。"]', '["万籟不在耳，寂寥心境清。","無妨數莖竹，时有蕭蕭声。"]', '诗', 'shi', '', NULL, '幽居樂 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27b92fa-23c2-4095-80a3-c43fd4e1ac26', '湘川懷古', '湘川懷古', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["湘水終日流，湘妃昔時哭。","美色已成塵，淚痕猶在竹。"]', '["湘水終日流，湘妃昔时哭。","美色已成塵，泪痕猶在竹。"]', '诗', 'shi', '', NULL, '湘川懷古 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72daa63-bddf-4ceb-9823-8e472db73c97', '秋山吟', '秋山吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夜吟秋山上，褭褭秋風歸。","月色清且[冷]，桂香落人衣。"]', '["夜吟秋山上，褭褭秋风归。","月色清且[冷]，桂香落人衣。"]', '诗', 'shi', '', NULL, '秋山吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f9b53d-4092-409e-955c-63bd684463a3', '寒夜', '寒夜', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["三復招隱吟，不知寒夜深。","看看西來月，移到青天心。"]', '["三复招隐吟，不知寒夜深。","看看西来月，移到青天心。"]', '诗', 'shi', '', NULL, '寒夜 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d650b17b-c1ad-47f9-a8f6-f6cfea468dc9', '湘竹詞', '湘竹词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["萬古湘江竹，無窮奈怨何。","年年長春筍，只是淚痕多。"]', '["万古湘江竹，無窮奈怨何。","年年长春筍，只是泪痕多。"]', '诗', 'shi', '', NULL, '湘竹詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8769cb35-f928-49b7-a338-1d2d4e8af7b7', '觀花後遊慈恩寺', '观花後游慈恩寺', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["世事知難了，應須問苦空。","羞將看花眼，來入梵王宮。"]', '["世事知难了，應須问苦空。","羞將看花眼，来入梵王宮。"]', '诗', 'shi', '', NULL, '觀花後遊慈恩寺 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb027138-9930-4848-a754-5ed841537d32', '乞巧詞', '乞巧词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["乞巧望星河，雙雙並綺羅。","不嫌針眼小，只道月明多。"]', '["乞巧望星河，雙雙並綺羅。","不嫌針眼小，只道月明多。"]', '诗', 'shi', '', NULL, '乞巧詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb6b7e3-eb7f-4d48-8022-3d0eb6798383', '不見來詞', '不见来词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["烏鵲語千回，黃昏不見來。","漫教脂粉匣，閉了又重開。"]', '["烏鵲語千回，黄昏不见来。","漫教脂粉匣，閉了又重开。"]', '诗', 'shi', '', NULL, '不見來詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411635e8-0f39-4272-a8ba-a50845cc7b97', '夜起來', '夜起来', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["香銷連理帶，塵覆合歡桮。","嬾臥相思枕，愁吟夜起來。"]', '["香銷連理带，塵覆合歡桮。","嬾臥相思枕，愁吟夜起来。"]', '诗', 'shi', '', NULL, '夜起來 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ff59ae-f01a-4eaa-851a-f73d69decb54', '笑卿卿詞', '笑卿卿词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["笑向卿卿道，躭書夜夜多。","出來看玉兔，又欲過銀河。"]', '["笑向卿卿道，躭书夜夜多。","出来看玉兔，又欲過銀河。"]', '诗', 'shi', '', NULL, '笑卿卿詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2fe41e-b5a8-4f28-80e9-83d78ca8d522', '感遇詞', '感遇词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["一種貌如仙，人情要自偏。","羅敷有底好，最得使君憐。"]', '["一種貌如仙，人情要自偏。","羅敷有底好，最得使君怜。"]', '诗', 'shi', '', NULL, '感遇詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3474f68-a050-48cf-8d0d-a4f73309ec2c', '及第後夜訪月仙子', '及第後夜訪月仙子', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["自喜尋幽夜，新當及第年。","還將天上桂，來訪月中仙。"]', '["自喜尋幽夜，新當及第年。","還將天上桂，来訪月中仙。"]', '诗', 'shi', '', NULL, '及第後夜訪月仙子 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b430204b-04b7-4d63-90ac-898f9fefa341', '定情樂 一', '定情乐 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["敢嗟君不憐，自是命不諧。","著破三條裙，却還雙股釵。"]', '["敢嗟君不怜，自是命不諧。","著破三條裙，却還雙股釵。"]', '诗', 'shi', '', NULL, '定情樂 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f797cbc-2c50-4692-a513-57ce7fadb055', '定情樂 二', '定情乐 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["感郎雙條脫，新破八幅綃。","不惜榆莢錢，買人金步搖。"]', '["感郎雙條脫，新破八幅綃。","不惜榆莢錢，買人金步搖。"]', '诗', 'shi', '', NULL, '定情樂 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4e116d-c270-4860-ba40-36c7a5573226', '宿南一上人山房', '宿南一上人山房', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["窗牖月色多，坐臥禪心靜。","青鬼來試人，夜深弄燈影。"]', '["窗牖月色多，坐臥禪心静。","青鬼来試人，夜深弄灯影。"]', '诗', 'shi', '', NULL, '宿南一上人山房 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f231ad07-e888-454a-bfa1-6544d95f1696', '蘭渚泊', '蘭渚泊', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["家在洞水西，身作蘭渚客。","天晝無纖雲，獨坐空江碧。"]', '["家在洞水西，身作蘭渚客。","天晝無纖云，独坐空江碧。"]', '诗', 'shi', '', NULL, '蘭渚泊 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeec8ef4-a521-4479-a72d-79ed17129f7f', '經吳真君舊宅', '經吳真君旧宅', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["古仙煉丹處，不測何歲年。","至今空宅基，時有五色煙。"]', '["古仙煉丹处，不測何歲年。","至今空宅基，时有五色煙。"]', '诗', 'shi', '', NULL, '經吳真君舊宅 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff655a33-2f9f-4d3e-b04f-6dc0e85e315f', '古相思', '古相思', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["十訪九不見，甚於菖蒲花。","可憐雲中月，今夜墮我家。"]', '["十訪九不见，甚於菖蒲花。","可怜云中月，今夜墮我家。"]', '诗', 'shi', '', NULL, '古相思 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f743153-575a-413e-b217-b10d18c723e9', '瀑布', '瀑布', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["豁開青冥顛，寫出萬丈泉。","如裁一條素，白日懸秋天。"]', '["豁开青冥顛，寫出万丈泉。","如裁一條素，白日懸秋天。"]', '诗', 'shi', '', NULL, '瀑布 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6c15c8-80b1-46d9-a0a5-93b3566c89d2', '金尺石', '金尺石', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["丹砂畫頑石，黃金橫一尺。","人世較短長，仙家愛平直。"]', '["丹砂畫頑石，黄金橫一尺。","人世較短长，仙家愛平直。"]', '诗', 'shi', '', NULL, '金尺石 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083c5d84-4001-4404-9f54-e7a12a526435', '秋洞宿', '秋洞宿', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夜深秋洞裏，風雨報龍歸。","何事觸人睡，不教胡蝶飛。"]', '["夜深秋洞裏，风雨報龙归。","何事觸人睡，不教胡蝶飞。"]', '诗', 'shi', '', NULL, '秋洞宿 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75c289e7-b9af-4ed5-b2b7-289d82f8710e', '效古詞', '效古词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["姊妹無多兄弟少，舉家鍾愛年最小。","有時繞樹山鵲飛，貪看不待畫眉了。"]', '["姊妹無多兄弟少，舉家鍾愛年最小。","有时繞樹山鵲飞，貪看不待畫眉了。"]', '诗', 'shi', '', NULL, '效古詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c577244-da4d-49de-8ebd-2f567888e89f', '山中得劉秀才京書', '山中得劉秀才京书', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["自笑家貧客到疎，滿庭煙草不能鋤。","今朝誰料三千里，忽得劉京一紙書。"]', '["自笑家貧客到疎，满庭煙草不能鋤。","今朝誰料三千里，忽得劉京一紙书。"]', '诗', 'shi', '', NULL, '山中得劉秀才京書 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02be2b59-bf17-4d89-82a6-08a0f4d99d3c', '望夫詞', '望夫词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["手爇寒燈向影頻，回文機上暗生塵。","自家夫壻無消息，却恨橋頭賣卜人。"]', '["手爇寒灯向影頻，回文機上暗生塵。","自家夫壻無消息，却恨橋头賣卜人。"]', '诗', 'shi', '', NULL, '望夫詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705098b0-0d29-4eb9-9d3e-417bb6dfc858', '憶四明山泉', '憶四明山泉', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["愛彼山中石泉水，幽深夜夜落空裏。","至今憶得臥雲時，猶自涓涓在人耳。"]', '["愛彼山中石泉水，幽深夜夜落空裏。","至今憶得臥云时，猶自涓涓在人耳。"]', '诗', 'shi', '', NULL, '憶四明山泉 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429449c0-e850-42b6-8d84-b80d39bf0712', '西山靜中吟', '西山静中吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["重重道氣結成神，玉闕金堂逐日新。","若數西山得道者，連予便是十三人。"]', '["重重道氣結成神，玉闕金堂逐日新。","若數西山得道者，連予便是十三人。"]', '诗', 'shi', '', NULL, '西山靜中吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f04e60d-2bb3-4169-82d0-b0271855767b', '天柱山贈峨嵋田道士', '天柱山贈峨嵋田道士', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["古稱天柱連九天，峨嵋道士棲其巔。","近聞教得玄鶴舞，試憑驅出青芝田。"]', '["古稱天柱連九天，峨嵋道士棲其巔。","近闻教得玄鹤舞，試憑驱出青芝田。"]', '诗', 'shi', '', NULL, '天柱山贈峨嵋田道士 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a9144aa-377f-46a0-b043-dc1565181b06', '夜巖謠', '夜巖謠', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夜上幽巖踏靈草，松枝已疎桂枝老。","新詩幾度惜不吟，此處一聲風月好。"]', '["夜上幽巖踏靈草，松枝已疎桂枝老。","新诗幾度惜不吟，此处一声风月好。"]', '诗', 'shi', '', NULL, '夜巖謠 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33c3d8b6-ed09-4eef-a00a-3ef6869892aa', '島夷行', '島夷行', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["腥臊海邊多鬼市，島夷居處無鄉里。","黑皮少年學採珠，手把生犀照鹹水。"]', '["腥臊海邊多鬼市，島夷居处無乡里。","黑皮少年学採珠，手把生犀照鹹水。"]', '诗', 'shi', '', NULL, '島夷行 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06353c64-c0ca-4688-9f7c-b83af168c96b', '帝宮詞', '帝宮词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["自得居王寵愛時，敢言春色上寒枝。","十年宮裏無人問，一日承恩天下知。"]', '["自得居王寵愛时，敢言春色上寒枝。","十年宮裏無人问，一日承恩天下知。"]', '诗', 'shi', '', NULL, '帝宮詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6055cd0f-b5c7-4258-afe3-01ba81223d11', '歎花詞', '歎花词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["前日滿林紅錦遍，今日遶林看不見。","空餘古岸泥土中，零落臙脂兩三片。"]', '["前日满林紅錦遍，今日遶林看不见。","空餘古岸泥土中，零落臙脂兩三片。"]', '诗', 'shi', '', NULL, '歎花詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70114318-6826-4b21-b178-205a3571e8ed', '杜鵑花詞', '杜鵑花词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["杜鵑花時夭豔然，所恨帝城人不識。","丁寧莫遣春風吹，留與佳人比顏色。"]', '["杜鵑花时夭豔然，所恨帝城人不識。","丁寧莫遣春风吹，留與佳人比顏色。"]', '诗', 'shi', '', NULL, '杜鵑花詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56510a0d-629b-444d-83de-ecea3c061225', '曉光詞', '晓光词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["日輪浮動羲和推，東方一軋天門開。","風神爲我掃煙霧，四海蕩蕩無塵埃。"]', '["日輪浮动羲和推，东方一軋天门开。","风神爲我掃煙霧，四海蕩蕩無塵埃。"]', '诗', 'shi', '', NULL, '曉光詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2de1137-3bf1-499b-b95d-28344505cdb5', '望曉詞', '望晓词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["攬衣起兮望秋河，濛濛遠霧飛輕羅。","蟠桃樹上日欲出，白榆枝畔星無多。"]', '["攬衣起兮望秋河，濛濛远霧飞轻羅。","蟠桃樹上日欲出，白榆枝畔星無多。"]', '诗', 'shi', '', NULL, '望曉詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('362cc777-453f-4b1f-bdc7-d51d898b14cf', '海邊遠望', '海邊远望', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["扶桑枝邊紅皎皎，天雞一聲四溟曉。","偶看仙女上青天，鸞鶴無多采雲少。"]', '["扶桑枝邊紅皎皎，天雞一声四溟晓。","偶看仙女上青天，鸾鹤無多采云少。"]', '诗', 'shi', '', NULL, '海邊遠望 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c1c2c26-b628-44d7-b864-9efc8d1c5f15', '聽南僧說偈詞', '听南僧说偈词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["師子座中香已發，西方佛偈南僧說。","惠風吹盡六條塵，清淨水中初見月。"]', '["師子座中香已發，西方佛偈南僧说。","惠风吹尽六條塵，清淨水中初见月。"]', '诗', 'shi', '', NULL, '聽南僧說偈詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff22961-f2c4-4fac-af4d-8d7cc9a1bb0e', '春日美新綠詞', '春日美新綠词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["前日萌芽小於粟，今朝草樹色已足。","天公不語能運爲，驅遣羲和染新綠。"]', '["前日萌芽小於粟，今朝草樹色已足。","天公不語能運爲，驱遣羲和染新綠。"]', '诗', 'shi', '', NULL, '春日美新綠詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c8a33ed-37db-4000-8a4c-c324b98019f8', '對月憶嵩陽故人', '对月憶嵩陽故人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["團團月光照西壁，嵩陽故人千里隔。","不知三十六峰前，定為何處峰前客。"]', '["團團月光照西壁，嵩陽故人千里隔。","不知三十六峰前，定為何处峰前客。"]', '诗', 'shi', '', NULL, '對月憶嵩陽故人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f90581-b748-4e6f-aa25-0a927e21724c', '贈莎地道士', '贈莎地道士', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["莎地陰森古蓮葉，游龜暗老青苔甲。","池邊道士誇眼明，夜取蟭螟摘蚊睫。"]', '["莎地陰森古蓮葉，游龟暗老青苔甲。","池邊道士誇眼明，夜取蟭螟摘蚊睫。"]', '诗', 'shi', '', NULL, '贈莎地道士 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4508e08c-0792-4ada-83d1-62bd1f41529a', '效古詞', '效古词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["莫愁新得年十六，如蛾雙眉長帶綠。","初學箜篌四五人，莫愁獨自聲前足。"]', '["莫愁新得年十六，如蛾雙眉长带綠。","初学箜篌四五人，莫愁独自声前足。"]', '诗', 'shi', '', NULL, '效古詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623d04dd-0497-4549-9292-a11a4fd1974c', '冬日觀早朝', '冬日观早朝', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["紫煙捧日爐香動，萬馬千車踏新凍。","繡衣年少朝欲歸，美人猶在青樓夢。"]', '["紫煙捧日爐香动，万马千车踏新凍。","繡衣年少朝欲归，美人猶在青楼梦。"]', '诗', 'shi', '', NULL, '冬日觀早朝 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb3997a-a90e-4cd0-bdbe-f62a809fde42', '觀吳偃畫松', '观吳偃畫松', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["君有絕藝終身寶，方寸巧心通萬造。","忽然寫出澗底松，筆下看看一枝老。"]', '["君有絕藝終身寶，方寸巧心通万造。","忽然寫出澗底松，笔下看看一枝老。"]', '诗', 'shi', '', NULL, '觀吳偃畫松 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d80126-aad8-4075-b709-f82cfdbbacdb', '題山僧水閣', '題山僧水閣', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["山房水閣連空翠，沈沈下有蛟龍睡。","老僧趺坐入定時，不知花落黃金地。"]', '["山房水閣連空翠，沈沈下有蛟龙睡。","老僧趺坐入定时，不知花落黄金地。"]', '诗', 'shi', '', NULL, '題山僧水閣 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('666083fd-56aa-4a28-98e3-c90344d22a36', '登峴亭懷孟生', '登峴亭懷孟生', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["峴山自高水自綠，後輩詞人心眼俗。","鹿門才子不再生，怪景幽奇無管屬。"]', '["峴山自高水自綠，後輩词人心眼俗。","鹿门才子不再生，怪景幽奇無管屬。"]', '诗', 'shi', '', NULL, '登峴亭懷孟生 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2224e0c-013e-420d-a963-9aff74177041', '吳中代蜀客吟', '吳中代蜀客吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["身狎吳兒客在蜀，春深屢唱思鄉曲。","峨眉風景無主人，錦江悠悠爲誰綠。"]', '["身狎吳兒客在蜀，春深屢唱思乡曲。","峨眉风景無主人，錦江悠悠爲誰綠。"]', '诗', 'shi', '', NULL, '吳中代蜀客吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54449109-03a1-424c-ad51-f3a7a7e0b762', '戲詠榆莢', '戲詠榆莢', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["風吹榆錢落如雨，繞林繞屋來不住。","知爾不堪還酒家，漫教夷甫無行處。"]', '["风吹榆錢落如雨，繞林繞屋来不住。","知爾不堪還酒家，漫教夷甫無行处。"]', '诗', 'shi', '', NULL, '戲詠榆莢 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee9e9882-8e02-4d13-84ae-8f39fb0ae704', '寄李補闕', '寄李補闕', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["蒼生應怪君起遲，蒲輪重輾嵩陽道。","功成名遂來不來，三十六峰仙鶴老。"]', '["蒼生應怪君起遲，蒲輪重輾嵩陽道。","功成名遂来不来，三十六峰仙鹤老。"]', '诗', 'shi', '', NULL, '寄李補闕 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49cf6b67-8b6b-46f0-ad47-ef17cbcfac36', '貧客吟', '貧客吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["𣰦毯敝衣無處結，寸心耿耿如刀切。","今朝欲泣泉客珠，及到盤中却成血。"]', '["𣰦毯敝衣無处結，寸心耿耿如刀切。","今朝欲泣泉客珠，及到盤中却成血。"]', '诗', 'shi', '', NULL, '貧客吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5021be5a-24e9-4989-b4d0-d02c9dde0c55', '誚山中叟', '誚山中叟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["老人今年八十幾，口中零落殘牙齒。","天陰傴僂帶嗽行，猶向巖前種松子。"]', '["老人今年八十幾，口中零落殘牙齒。","天陰傴僂带嗽行，猶向巖前種松子。"]', '诗', 'shi', '', NULL, '誚山中叟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17bb1736-2550-4b20-b965-917709a600f3', '聞山中步虛聲', '闻山中步虛声', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["何人步虛南峰頂，鶴唳九天霜月冷。","仙詞偶逐東風來，誤飄數聲落塵境。"]', '["何人步虛南峰頂，鹤唳九天霜月冷。","仙词偶逐东风来，誤飄數声落塵境。"]', '诗', 'shi', '', NULL, '聞山中步虛聲 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4a615b-8c44-4191-a88e-393a8aa7deb5', '題龍池山人', '題龙池山人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["主人家在龍池側，水中有魚不敢食。","終朝采藥供仙廚，却笑桃花少顏色。"]', '["主人家在龙池側，水中有鱼不敢食。","終朝采藥供仙廚，却笑桃花少顏色。"]', '诗', 'shi', '', NULL, '題龍池山人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3ead9f-0740-445c-b153-01f9e7cd7e82', '翫新桃花', '翫新桃花', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["幾歎紅桃開未得，忽驚造化新裝飾。","一種同霑榮盛時，偏荷清光借顏色。"]', '["幾歎紅桃开未得，忽驚造化新裝飾。","一種同霑榮盛时，偏荷清光借顏色。"]', '诗', 'shi', '', NULL, '翫新桃花 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a97674b4-c9bb-49fc-9809-cf58337f5b6a', '山石榴花', '山石榴花', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["深色臙脂碎剪紅，巧能攢合是天公。","莫言無物堪相比，妖豔西施春驛中。"]', '["深色臙脂碎剪紅，巧能攢合是天公。","莫言無物堪相比，妖豔西施春驛中。"]', '诗', 'shi', '', NULL, '山石榴花 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d588c37-d1de-437e-b875-8ff964599bcb', '翫友人庭竹', '翫友人庭竹', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["曾去玄洲看種玉，那似君家滿庭竹。","客來不用呼清風，此處挂冠涼自足。"]', '["曾去玄洲看種玉，那似君家满庭竹。","客来不用呼清风，此处挂冠涼自足。"]', '诗', 'shi', '', NULL, '翫友人庭竹 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89006e8f-f377-4719-ae8d-6fddb46052b4', '秋夜山居二首 一', '秋夜山居二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["幽居正想飡霞客，夜久月寒珠露滴。","千年獨鶴兩三聲，飛下巖前一枝柏。"]', '["幽居正想飡霞客，夜久月寒珠露滴。","千年独鹤兩三声，飞下巖前一枝柏。"]', '诗', 'shi', '', NULL, '秋夜山居二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('019b7e56-a255-4b88-b097-0d038ad2af51', '秋夜山居二首 二', '秋夜山居二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["去鴈聲遙人語絕，誰家素機織新雪。","秋山野客醉醒時，百尺老松銜半月。"]', '["去鴈声遙人語絕，誰家素機织新雪。","秋山野客醉醒时，百尺老松銜半月。"]', '诗', 'shi', '', NULL, '秋夜山居二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d42709ce-9c14-451d-8b6f-4253c363a18a', '秋夜山中別友人', '秋夜山中別友人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["獨鶴孤雲兩難說，明朝又作東西別。","知君少壯無幾年，莫愛閑吟老松月。"]', '["独鹤孤云兩难说，明朝又作东西別。","知君少壯無幾年，莫愛闲吟老松月。"]', '诗', 'shi', '', NULL, '秋夜山中別友人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('078f4ec7-6634-44b2-ba3d-f19e322069cb', '贈別王鍊師往羅浮', '贈別王鍊師往羅浮', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["道俗駢闐留不住，羅浮山上有心期。","却愁仙處人難到，別後音書寄與誰。"]', '["道俗駢闐留不住，羅浮山上有心期。","却愁仙处人难到，別後音书寄與誰。"]', '诗', 'shi', '', NULL, '贈別王鍊師往羅浮 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc22e0a-4759-41f1-8073-e5a084deee2f', '春日飡霞閣', '春日飡霞閣', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["灑水初晴物候新，飡霞閣上最宜春。","山花四面風吹入，爲我鋪牀作錦茵。"]', '["灑水初晴物候新，飡霞閣上最宜春。","山花四面风吹入，爲我鋪牀作錦茵。"]', '诗', 'shi', '', NULL, '春日飡霞閣 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785dec2a-6bae-4047-934f-49dbeaa6c85e', '喜友再相逢', '喜友再相逢', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["三十年前與君別，可憐容色奪花紅。","誰知日月相催促，此度見君成老翁。"]', '["三十年前與君別，可怜容色奪花紅。","誰知日月相催促，此度见君成老翁。"]', '诗', 'shi', '', NULL, '喜友再相逢 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae8fcdb2-b1dd-4deb-b563-b892e197f2af', '候仙詞', '候仙词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["西歸公子何時降，南岳先生早晚來。","巡歷世間猶未遍，乞求鸞鶴且裴回。"]', '["西归公子何时降，南岳先生早晚来。","巡歷世间猶未遍，乞求鸾鹤且裴回。"]', '诗', 'shi', '', NULL, '候仙詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41f5972b-8568-49a8-bbf9-8960f3e1ba0b', '修仙詞', '修仙词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["丹田自種留年藥，玄谷長生續命芝。","世上漫忙兼漫走，不知求己更求誰。"]', '["丹田自種留年藥，玄谷长生續命芝。","世上漫忙兼漫走，不知求己更求誰。"]', '诗', 'shi', '', NULL, '修仙詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adcc33c6-741a-439e-8177-3bb08ac7f64c', '夏日題方師院', '夏日題方師院', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["火天無處買清風，悶發時來入梵宮。","只向方師小廊下，回看門外是樊籠。"]', '["火天無处買清风，悶發时来入梵宮。","只向方師小廊下，回看门外是樊籠。"]', '诗', 'shi', '', NULL, '夏日題方師院 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45cf8159-2370-4185-988e-5cd82037d543', '春游樂', '春游乐', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["一年三百六十日，賞心那似春中物。","草迷曲塢花滿園，東家少年西家出。"]', '["一年三百六十日，賞心那似春中物。","草迷曲塢花满园，东家少年西家出。"]', '诗', 'shi', '', NULL, '春游樂 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('375b5e8e-cd0d-4430-9d9d-7159f41684f5', '仙客歸鄉詞二首 一', '仙客归乡词二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["六合八荒游未半，子孫零落暫歸來。","井邊不認捎雲樹，多是門人在後栽。"]', '["六合八荒游未半，子孫零落暫归来。","井邊不認捎云樹，多是门人在後栽。"]', '诗', 'shi', '', NULL, '仙客歸鄉詞二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee0a4f1-c368-4588-8b35-957b2a3d609e', '仙客歸鄉詞二首 二', '仙客归乡词二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["洞中日月洞中仙，不算離家是幾年。","出郭始知人代變，又須拋却古時錢。"]', '["洞中日月洞中仙，不算離家是幾年。","出郭始知人代变，又須拋却古时錢。"]', '诗', 'shi', '', NULL, '仙客歸鄉詞二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e534c272-e750-4509-b183-60894334a6e1', '雲州飲席', '云州饮席', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["酒腸雖滿少歡情，身在雲州望帝城。","巡次合當誰令改，先須爲我打還京。"]', '["酒腸雖满少歡情，身在云州望帝城。","巡次合當誰令改，先須爲我打還京。"]', '诗', 'shi', '', NULL, '雲州飲席 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3847ab3-6a25-4df2-b5a1-179c541e2170', '戲贈李主簿', '戲贈李主簿', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["官罷江南客恨遙，二年空被酒中消。","不知暗數春游處，偏憶揚州第幾橋。"]', '["官罷江南客恨遙，二年空被酒中消。","不知暗數春游处，偏憶揚州第幾橋。"]', '诗', 'shi', '', NULL, '戲贈李主簿 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1541605-2557-4216-93de-471947e3bd3c', '春詞', '春词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["黃鳥啼多春日高，紅芳開盡井邊桃。","美人手暖裁衣易，片片輕雲落剪刀。"]', '["黄鸟啼多春日高，紅芳开尽井邊桃。","美人手暖裁衣易，片片轻云落剪刀。"]', '诗', 'shi', '', NULL, '春詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42e6e48-4c94-45ee-8595-5e6bd8eb2449', '題景上人山門', '題景上人山门', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["水有青蓮沙有金，老僧於此獨觀心。","愁人欲寄中峰宿，只恐白猨啼夜深。"]', '["水有青蓮沙有金，老僧於此独观心。","愁人欲寄中峰宿，只恐白猨啼夜深。"]', '诗', 'shi', '', NULL, '題景上人山門 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ae33b4-839a-485e-b7bc-08dabc2b361d', '妓人殘粧詞', '妓人殘粧词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["雲髻已收金鳳皇，巧勻輕黛約殘粧。","不知昨夜新歌響，猶在誰家繞畫梁。"]', '["云髻已收金鳳皇，巧勻轻黛約殘粧。","不知昨夜新歌响，猶在誰家繞畫梁。"]', '诗', 'shi', '', NULL, '妓人殘粧詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4edd187-408c-42fc-a01f-e1561bbe8393', '臨水亭', '臨水亭', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["只怪素亭黏黛色，溪煙爲我染莓苔。","欲知源上春風起，看取桃花逐水來。"]', '["只怪素亭黏黛色，溪煙爲我染莓苔。","欲知源上春风起，看取桃花逐水来。"]', '诗', 'shi', '', NULL, '臨水亭 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea4a211-6ab1-47b2-8e44-1a5c0375b89f', '聽范玄長吟', '听范玄长吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["聲聲扣出碧琅玕，能使秋猨欲呌難。","詩興未窮心更遠，手垂青拂向雲看。"]', '["声声扣出碧琅玕，能使秋猨欲呌难。","诗兴未窮心更远，手垂青拂向云看。"]', '诗', 'shi', '', NULL, '聽范玄長吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6bc6d3d-576c-40c2-8736-922e8f15d9e0', '觀葉生畫花', '观葉生畫花', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["心竅玲瓏貌亦奇，榮枯只在手中移。","今朝故向霜天裏，點破繁花四五枝。"]', '["心竅玲瓏貌亦奇，榮枯只在手中移。","今朝故向霜天裏，点破繁花四五枝。"]', '诗', 'shi', '', NULL, '觀葉生畫花 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d0e8c4-703d-4ffe-8eb3-fa0528a36bc9', '洗丹沙詞', '洗丹沙词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["千淘萬洗紫光攢，夜火熒熒照玉盤。","恐是麻姑殘米粒，不曾將與世人看。"]', '["千淘万洗紫光攢，夜火熒熒照玉盤。","恐是麻姑殘米粒，不曾將與世人看。"]', '诗', 'shi', '', NULL, '洗丹沙詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684ce1ad-fd44-4653-9510-57fd45d8fd6e', '長安春夜吟', '长安春夜吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["露盤滴時河漢微，美人燈下裁春衣。","蟾蜍東去鵲南飛，芸香省中郎不歸。"]', '["露盤滴时河漢微，美人灯下裁春衣。","蟾蜍东去鵲南飞，芸香省中郎不归。"]', '诗', 'shi', '', NULL, '長安春夜吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4881382-e972-4a80-a60c-dd0330570799', '自述', '自述', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["篋貯靈砂日日看，欲成仙法脫身難。","不知誰向交州去，爲謝羅浮葛長官。"]', '["篋貯靈砂日日看，欲成仙法脫身难。","不知誰向交州去，爲謝羅浮葛长官。"]', '诗', 'shi', '', NULL, '自述 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a907177-961e-41ab-a70a-77fd8d115b64', '少年行', '少年行', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["醉騎白馬走空衢，惡少皆稱電不如。","五鳳街頭新勒轡，半垂衫袖揖金吾。"]', '["醉騎白马走空衢，惡少皆稱電不如。","五鳳街头新勒轡，半垂衫袖揖金吾。"]', '诗', 'shi', '', NULL, '少年行 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30fc8128-f699-4222-8d61-407c7cd44c23', '越中遇寒食', '越中遇寒食', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["去歲清明霅溪口，今朝寒食鏡湖西。","信知天地心不易，還有子規依舊啼。"]', '["去歲清明霅溪口，今朝寒食镜湖西。","信知天地心不易，還有子規依旧啼。"]', '诗', 'shi', '', NULL, '越中遇寒食 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08767d13-f705-47d2-8faf-00bd32e63bf9', '贈採藥叟', '贈採藥叟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["老去唯將藥裹行，無家無累一身輕。","却教年少取書卷，小字燈前鬬眼明。"]', '["老去唯將藥裹行，無家無累一身轻。","却教年少取书卷，小字灯前鬬眼明。"]', '诗', 'shi', '', NULL, '贈採藥叟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d8e95f-b5d5-4887-afb2-475e9032210d', '清夜憶仙宮子', '清夜憶仙宮子', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夜靜門深紫洞煙，孤行獨坐憶神仙。","三清宫裏月如晝，十二宫樓何處眠。"]', '["夜静门深紫洞煙，孤行独坐憶神仙。","三清宫裏月如晝，十二宫楼何处眠。"]', '诗', 'shi', '', NULL, '清夜憶仙宮子 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a26677c-2a40-47dc-a6f7-392d9066a3fd', '江南怨', '江南怨', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["愁見橋邊荇葉新，蘭舟枕水楫生塵。","從來不是無蓮采，十頃蓮塘賣與人。"]', '["愁见橋邊荇葉新，蘭舟枕水楫生塵。","從来不是無蓮采，十頃蓮塘賣與人。"]', '诗', 'shi', '', NULL, '江南怨 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e09334e8-ee6e-427c-bb5a-7edd8742c48c', '送絕塵子歸舊隱二首 一', '送絕塵子归旧隐二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["雲水千重繞洞門，獨歸何處是桃源？仙方不用隨身去，留與人間老子孫。"]', '["云水千重繞洞门，独归何处是桃源？仙方不用隨身去，留與人间老子孫。"]', '诗', 'shi', '', NULL, '送絕塵子歸舊隱二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5e4cab2-4139-4b84-a049-77938896159c', '送絕塵子歸舊隱二首 二', '送絕塵子归旧隐二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["班藤爲杖草爲衣，萬壑千峰獨自歸。","縱令相憶誰相報，桂樹巖邊人信稀。"]', '["班藤爲杖草爲衣，万壑千峰独自归。","縱令相憶誰相報，桂樹巖邊人信稀。"]', '诗', 'shi', '', NULL, '送絕塵子歸舊隱二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155c42c8-4976-4d67-84f6-8ebe31854bff', '送裴秀才歸淮南', '送裴秀才归淮南', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["怪來頻起詠刀頭，楓葉枝邊一夕秋。","又向江南別才子，却將風景過揚州。"]', '["怪来頻起詠刀头，楓葉枝邊一夕秋。","又向江南別才子，却將风景過揚州。"]', '诗', 'shi', '', NULL, '送裴秀才歸淮南 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e7e33fe-c181-4586-95c7-7dc4d206646d', '錢塘渡口', '錢塘渡口', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["天塹茫茫連沃焦，秦皇何事不安橋。","錢塘渡口無錢納，已失西興兩信潮。"]', '["天塹茫茫連沃焦，秦皇何事不安橋。","錢塘渡口無錢納，已失西兴兩信潮。"]', '诗', 'shi', '', NULL, '錢塘渡口 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d48da5-66bc-4247-8687-d9649ccab279', '春日宴徐君池亭', '春日宴徐君池亭', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["暫憑春酒換愁顏，今日應須醉始還。","池上有門君莫掩，從教野客見青山。"]', '["暫憑春酒換愁顏，今日應須醉始還。","池上有门君莫掩，從教野客见青山。"]', '诗', 'shi', '', NULL, '春日宴徐君池亭 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2234542-d763-4045-a5c1-bf07e5419499', '山中送友人', '山中送友人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["欲折楊枝別恨生，一重枝上一啼鶯。","亂山重疊雲相掩，君向亂山何處行。"]', '["欲折楊枝別恨生，一重枝上一啼鶯。","亂山重叠云相掩，君向亂山何处行。"]', '诗', 'shi', '', NULL, '山中送友人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a2a12a-bca3-443c-b823-b1c95333faea', '寄王少府', '寄王少府', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["采松仙子徒銷日，喫菜山僧枉過生。","多謝藍田王少府，人間詩酒最關情。"]', '["采松仙子徒銷日，喫菜山僧枉過生。","多謝藍田王少府，人间诗酒最关情。"]', '诗', 'shi', '', NULL, '寄王少府 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a9e9566-7722-4675-98d4-e62c98fedc25', '贈女道士鄭玉華二首 一', '贈女道士鄭玉华二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["玄髮新簪碧藕花，欲添肌雪餌紅砂。","世間風景那堪戀，長笑劉郎漫憶家。"]', '["玄髮新簪碧藕花，欲添肌雪餌紅砂。","世间风景那堪戀，长笑劉郎漫憶家。"]', '诗', 'shi', '', NULL, '贈女道士鄭玉華二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a811379-9526-4288-bde8-5c1e150eb96a', '贈女道士鄭玉華二首 二', '贈女道士鄭玉华二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["明鏡湖中休采蓮，却師阿母學神仙。","朱絲誤落青囊裏，猶是箜篌第幾弦。"]', '["明镜湖中休采蓮，却師阿母学神仙。","朱絲誤落青囊裏，猶是箜篌第幾弦。"]', '诗', 'shi', '', NULL, '贈女道士鄭玉華二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d03ea4b-49bf-4926-a4fc-06dfd459ae36', '寄西臺李侍御', '寄西台李侍御', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["二千餘里採瓊瓌，到處傷心瓦礫堆。","唯有繡衣周柱史，獨將珠玉挂西臺。"]', '["二千餘里採瓊瓌，到处傷心瓦礫堆。","唯有繡衣周柱史，独將珠玉挂西台。"]', '诗', 'shi', '', NULL, '寄西臺李侍御 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b71efa80-e3d4-490a-baf6-89375f9f1bd8', '贈凌仙姥', '贈凌仙姥', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["阿母從天降幾時，前朝惟有漢皇知。","仙桃不啻三回熟，飽見東方一小兒。"]', '["阿母從天降幾时，前朝惟有漢皇知。","仙桃不啻三回熟，飽见东方一小兒。"]', '诗', 'shi', '', NULL, '贈凌仙姥 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950caaac-2d3c-4169-85ef-ddbb81fb6acf', '晚春送王秀才游剡川', '晚春送王秀才游剡川', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["越山花去剡藤新，才子風光不厭春。","第一莫尋溪上路，可憐仙女愛迷人。"]', '["越山花去剡藤新，才子风光不厭春。","第一莫尋溪上路，可怜仙女愛迷人。"]', '诗', 'shi', '', NULL, '晚春送王秀才游剡川 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e200db-3aee-4026-996e-b8379f83d935', '馮上人院', '馮上人院', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["擾擾凡情逐水流，世間多喜復多憂。","一回行到馮公院，便欲令人百事休。"]', '["擾擾凡情逐水流，世间多喜复多憂。","一回行到馮公院，便欲令人百事休。"]', '诗', 'shi', '', NULL, '馮上人院 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c222712b-85bd-4c71-9f32-9dc99fe85e71', '金吾詞', '金吾词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["行擁朱輪錦幨兒，望仙門外叱金羈。","染鬚偷嫩無人覺，唯有平康小婦知。"]', '["行擁朱輪錦幨兒，望仙门外叱金羈。","染鬚偷嫩無人覺，唯有平康小婦知。"]', '诗', 'shi', '', NULL, '金吾詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd53787f-12c7-4a4f-a8ab-a65f59027481', '觀舞女', '观舞女', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["纏紅結紫畏風吹，嫋娜初回弱柳枝。","買笑未知誰是主，萬人心逐一人移。"]', '["纏紅結紫畏风吹，嫋娜初回弱柳枝。","買笑未知誰是主，万人心逐一人移。"]', '诗', 'shi', '', NULL, '觀舞女 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63bc48e0-ff51-4649-8291-5602845d119b', '鄠縣村居', '鄠縣村居', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["欲住村西日日慵，上山無水引高蹤。","誰能求得秦皇術，爲我先驅紫閣峰。"]', '["欲住村西日日慵，上山無水引高蹤。","誰能求得秦皇術，爲我先驱紫閣峰。"]', '诗', 'shi', '', NULL, '鄠縣村居 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ef18d8-3faf-4ce6-9fb8-f9dd3c965f8f', '酬周秀才', '酬周秀才', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["三展蜀牋皆郢曲，我心珍重甚瓊瑤。","應緣水府龍神睡，偷得蛟人五色綃。"]', '["三展蜀牋皆郢曲，我心珍重甚瓊瑤。","應緣水府龙神睡，偷得蛟人五色綃。"]', '诗', 'shi', '', NULL, '酬周秀才 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3a0dc5-9bc8-467d-bf42-bc33440e35aa', '旅次文水縣喜遇李少府', '旅次文水縣喜遇李少府', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["爲君三日廢行程，一縣官人是酒朋。","共憶襄陽同醉處，尚書坐上納銀觥。"]', '["爲君三日廢行程，一縣官人是酒朋。","共憶襄陽同醉处，尚书坐上納銀觥。"]', '诗', 'shi', '', NULL, '旅次文水縣喜遇李少府 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01fadbde-1e4c-4a5f-bd20-989ee319f27e', '夏雨後題青荷蘭若', '夏雨後題青荷蘭若', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["僧舍清涼竹樹新，初經一雨洗諸塵。","微風忽起吹蓮葉，青玉盤中瀉水銀。"]', '["僧舍清涼竹樹新，初經一雨洗諸塵。","微风忽起吹蓮葉，青玉盤中瀉水銀。"]', '诗', 'shi', '', NULL, '夏雨後題青荷蘭若 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6e7fea-f41c-40ab-8aa4-adbec5aba2ff', '途中逢少女', '途中逢少女', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["身倚西門笑向東，牡丹初折一枝紅。","市頭日賣千般鏡，知落誰家新匣中。"]', '["身倚西门笑向东，牡丹初折一枝紅。","市头日賣千般镜，知落誰家新匣中。"]', '诗', 'shi', '', NULL, '途中逢少女 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4410bc-f0c0-4081-873d-de83848f5e68', '山中翫白鹿', '山中翫白鹿', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["繞洞尋花日易銷，人間無路得相招。","呦呦白鹿毛如雪，踏我桃花過石橋。"]', '["繞洞尋花日易銷，人间無路得相招。","呦呦白鹿毛如雪，踏我桃花過石橋。"]', '诗', 'shi', '', NULL, '山中翫白鹿 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30354055-e9c3-434f-908b-d96de447bfdb', '山居樂', '山居乐', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["鸞鶴每於松下見，笙歌常向坐中聞。","手持十節龍頭杖，不指虛空即指雲。"]', '["鸾鹤每於松下见，笙歌常向坐中闻。","手持十節龙头杖，不指虛空即指云。"]', '诗', 'shi', '', NULL, '山居樂 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c003a336-7adb-4458-9192-31b5b7a3861d', '襄陽曲', '襄陽曲', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["大堤女兒郎莫尋，三三五五結同心。","清晨對鏡理容色，意欲取郎千萬金。"]', '["大堤女兒郎莫尋，三三五五結同心。","清晨对镜理容色，意欲取郎千万金。"]', '诗', 'shi', '', NULL, '襄陽曲 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4f231c-c8fc-4b84-ba6a-30898c4048fa', '望夫詞二首 一', '望夫词二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["看看北鴈又南飛，薄倖征夫久不歸。","蟢子到頭無信處，凡經幾度上人衣。"]', '["看看北鴈又南飞，薄倖征夫久不归。","蟢子到头無信处，凡經幾度上人衣。"]', '诗', 'shi', '', NULL, '望夫詞二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48293382-6e69-433d-a221-695c4b1d3ff3', '望夫詞二首 二', '望夫词二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["何事經年斷書信，愁聞遠客說風波。","西家還有望夫伴，一種淚痕兒最多。"]', '["何事經年斷书信，愁闻远客说风波。","西家還有望夫伴，一種泪痕兒最多。"]', '诗', 'shi', '', NULL, '望夫詞二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e97469-e8bc-4263-8f5a-c60a53ce2b0b', '少婦游春詞', '少婦游春词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["簇錦攢花鬬勝遊，萬人行處最風流。","無端自向春園裏，笑摘青梅呌阿侯。"]', '["簇錦攢花鬬勝游，万人行处最风流。","無端自向春园裏，笑摘青梅呌阿侯。"]', '诗', 'shi', '', NULL, '少婦游春詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6587440-6531-42a2-a8c8-42a82bb2cb23', '折柳枝', '折柳枝', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["傷見路邊楊柳春，一重折盡一重新。","今年還折去年處，不送去年離別人。"]', '["傷见路邊楊柳春，一重折尽一重新。","今年還折去年处，不送去年離別人。"]', '诗', 'shi', '', NULL, '折柳枝 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d4bd71-7411-4594-afc3-93696ef28b25', '歸將吟', '归將吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["百戰放歸成老翁，餘生得出死人中。","今朝授敕三回舞，兩賜青娥又拜公。"]', '["百戰放归成老翁，餘生得出死人中。","今朝授敕三回舞，兩賜青娥又拜公。"]', '诗', 'shi', '', NULL, '歸將吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7447fabc-f3c7-4a72-8f7e-d12c32b76694', '惜花詞', '惜花词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["千樹繁紅遶碧泉，正宜尊酒對芳年。","明朝欲飲還來此，只怕春風却在前。"]', '["千樹繁紅遶碧泉，正宜尊酒对芳年。","明朝欲饮還来此，只怕春风却在前。"]', '诗', 'shi', '', NULL, '惜花詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6f7bbd5-76e8-444b-aa2b-c116f09b383d', '拋纏頭詞', '拋纏头词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["翠娥初罷繞梁詞，又見雙鬟對舞時。","一抱紅羅分不足，參差裂破鳳皇兒。"]', '["翠娥初罷繞梁词，又见雙鬟对舞时。","一抱紅羅分不足，參差裂破鳳皇兒。"]', '诗', 'shi', '', NULL, '拋纏頭詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79fcfad1-ca4c-4d7d-9a4d-c90efdd58ed7', '望騎馬郎', '望騎马郎', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["碧蹄新壓步初成，玉色郎君弄影行。","賺殺唱歌樓上女，伊州誤作石州聲。"]', '["碧蹄新壓步初成，玉色郎君弄影行。","賺殺唱歌楼上女，伊州誤作石州声。"]', '诗', 'shi', '', NULL, '望騎馬郎 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e26dafd-08ac-40b6-a324-0132945e95c2', '春日錢塘雜興二首 一', '春日錢塘杂兴二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["酒姥溪頭桑褭褭，錢塘郭外柳𣯶𣯶。","路逢鄰婦遙相問，小小如今學養蠶。"]', '["酒姥溪头桑褭褭，錢塘郭外柳𣯶𣯶。","路逢鄰婦遙相问，小小如今学養蠶。"]', '诗', 'shi', '', NULL, '春日錢塘雜興二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cbc723f-91d5-4036-8f9d-5ede9a06a1d1', '春日錢塘雜興二首 二', '春日錢塘杂兴二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["西鄰年少問東鄰，柳岸花隄幾處新。","昨夜雨多春水闊，隔江桃葉喚何人。"]', '["西鄰年少问东鄰，柳岸花隄幾处新。","昨夜雨多春水闊，隔江桃葉喚何人。"]', '诗', 'shi', '', NULL, '春日錢塘雜興二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abed2cda-b3ad-4603-84b7-87caf8d455db', '翫手植松', '翫手植松', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["却思毫末栽松處，青翠纔將衆草分。","今日散材遮不得，看看氣色欲凌雲。"]', '["却思毫末栽松处，青翠纔將衆草分。","今日散材遮不得，看看氣色欲凌云。"]', '诗', 'shi', '', NULL, '翫手植松 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8a8e67b-0b4a-4039-be48-0738bfe434f4', '夜笛詞', '夜笛词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["皎潔西樓月未斜，笛聲寥亮入東家。","却令燈下裁衣婦，誤翦同心一半花。"]', '["皎潔西楼月未斜，笛声寥亮入东家。","却令灯下裁衣婦，誤翦同心一半花。"]', '诗', 'shi', '', NULL, '夜笛詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a5cd3d4-b0de-40af-b7bd-798ef2f59245', '贈鄭倫吹鳳管', '贈鄭倫吹鳳管', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["喃喃解語鳳皇兒，曾聽棃園竹裏吹。","誰謂五陵年少子，還將此曲暗相隨。"]', '["喃喃解語鳳皇兒，曾听棃园竹裏吹。","誰謂五陵年少子，還將此曲暗相隨。"]', '诗', 'shi', '', NULL, '贈鄭倫吹鳳管 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a31eb4b4-a38b-4c62-81d7-f60c100d22b8', '蜀茗詞', '蜀茗词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["越椀初盛蜀茗新，薄煙輕處攪來勻。","山僧問我將何比，欲道瓊漿却畏嗔。"]', '["越椀初盛蜀茗新，薄煙轻处攪来勻。","山僧问我將何比，欲道瓊漿却畏嗔。"]', '诗', 'shi', '', NULL, '蜀茗詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d9a4ac9-b6ec-4c16-acfe-27f8f452756f', '春霽', '春霽', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["煎茶水裏花千片，候客亭中酒一樽。","獨對春光還寂寞，羅浮道士忽敲門。"]', '["煎茶水裏花千片，候客亭中酒一樽。","独对春光還寂寞，羅浮道士忽敲门。"]', '诗', 'shi', '', NULL, '春霽 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e79ad0d-dd06-4283-829f-4f3fda2a2adf', '諷山雲', '諷山云', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["閑雲生葉不生根，常被重重蔽石門。","賴有風簾能埽蕩，滿山晴日照乾坤。"]', '["闲云生葉不生根，常被重重蔽石门。","賴有风簾能埽蕩，满山晴日照乾坤。"]', '诗', 'shi', '', NULL, '諷山雲 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e64449-ebb9-4dc3-b16b-b8d735311321', '日晚歸山詞', '日晚归山词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["虎跡新逢雨後泥，無人家處洞邊溪。","獨行歸客晚山裏，賴有鷓鴣臨路岐。"]', '["虎跡新逢雨後泥，無人家处洞邊溪。","独行归客晚山裏，賴有鷓鴣臨路岐。"]', '诗', 'shi', '', NULL, '日晚歸山詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81a94106-b91e-4d2f-b7e1-5b733d4fb80b', '翫花詞', '翫花词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["今朝造化使春風，開拆西施面上紅。","竟日眼前猶不足，數株舁入寸心中。"]', '["今朝造化使春风，开拆西施面上紅。","竟日眼前猶不足，數株舁入寸心中。"]', '诗', 'shi', '', NULL, '翫花詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab875bd-ef9f-444e-af55-48a9704db121', '長安早春', '长安早春', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["報花消息是春風，未見先教何處紅。","想得芳園十餘日，萬家身在畫屏中。"]', '["報花消息是春风，未见先教何处紅。","想得芳园十餘日，万家身在畫屏中。"]', '诗', 'shi', '', NULL, '長安早春 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9188b70-edb6-41c4-b390-b6cdacdd7bb6', '再酬李先輩', '再酬李先輩', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["清辭再發郢人家，字字新移錦上花。","能使龍宮買綃女，低回不敢織輕霞。"]', '["清辞再發郢人家，字字新移錦上花。","能使龙宮買綃女，低回不敢织轻霞。"]', '诗', 'shi', '', NULL, '再酬李先輩 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e1be7d-78ea-4488-9c9e-9390be755430', '寄隱者', '寄隐者', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["路絕空林無處問，幽奇山水不知名。","松門拾得一片屐，知是高人向此行。"]', '["路絕空林無处问，幽奇山水不知名。","松门拾得一片屐，知是高人向此行。"]', '诗', 'shi', '', NULL, '寄隱者 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2e8111-f248-4d9c-b444-0876fbd460ab', '寄四明山子', '寄四明山子', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["高棲只在千峰裏，塵世望君那得知。","長憶去年風雨夜，向君窗下聽猨時。"]', '["高棲只在千峰裏，塵世望君那得知。","长憶去年风雨夜，向君窗下听猨时。"]', '诗', 'shi', '', NULL, '寄四明山子 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('348d8d23-941e-4829-8b3d-5a0227d7e66d', '觀美人', '观美人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["漆點雙眸鬢繞蟬，長留白雪占胸前。","愛將紅袖遮嬌笑，往往偷開水上蓮。"]', '["漆点雙眸鬢繞蟬，长留白雪占胸前。","愛將紅袖遮嬌笑，往往偷开水上蓮。"]', '诗', 'shi', '', NULL, '觀美人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('660b96e7-bbf6-4e09-a51e-55e9c1b1dfd9', '收妝詞', '收妝词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["斜月朧朧照半牀，煢煢孤妾嬾收妝。","燈前再覽青銅鏡，枉插金釵十二行。"]', '["斜月朧朧照半牀，煢煢孤妾嬾收妝。","灯前再覽青銅镜，枉插金釵十二行。"]', '诗', 'shi', '', NULL, '收妝詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80621b4a-d479-47bb-9a95-7e3e234a1030', '仙女詞', '仙女词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["仙女羣中名最高，曾看王母種仙桃。","手題金簡非凡筆，道是天邊玉兔毛。"]', '["仙女羣中名最高，曾看王母種仙桃。","手題金簡非凡笔，道是天邊玉兔毛。"]', '诗', 'shi', '', NULL, '仙女詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9a518b-c0fd-4d4f-91ae-f8fa7216835f', '仙翁詞', '仙翁词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["世間無遠可爲游，六合朝行夕已周。","壇上夜深風雨靜，小仙乘月繫蒼虯。"]', '["世间無远可爲游，六合朝行夕已周。","壇上夜深风雨静，小仙乘月繫蒼虯。"]', '诗', 'shi', '', NULL, '仙翁詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6669eca-ad3a-4012-a6d6-0304b37296de', '遇李山人', '遇李山人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["游山遊水幾千重，二十年中一度逢。","別易會難君且住，莫交青竹化爲龍。"]', '["游山游水幾千重，二十年中一度逢。","別易會难君且住，莫交青竹化爲龙。"]', '诗', 'shi', '', NULL, '遇李山人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dbc518-4324-4420-a216-ae2fcef143f1', '同張鍊師溪行', '同張鍊師溪行', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["青溪道士紫霞巾，洞裏仙家舊是鄰。","每見桃花逐流水，無回不憶武陵人。"]', '["青溪道士紫霞巾，洞裏仙家旧是鄰。","每见桃花逐流水，無回不憶武陵人。"]', '诗', 'shi', '', NULL, '同張鍊師溪行 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6062dc-c410-404b-89b3-a1f055ac8d01', '桃源詞二首 一', '桃源词二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["夭夭花裏千家住，總爲當時隱暴秦。","歸去不論無舊識，子孫今亦是他人。"]', '["夭夭花裏千家住，總爲當时隐暴秦。","归去不論無旧識，子孫今亦是他人。"]', '诗', 'shi', '', NULL, '桃源詞二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f24d1909-30fd-4c81-a969-41fdb58c0a43', '桃源詞二首 二', '桃源词二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["秦世老翁歸漢世，還同白鶴返遼城。","縱令記得山川路，莫問當時州縣名。"]', '["秦世老翁归漢世，還同白鹤返遼城。","縱令記得山川路，莫问當时州縣名。"]', '诗', 'shi', '', NULL, '桃源詞二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca19cfe7-213a-4934-b694-5d5233c1fd89', '送道友遊山', '送道友游山', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["欲駐如今未老形，萬重山上九芝清。","君今若問採芝路，踏水踏雲攀杳冥。"]', '["欲駐如今未老形，万重山上九芝清。","君今若问採芝路，踏水踏云攀杳冥。"]', '诗', 'shi', '', NULL, '送道友遊山 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3843f4c7-eb15-43fc-a850-79de3944f7e9', '贈王屋劉道士', '贈王屋劉道士', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["小有洞中長住客，大羅天下後來仙。","出門即是尋常處，未可還它跨鶴鞭。"]', '["小有洞中长住客，大羅天下後来仙。","出门即是尋常处，未可還它跨鹤鞭。"]', '诗', 'shi', '', NULL, '贈王屋劉道士 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d225df26-9bec-447b-8595-c2d8f668da4d', '謝自然升仙', '謝自然升仙', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["分明得道謝自然，古來漫說尸解仙。","如花年少一女子，身騎白鶴遊青天。"]', '["分明得道謝自然，古来漫说尸解仙。","如花年少一女子，身騎白鹤游青天。"]', '诗', 'shi', '', NULL, '謝自然升仙 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3eab095-e09a-42b3-bcea-f16121db3bc8', '秋吟獻李舍人', '秋吟獻李舍人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["腸結愁根酒不消，新驚白髮長愁苗。","主司儻許題名姓，筆下看成度海橋。"]', '["腸結愁根酒不消，新驚白髮长愁苗。","主司儻許題名姓，笔下看成度海橋。"]', '诗', 'shi', '', NULL, '秋吟獻李舍人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fdf511e-1350-4034-ac6f-a6ed85ec5270', '山中喜靜和子見訪', '山中喜静和子见訪', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["絕壁深溪無四鄰，每逢猨鶴即相親。","小奴驚出垂藤下，山犬今朝吠一人。"]', '["絕壁深溪無四鄰，每逢猨鹤即相親。","小奴驚出垂藤下，山犬今朝吠一人。"]', '诗', 'shi', '', NULL, '山中喜靜和子見訪 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9733e3-265c-4c5c-bd04-e82f013a7e27', '春日題羅處士山舍', '春日題羅处士山舍', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["亂疊千峰掩翠微，高人愛此自忘機。","春風若埽階前地，便是山花帶錦飛。"]', '["亂叠千峰掩翠微，高人愛此自忘機。","春风若埽階前地，便是山花带錦飞。"]', '诗', 'shi', '', NULL, '春日題羅處士山舍 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa3624d-3b72-475c-9cbf-dc3a1d37e3c5', '訪松嶺徐鍊師', '訪松嶺徐鍊師', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["千仞峰頭一謫仙，何時種玉已成田？開經猶在松陰裏，讀到南華第幾篇。"]', '["千仞峰头一謫仙，何时種玉已成田？开經猶在松陰裏，读到南华第幾篇。"]', '诗', 'shi', '', NULL, '訪松嶺徐鍊師 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c4908d-4031-4c39-86be-9ae366e11a5e', '江南織綾詞', '江南织綾词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["卿卿買得越人絲，貪弄金梭嬾畫眉。","女伴能來看新𥷨，鴛鴦正欲上花枝。"]', '["卿卿買得越人絲，貪弄金梭嬾畫眉。","女伴能来看新𥷨，鴛鴦正欲上花枝。"]', '诗', 'shi', '', NULL, '江南織綾詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6c0e274-6067-467a-93ef-3b8fcaaf5afa', '宿蘭若', '宿蘭若', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["聽鐘投宿入孤煙，巖下病僧猶坐禪。","獨夜客心何處是，秋雲影裏一燈然。"]', '["听鐘投宿入孤煙，巖下病僧猶坐禪。","独夜客心何处是，秋云影裏一灯然。"]', '诗', 'shi', '', NULL, '宿蘭若 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c970c2-c95f-4040-af45-0ea89f1d5b19', '題禪僧院', '題禪僧院', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["棲禪枝畔數花新，飛作琉璃池上塵。","谷鳥自啼猨自呌，不能愁得定中人。"]', '["棲禪枝畔數花新，飞作琉璃池上塵。","谷鸟自啼猨自呌，不能愁得定中人。"]', '诗', 'shi', '', NULL, '題禪僧院 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0990c21-e4b8-4a34-81d2-23811bcdd1ca', '送絕粒僧', '送絕粒僧', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["碧洞青蘿不畏深，免將飢渴累禪心。","若期野客來相訪，一室無煙何處尋。"]', '["碧洞青蘿不畏深，免將飢渴累禪心。","若期野客来相訪，一室無煙何处尋。"]', '诗', 'shi', '', NULL, '送絕粒僧 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a16114-a074-419e-8ab6-ed58deded080', '早春游曲江', '早春游曲江', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["芳處亦將枯槁同，應緣遭化未施功。","羲和若擬動鑪鞴，先鑄曲江千樹紅。"]', '["芳处亦將枯槁同，應緣遭化未施功。","羲和若擬动鑪鞴，先鑄曲江千樹紅。"]', '诗', 'shi', '', NULL, '早春游曲江 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4541b61a-8fbe-4183-855d-edd0769eedcf', '佳人覽鏡', '佳人覽镜', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["每坐臺前見玉容，今朝不與昨朝同。","良人一夜出門宿，減却桃花一半紅。"]', '["每坐台前见玉容，今朝不與昨朝同。","良人一夜出门宿，減却桃花一半紅。"]', '诗', 'shi', '', NULL, '佳人覽鏡 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f107de5e-2a83-4703-be27-be868c35a96f', '遇王山人', '遇王山人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["每欲尋君千萬峰，豈知人世也相逢。","一瓢遺却在何處，應挂天台最老松。"]', '["每欲尋君千万峰，豈知人世也相逢。","一瓢遺却在何处，應挂天台最老松。"]', '诗', 'shi', '', NULL, '遇王山人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e13a382-6542-48d9-b0de-e55299a87070', '遇醉道士', '遇醉道士', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["霞帔尋常帶酒眠，路傍疑是酒中仙。","醉來不住人家宿，多向遠山松月邊。"]', '["霞帔尋常带酒眠，路傍疑是酒中仙。","醉来不住人家宿，多向远山松月邊。"]', '诗', 'shi', '', NULL, '遇醉道士 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6bc3e4b-f9b7-4739-a06b-53d1dd2d940d', '送人歸台州', '送人归台州', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["莫驅歸騎且徘徊，更遣離情四五桮。","醉後不憂迷客路，遙看瀑布識天台。"]', '["莫驱归騎且徘徊，更遣離情四五桮。","醉後不憂迷客路，遙看瀑布識天台。"]', '诗', 'shi', '', NULL, '送人歸台州 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('836b9fad-633e-4c30-8116-3edea8545daa', '贈施仙姑', '贈施仙姑', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["縹緲吾家一女仙，冰容雖小不知年。","有時頻夜看明月，心在嫦娥几案邊。"]', '["縹緲吾家一女仙，冰容雖小不知年。","有时頻夜看明月，心在嫦娥几案邊。"]', '诗', 'shi', '', NULL, '贈施仙姑 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5127a970-c181-4243-8446-e858346e1e67', '山院觀花', '山院观花', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["初來唯見空樹枝，今朝滿院花如雪。","門前爲報諸少年，明日來遲不堪折。"]', '["初来唯见空樹枝，今朝满院花如雪。","门前爲報諸少年，明日来遲不堪折。"]', '诗', 'shi', '', NULL, '山院觀花 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cb62e9d-7365-459d-aaea-450ded89d0f6', '經桃花夫人廟', '經桃花夫人廟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["誰能枉駕入荒榛，隨例形相土木身。","不及連山種桃樹，花開猶得識夫人。"]', '["誰能枉駕入荒榛，隨例形相土木身。","不及連山種桃樹，花开猶得識夫人。"]', '诗', 'shi', '', NULL, '經桃花夫人廟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04f37642-924d-4b6d-9054-3992554647c7', '代農叟吟', '代農叟吟', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["且將一笑悅豐年，漸老那能日日眠。","引客特來山地上，坐看秋水落紅蓮。"]', '["且將一笑悅豐年，漸老那能日日眠。","引客特来山地上，坐看秋水落紅蓮。"]', '诗', 'shi', '', NULL, '代農叟吟 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86001a9b-8dee-4f09-b7f0-9fbf765b7600', '下第春遊', '下第春游', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["羈情含蘖復含辛，淚眼看花只似塵。","天遣春風領春色，不教分付與愁人。"]', '["羈情含蘖复含辛，泪眼看花只似塵。","天遣春风領春色，不教分付與愁人。"]', '诗', 'shi', '', NULL, '下第春遊 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4231d07-fee5-47cd-91a7-5ff8177e9cc0', '送僧遊越', '送僧游越', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["麻衣年少雪爲顏，却笑孤雲未是閑。","此去若逢花柳月，棲禪莫向苧蘿山。"]', '["麻衣年少雪爲顏，却笑孤云未是闲。","此去若逢花柳月，棲禪莫向苧蘿山。"]', '诗', 'shi', '', NULL, '送僧遊越 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef42aa2-be0d-46e7-a150-58e7a711b3c1', '遇越州賀仲宣', '遇越州賀仲宣', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["君在鏡湖西畔住，四明山下莫經春。","門前幾箇采蓮女，欲泊蓮舟無主人。"]', '["君在镜湖西畔住，四明山下莫經春。","门前幾箇采蓮女，欲泊蓮舟無主人。"]', '诗', 'shi', '', NULL, '遇越州賀仲宣 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6daaee2a-4356-41e6-a6cc-2aa8e749fb37', '江南積雨歎', '江南積雨歎', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["人厭爲霖水毀溪，牀邊生菌路成泥。","雨師一日三回到，棟裏閑雲豈得棲。"]', '["人厭爲霖水毀溪，牀邊生菌路成泥。","雨師一日三回到，棟裏闲云豈得棲。"]', '诗', 'shi', '', NULL, '江南積雨歎 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b66f80f-9b47-472e-9685-ee18aa72835a', '雲中道上作', '云中道上作', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["羊馬羣中覓人道，鴈門關外絕人家。","昔時聞有雲中郡，今日無雲空見沙。"]', '["羊马羣中覓人道，鴈门关外絕人家。","昔时闻有云中郡，今日無云空见沙。"]', '诗', 'shi', '', NULL, '雲中道上作 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c6e30a-c36a-45bb-8838-2cceb53c534b', '同諸隱者夜登四明山', '同諸隐者夜登四明山', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["半夜尋幽上四明，手攀松桂觸雲行。","相呼已到無人境，何處玉簫吹一聲。"]', '["半夜尋幽上四明，手攀松桂觸云行。","相呼已到無人境，何处玉簫吹一声。"]', '诗', 'shi', '', NULL, '同諸隱者夜登四明山 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8de8174f-a2c4-4fa7-bf6a-9ca21cdd411f', '戲鄭申府', '戲鄭申府', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["年少鄭郎那解愁，春來閑臥酒家樓。","胡姬若擬邀他宿，挂却金鞭繫紫騮。"]', '["年少鄭郎那解愁，春来闲臥酒家楼。","胡姬若擬邀他宿，挂却金鞭繫紫騮。"]', '诗', 'shi', '', NULL, '戲鄭申府 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d1e5e18-57ba-4566-b71b-5808e0ecc718', '宿干越亭', '宿干越亭', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["琵琶洲上人行絕，干越亭中客思多。","月滿秋江山冷落，不知誰問夜如何。"]', '["琵琶洲上人行絕，干越亭中客思多。","月满秋江山冷落，不知誰问夜如何。"]', '诗', 'shi', '', NULL, '宿干越亭 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb46586f-797f-44de-9522-644aa13244ab', '少女詞二首 一', '少女词二首 一', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["嬌羞不肯點新黃，踏過金鈿出繡牀。","信物無端寄誰去，等閑裁破錦鴛鴦。"]', '["嬌羞不肯点新黄，踏過金鈿出繡牀。","信物無端寄誰去，等闲裁破錦鴛鴦。"]', '诗', 'shi', '', NULL, '少女詞二首 一 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5038998f-20a6-492c-b247-d698042a13dd', '少女詞二首 二', '少女词二首 二', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["同心帶裏脫金錢，買取頭花翠羽連。","手執木蘭猶未慣，今朝初上采菱船。"]', '["同心带裏脫金錢，買取头花翠羽連。","手執木蘭猶未慣，今朝初上采菱船。"]', '诗', 'shi', '', NULL, '少女詞二首 二 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d961175d-4727-494a-9643-c2d1a73aa061', '冬詞', '冬词', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["錦繡堆中臥初起，芙蓉面上粉猶殘。","臺前也欲梳雲髻，只怕盤龍手捻難。"]', '["錦繡堆中臥初起，芙蓉面上粉猶殘。","台前也欲梳云髻，只怕盤龙手捻难。"]', '诗', 'shi', '', NULL, '冬詞 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aca8ff15-1361-4c3c-8910-74efd08ba13c', '昭君怨', '昭君怨', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["馬上徒勞別恨深，總緣如玉不輸金。","已知賤妾無歸日，空荷君王有悔心。"]', '["马上徒勞別恨深，總緣如玉不輸金。","已知賤妾無归日，空荷君王有悔心。"]', '诗', 'shi', '', NULL, '昭君怨 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9da098c-d1b5-4288-9f2d-82334cad5bc0', '贈仙子', '贈仙子', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["欲令雪貌帶紅芳，更取金瓶瀉玉漿。","鳳管鶴聲來未足，嬾眠秋月憶蕭郎。"]', '["欲令雪貌带紅芳，更取金瓶瀉玉漿。","鳳管鹤声来未足，嬾眠秋月憶蕭郎。"]', '诗', 'shi', '', NULL, '贈仙子 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc9e291-65f6-4824-b7ad-444a85bb77da', '越溪懷古', '越溪懷古', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["憶昔西施人未求，浣紗曾向此溪頭。","一朝得侍君王側，不見玉顏空水流。"]', '["憶昔西施人未求，浣紗曾向此溪头。","一朝得侍君王側，不见玉顏空水流。"]', '诗', 'shi', '', NULL, '越溪懷古 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d970bea0-3ed7-4783-b803-6a8d0b6b87bf', '秋夜山中贈別友人', '秋夜山中贈別友人', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["何處邀君話別情，寒山木落月華清。","莫愁今夜無詩思，已聽秋猨第一聲。"]', '["何处邀君話別情，寒山木落月华清。","莫愁今夜無诗思，已听秋猨第一声。"]', '诗', 'shi', '', NULL, '秋夜山中贈別友人 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170155ec-15c9-4b3f-aca1-6ff99583e834', '大堤新詠', '大堤新詠', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["行路少年知不知，襄陽全欠舊來時。","宜城賈客載錢出，始覺大堤無女兒。"]', '["行路少年知不知，襄陽全欠旧来时。","宜城賈客載錢出，始覺大堤無女兒。"]', '诗', 'shi', '', NULL, '大堤新詠 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('528c3fdb-defd-4d3a-81b6-696363540070', '宿四明山', '宿四明山', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["黎洲老人命余宿，杳然高頂浮雲平。","下視不知幾千仞，欲曉不曉天雞聲。"]', '["黎洲老人命余宿，杳然高頂浮云平。","下視不知幾千仞，欲晓不晓天雞声。"]', '诗', 'shi', '', NULL, '宿四明山 施肩吾 shi');
